/* Copy-and-patch loop JIT (x86-64 Linux).
 *
 * A hot loop (a backward jump taken often) is compiled from the pristine bytecode into one region of machine code. The
 * code is stitched together from pre-assembled stencils (jit/stencils.S -> jit/stencils.h): each stencil is memcpy'd and
 * its holes (slot offsets, immediates, branch targets) are patched. The compiler tracks, per variable, a type (int /
 * float / bool / array) that is checked once on region entry, so typed code needs no per-operation tag checks; values
 * of unknown type (array elements) are guarded where they are used.
 *
 * The region works on the real frame and the real operand stack, so leaving it is trivial: every exit just returns an
 * (pc, depth) pair and the interpreter carries on at that instruction. Anything the stencils do not handle exactly as
 * the interpreter does (overflow, division by zero, an out-of-range index, a type that differs from the expected one,
 * an exhausted step budget) is such an exit taken *before* the instruction has any effect, so the interpreter simply
 * re-executes it. Semantics are therefore the interpreter's by construction; `make test-jit` runs the whole suite with
 * a hot threshold of 1 to check that. Regions contain no calls, allocation or GC points. */
#define _GNU_SOURCE
#include "../sp.h"

#if !SP_JIT

int jit_site(VM *vm, Proto *p, const uint8_t *hdr, SpValue *base, SpValue *sp) {
    (void)vm; (void)p; (void)hdr; (void)base; (void)sp;
    return 0;
}
JitUnit *jit_call_hot(VM *vm, SFunc *fn, SpValue *base) {
    (void)vm; (void)fn; (void)base;
    return NULL;
}
void jit_run(VM *vm, JitUnit *u, SpValue *base) { (void)vm; (void)u; (void)base; }
void jit_free_proto(Proto *p) { (void)p; }
void jit_roots(Proto *p, void (*mark)(VM *, SpValue), VM *vm) { (void)p; (void)mark; (void)vm; }
void jit_configure(VM *vm) { vm->jit_on = 0; }

#else

#include <math.h>
#include <stddef.h>
#include <sys/mman.h>
#include <unistd.h>
#include "jit/layout.h"
#include "jit/stencils.h"

/* stencils.S hard-codes these offsets (generated by tools/jitlayout.c): a layout change needs `make jit-regen` */
_Static_assert(L_FRAME == sizeof(Frame) && L_FR_FN == offsetof(Frame, fn) && L_FR_PC == offsetof(Frame, pc) &&
               L_FR_BASE == offsetof(Frame, base) && L_FR_KIND == offsetof(Frame, kind) &&
               L_FR_DBASE == offsetof(Frame, dbase) && L_FR_UEV == offsetof(Frame, uev), "Frame layout");
_Static_assert(L_VM_SLOTS == offsetof(VM, slots) && L_VM_ILEFT == offsetof(VM, ileft) &&
               L_VM_NFRAMES == offsetof(VM, nframes) && L_VM_STACK_END == offsetof(VM, stack_end) &&
               L_VM_NDR == offsetof(VM, ndr) && L_VM_JCUR == offsetof(VM, jit_cur) &&
               L_VM_JRSP == offsetof(VM, jit_rsp) && L_VM_JFMAX == offsetof(VM, jit_fmax), "VM layout");
_Static_assert(L_JU_PROTO == offsetof(JitUnit, proto) && L_PROTO_CODE == offsetof(Proto, code), "JIT layout 2");
_Static_assert(L_VM_SP == offsetof(VM, sp) && L_VM_JNEW == offsetof(VM, jit_new), "VM layout 2");
_Static_assert(L_CLS_NF == offsetof(SClass, nfields) && L_CLS_DFLT == offsetof(SClass, dflt) && L_INST_NSLOTS == offsetof(SInstance, nslots) &&
               L_VM_BYTES == offsetof(VM, bytes) && L_VM_GCNEXT == offsetof(VM, gc_next) && L_VM_OBJS == offsetof(VM, objs) &&
               L_VM_NEXTID == offsetof(VM, next_id) && L_VM_POOLFREE == offsetof(VM, pool_free) &&
               L_VM_MAXHEAP == offsetof(VM, lim) + offsetof(Limits, max_heap_bytes) && L_INST_SLOTS == 32 &&
               offsetof(Obj, next) == 8 && offsetof(Obj, id) == 4, "instance allocation layout");
_Static_assert(L_INST_CLS == offsetof(SInstance, cls) && L_INST_SLOTS == offsetof(SInstance, slots) &&
               L_SFUNC_PROTO == offsetof(SFunc, proto) && L_SFUNC_UP == offsetof(SFunc, up) &&
               L_CELL_V == offsetof(SCell, v) && L_PROTO_JUNIT == offsetof(Proto, junit) &&
               L_JU_ENTRY == offsetof(JitUnit, entry) && L_JU_KT == offsetof(JitUnit, kt) &&
               L_JU_CODE == offsetof(JitUnit, code) && L_JU_NPARAMS == offsetof(JitUnit, nparams) &&
               L_JU_NLOCALS == offsetof(JitUnit, nlocals) && L_JU_NEED == offsetof(JitUnit, need), "JIT layout");

enum { TY_UNK = 0, TY_INT, TY_FLT, TY_BOOL, TY_ARR, TY_MOD, TY_INST };   /* TY_INST: an instance of vk[var] / Ent.cls */
enum { EK_MEM = 0, EK_LOC, EK_K, EK_MOD, EK_REG };   /* EK_REG: a typed value held in a machine register (ty INT/ARR/INST: payload in a GPR, FLT: in an xmm) */
enum { MAXMV = 24, MAXEXTRA = 256, MAXFIX = 1 << 16 };
enum { JS_NEW = 0, JS_OK, JS_FAIL };

typedef struct { uint32_t pc; int depth; int ictx; } JExit;   /* ictx: 0, or 1 + the inlined call the exit lies in */
typedef struct { Proto *proto; uint32_t retpc; int base_slots; int ctor; int parent; } JIctx;   /* an inlined callee: resume pc of the caller, callee base in slots */
typedef struct JRegion {
    uint32_t hdr;
    int state;
    int cnt;
    int d0;
    int (*fn)(VM *, SpValue *, const SpValue *, Frame *);
    void *mem;
    size_t msize;
    SpValue *kt;
    JExit *exits;
    int nexits;
    JIctx *ictx;
    int nictx;
    int unit;                /* a whole function (hdr = 0) rather than a loop */
    int nent;                /* loop regions: entries and the steps they ran (a region that is left at once is dropped) */
    uint64_t work;
    int64_t inl_extent;      /* loop regions: bytes above the frame base that inlined calls use (0: none), checked at entry */
    int oks, fails;          /* units: normal returns / entry-guard failures of the outermost call */
    int nk0, nk;             /* kt[nk0..nk): objects the code refers to (classes, methods), kept alive by the GC */
    JitUnit u;
    Proto *proto;
} JRegion;
struct JitProto {
    JRegion **r;
    int n, cap, nok;
    JRegion *unit;
};

/* allocation for compiled code: the collection the interpreter would run before NEW_INSTANCE, then the instance with
 * its default slot values (vm->sp has been set to the top of the live stack) */
static void *jit_new_inst(VM *vm, SClass *k) {
    if (vm->bytes >= vm->gc_next) vm_gc(vm);
    SInstance *ci = vm_new_instance(vm, k);
    if (k->dflt)
        for (int i = 0; i < ci->nslots; i++) ci->slots[i] = k->dflt[i];
    return ci;
}

static SpValue g_hint_int;   /* "probably an int": the guess for the result of a call */

void jit_configure(VM *vm) {
    vm->jit_on = 1;
    vm->jit_thresh = 40;
    vm->jit_dbg = 0;
    const char *e = getenv("SPRINT_JIT");
    if (e && e[0] == '0') vm->jit_on = 0;
    e = getenv("SPRINT_JIT_THRESHOLD");
    if (e && atoi(e) > 0) vm->jit_thresh = atoi(e);
    e = getenv("SPRINT_JIT_DEBUG");
    if (e && e[0] >= '1') vm->jit_dbg = e[0] - '0';
    g_hint_int = v_int(0);
    vm->jit_cur = NULL;
    vm->jit_rsp = NULL;
    vm->jit_fmax = 0;
    vm->jit_new = jit_new_inst;
}

static void region_free(JRegion *r) {
    if (!r) return;
    if (r->mem) munmap(r->mem, r->msize);
    free(r->kt);
    free(r->exits);
    free(r->ictx);
    free(r);
}

void jit_roots(Proto *p, void (*mark)(VM *, SpValue), VM *vm) {
    const struct JitProto *jp = p->jit;
    if (!jp) return;
    for (int i = 0; i <= jp->n; i++) {
        const JRegion *r = i < jp->n ? jp->r[i] : jp->unit;
        if (!r || !r->kt) continue;
        for (int k = r->nk0; k < r->nk; k++) mark(vm, r->kt[k]);
    }
}

void jit_free_proto(Proto *p) {
    struct JitProto *jp = p->jit;
    if (!jp) return;
    for (int i = 0; i < jp->n; i++) region_free(jp->r[i]);
    region_free(jp->unit);
    free(jp->r);
    free(jp);
    p->jit = NULL;
    p->junit = NULL;
}

/* ------------------------------------------------------------------ */
/* compiler state                                                      */
/* ------------------------------------------------------------------ */
typedef struct { uint8_t kind, ty; int idx; uint32_t ppc; const SpValue *hint; const SClass *cls; } Ent;
typedef struct { uint32_t pos; int kind, target, addend; } Fix;

typedef struct {
    VM *vm;
    Proto *p;
    SFunc *fn;                           /* the closure being compiled for (upvalue hints), may be NULL */
    int unit;                            /* compiling a whole function */
    JRegion *region;
    const uint8_t *code;
    uint32_t hdr, end;
    int nloc, d0, nvars, nmv, mslot[MAXMV];
    SpValue *base;
    uint8_t *vt, *vlive;                 /* current variable states (type | 0x80 = defined); read-before-write marks */
    const SClass **vk;                   /* class of a variable whose type is TY_INST (fixed once chosen) */
    uint8_t *lt, *lvalid;                /* per-leader variable states */
    uint8_t *ldep;                       /* per-leader stack depth above d0 (0xff: not yet known); the values are in memory at a join */
    int *lmap, nl;                       /* pc - hdr -> leader index or -1 */
    uint8_t *isins;                      /* pc - hdr -> instruction start */
    Ent *st;
    int dep, stcap;
    uint8_t *cb;
    size_t cn, ccap;
    Fix *fx;
    int nfx, capfx;
    uint32_t *pcaddr;
    JExit *ex;
    int nex, capex;
    JIctx *ic;                           /* inlined calls seen so far (exit contexts) */
    int64_t inl_extent;                  /* loop regions: the highest byte above r12 an inlined call reaches */
    int nest;                            /* inlined calls the translated code is inside of (0: the region itself) */
    int nic, capic, cur_ic;              /* cur_ic: 0, or 1 + the inlined call being translated */
    int32_t bias;                        /* byte offset of the translated frame's base from r12 */
    int pos0;                            /* index in st[] of the translated frame's stack bottom */
    SpValue *kt;
    int nk, nk0, capk;
    int tk, tt, xe;                      /* branch / guard target for the next stencil */
    int pin;                             /* local mirrored in rbp (payload word; memory stays authoritative), or -1 */
    int pin_fuse;                        /* fuse_store may write straight into the pinned local (only int arithmetic syncs rbp) */
    int reg_on;                          /* register temporaries enabled (SPRINT_JIT_REGS=0 turns them off) */
    struct { int k, reg, x, up, ty; } lc[8];     /* locals whose payload is also held in a register (memory stays authoritative: write-through) */
    int nlc;
    uint8_t *lrd;                        /* reads of each local in the region (hot ones are worth a register) */
    int rb, xb;                          /* machine registers holding EK_REG entries (bit masks: GPR number / xmm number) */
    int32_t xmm_off;                     /* frame offset whose float payload xmm0 holds right now (-1: none) */
    int skipx;                           /* the next stencil may drop its leading "movsd H1+8(%r12),%xmm0" */
    int32_t rax_off;                     /* frame offset whose int payload rax holds right now (-1: none) */
    int skip1;                           /* the next stencil may drop its leading "mov H1+8(%r12),%rax" */
    int32_t h5;                          /* sixth hole of the next stencil (consumed by em) */
    uint64_t hq2;                        /* second 64-bit hole of the next stencil (consumed by em) */
    uint32_t cur_pc;
    int32_t rstep_imm[256];
    uint8_t rstep[256];                  /* per range-loop state slot: 1/2 = the step is a constant > 0 / < 0, 3 = not constant (set by RANGE_PREP); 0 = no RANGE_PREP seen in the region */
    uint8_t eg[256];                     /* range slots whose step is checked against egv[] when the region is entered */
    int32_t egv[256];
    int changed;
    const char *why;
    char whybuf[48];
} JC;

static unsigned rd16(const uint8_t *p) { return (unsigned)p[0] | ((unsigned)p[1] << 8); }
static int32_t rd32s(const uint8_t *p) {
    return (int32_t)((uint32_t)p[0] | ((uint32_t)p[1] << 8) | ((uint32_t)p[2] << 16) | ((uint32_t)p[3] << 24));
}

#define FAIL(w) do { if (!c->why) c->why = (w); return 0; } while (0)

static int ty_of(const SpValue *v, int allow_mod) {
    switch (v->type) {
    case T_INT: return TY_INT;
    case T_FLOAT: return TY_FLT;
    case T_BOOL: return TY_BOOL;
    case T_ARRAY: return TY_ARR;
    case T_MODULE: return allow_mod ? TY_MOD : TY_UNK;
    default: return TY_UNK;
    }
}
static uint64_t tag_of(int ty) {
    switch (ty) {
    case TY_INT: return T_INT;
    case TY_FLT: return T_FLOAT;
    case TY_BOOL: return T_BOOL;
    case TY_ARR: return T_ARRAY;
    case TY_INST: return T_INSTANCE;
    default: return T_MODULE;
    }
}

/* ---- emission ---- */
static int cb_room(JC *c, size_t n) {
    if (c->cn + n <= c->ccap) return 1;
    size_t nc = c->ccap ? c->ccap * 2 : 4096;
    while (nc < c->cn + n) nc *= 2;
    uint8_t *t = realloc(c->cb, nc);
    if (!t) return 0;
    c->cb = t;
    c->ccap = nc;
    return 1;
}

static int addfix(JC *c, uint32_t pos, int kind, int target, int addend) {
    if (c->nfx == c->capfx) {
        if (c->capfx >= MAXFIX) return 0;
        int nc = c->capfx ? c->capfx * 2 : 256;
        Fix *t = realloc(c->fx, (size_t)nc * sizeof *t);
        if (!t) return 0;
        c->fx = t;
        c->capfx = nc;
    }
    c->fx[c->nfx++] = (Fix){pos, kind, target, addend};
    return 1;
}

static int em(JC *c, int sid, int32_t h0, int32_t h1, int32_t h2, int32_t h3, int32_t h4, uint64_t hq) {
    const JStencil *s = &jst_tab[sid];
    if (!cb_room(c, s->len)) { if (!c->why) c->why = "out of memory"; return 0; }
    uint8_t *d = c->cb + c->cn;
    const uint8_t *src = jst_code + s->off;
    uint32_t slen = s->len, cut = 0;
    if (c->skip1 && slen > 8 && src[0] == 0x49 && src[1] == 0x8b && src[2] == 0x84 && src[3] == 0x24) {
        for (uint32_t i = 0; i < s->nrel; i++)
            if (jst_rel[s->rel0 + i].at == 4 && jst_rel[s->rel0 + i].hole == HOLE_H1) cut = 8;
        if (cut) {                                  /* rax already holds the operand */
            src += 8;
            slen -= 8;
        }
    }
    c->skip1 = 0;
    if (c->skipx && !cut && slen > 10 && src[0] == 0xf2 && src[1] == 0x41 && src[2] == 0x0f && src[3] == 0x10 && src[4] == 0x84 && src[5] == 0x24) {
        for (uint32_t i = 0; i < s->nrel; i++)
            if (jst_rel[s->rel0 + i].at == 6 && jst_rel[s->rel0 + i].hole == HOLE_H1) cut = 10;
        if (cut) {                                  /* xmm0 already holds the operand */
            src += 10;
            slen -= 10;
        }
    }
    c->skipx = 0;
    memcpy(d, src, slen);
    int32_t hv[6] = {h0, h1, h2, h3, h4, c->h5};
    c->h5 = 0;
    uint64_t hq2 = c->hq2;
    c->hq2 = 0;
    for (uint32_t i = 0; i < s->nrel; i++) {
        JReloc rl = jst_rel[s->rel0 + i];
        if (rl.at < cut) continue;
        rl.at = (uint16_t)(rl.at - cut);
        const JReloc *r = &rl;
        if (r->hole <= HOLE_H5) {
            int32_t v = hv[r->hole] + r->addend;
            memcpy(d + r->at, &v, 4);
        } else if (r->hole == HOLE_HQ || r->hole == HOLE_HQ2) {
            uint64_t v = (r->hole == HOLE_HQ ? hq : hq2) + (uint64_t)(int64_t)r->addend;
            memcpy(d + r->at, &v, 8);
        } else if (r->hole == HOLE_T) {
            if (!addfix(c, (uint32_t)c->cn + r->at, c->tk, c->tt, r->addend)) { c->why = "too many branches"; return 0; }
        } else {
            if (c->xe < 0) { c->why = "internal: guard without exit"; return 0; }
            if (!addfix(c, (uint32_t)c->cn + r->at, 1, c->xe, r->addend)) { c->why = "too many branches"; return 0; }
        }
    }
    c->cn += slen;
    c->rax_off = -1;
    c->xmm_off = -1;
    return 1;
}
#define EM(...) do { if (!em(c, __VA_ARGS__)) return 0; } while (0)

static int exit_for(JC *c, uint32_t pc, int depth) {
    depth -= c->pos0;
    for (int i = 0; i < c->nex; i++) if (c->ex[i].pc == pc && c->ex[i].depth == depth && c->ex[i].ictx == c->cur_ic) return i;
    if (c->nex == c->capex) {
        int nc = c->capex ? c->capex * 2 : 32;
        JExit *t = realloc(c->ex, (size_t)nc * sizeof *t);
        if (!t) return -1;
        c->ex = t;
        c->capex = nc;
    }
    c->ex[c->nex] = (JExit){pc, depth, c->cur_ic};
    return c->nex++;
}

/* where the interpreter must resume if a guard of the current instruction fails: at the earliest still-pending push
 * (everything after it is re-executed and only pure), else at the current instruction */
static int gexit(JC *c) {
    for (int i = c->pos0; i < c->dep; i++)
        if (c->st[i].kind != EK_MEM) return exit_for(c, c->st[i].ppc, i);
    return exit_for(c, c->cur_pc, c->dep);
}

static int kadd(JC *c, SpValue v) {
    for (int i = c->nk0; i < c->nk; i++)
        if (c->kt[i].w == v.w && c->kt[i].as.i == v.as.i) return i;
    if (c->nk >= c->capk) return -1;
    c->kt[c->nk] = v;
    return c->nk++;
}

/* ---- stack model ---- */
static int32_t koff(int idx) { return idx * 16; }
#define LOFF(c, i) ((c)->bias + (int32_t)(i) * 16)
static int32_t soff(const JC *c, int pos) { return (c)->bias + (c->nloc + pos - c->pos0) * 16; }
/* byte offset of a register operand (local or materialised stack slot) */
static int32_t roff(const JC *c, const Ent *e, int pos) { return e->kind == EK_LOC ? LOFF(c, e->idx) : soff(c, pos); }

static Ent *push(JC *c, int kind, int ty, int idx) {
    if (c->dep >= c->stcap) { c->why = "stack overflow"; return NULL; }
    Ent *e = &c->st[c->dep++];
    e->kind = (uint8_t)kind;
    e->ty = (uint8_t)ty;
    e->idx = idx;
    e->ppc = c->cur_pc;
    e->hint = NULL;
    e->cls = NULL;
    return e;
}


/* ---- machine-register temporaries ------------------------------------------------------------------------------
 * A pure value (a field, an array element, the result of + - *) whose type is known can stay in a register instead of
 * a 16-byte stack slot. Such an entry is "pending" like a local or constant: the interpreter-resume point of a guard
 * is the earliest pending entry, which replays the whole pure chain, so exits never need to know the registers.
 * Only the handlers that understand EK_REG see one; every other instruction first writes them back (flush_regs).
 * Registers used: rsi rdi r8 r9 r10 r11 and xmm1..xmm7 (the stencils the reg-aware handlers may still emit - tag and
 * class guards, mov of a local - only use rax rcx rdx). rax rcx rdx xmm0 are scratch here. */
enum { R_R12 = 12, R_R13 = 13, R_R14 = 14, R_R15 = 15, R_RAX = 0, R_RCX = 1, R_RDX = 2, R_RBP = 5, R_RSI = 6, R_RDI = 7 };
static const int gpool[6] = {6, 7, 8, 9, 10, 11};

static int xput(JC *c, const uint8_t *b, size_t n) {
    if (!cb_room(c, n)) { if (!c->why) c->why = "out of memory"; return 0; }
    memcpy(c->cb + c->cn, b, n);
    c->cn += n;
    c->rax_off = -1;
    c->xmm_off = -1;
    c->skip1 = 0;
    c->skipx = 0;
    return 1;
}
/* [legacy prefix] [REX] opcode [0F-escape second byte] modrm [sib] disp32 : reg field `reg`, memory operand [base+disp] */
static int x_mem(JC *c, int pfx, int w, int op1, int op2, int reg, int base, int32_t disp) {
    uint8_t b[16];
    size_t n = 0;
    if (pfx) b[n++] = (uint8_t)pfx;
    int rex = 0x40 | (w ? 8 : 0) | (((reg >> 3) & 1) << 2) | ((base >> 3) & 1);
    if (rex != 0x40) b[n++] = (uint8_t)rex;
    b[n++] = (uint8_t)op1;
    if (op2 >= 0) b[n++] = (uint8_t)op2;
    b[n++] = (uint8_t)(0x80 | ((reg & 7) << 3) | (base & 7));
    if ((base & 7) == 4) b[n++] = 0x24;
    memcpy(b + n, &disp, 4);
    n += 4;
    return xput(c, b, n);
}
static int x_rr(JC *c, int pfx, int w, int op1, int op2, int reg, int rm) {
    uint8_t b[8];
    size_t n = 0;
    if (pfx) b[n++] = (uint8_t)pfx;
    int rex = 0x40 | (w ? 8 : 0) | (((reg >> 3) & 1) << 2) | ((rm >> 3) & 1);
    if (rex != 0x40) b[n++] = (uint8_t)rex;
    b[n++] = (uint8_t)op1;
    if (op2 >= 0) b[n++] = (uint8_t)op2;
    b[n++] = (uint8_t)(0xc0 | ((reg & 7) << 3) | (rm & 7));
    return xput(c, b, n);
}
static int x_imm32(JC *c, int32_t v) { uint8_t b[4]; memcpy(b, &v, 4); return xput(c, b, 4); }
/* mov r, [base+d] / mov [base+d], r / mov r, r / mov qword [base+d], imm32 / mov r, imm */
static int x_ld(JC *c, int r, int base, int32_t d) { return x_mem(c, 0, 1, 0x8b, -1, r, base, d); }
static int x_st(JC *c, int base, int32_t d, int r) { return x_mem(c, 0, 1, 0x89, -1, r, base, d); }
static int x_mov(JC *c, int dst, int src) { return x_rr(c, 0, 1, 0x8b, -1, dst, src); }
static int x_sti(JC *c, int base, int32_t d, int32_t v) { return x_mem(c, 0, 1, 0xc7, -1, 0, base, d) && x_imm32(c, v); }
static int x_movi(JC *c, int r, int64_t v) {
    if (v >= INT32_MIN && v <= INT32_MAX) return x_rr(c, 0, 1, 0xc7, -1, 0, r) && x_imm32(c, (int32_t)v);
    uint8_t b[10];
    b[0] = (uint8_t)(0x48 | ((r >> 3) & 1));
    b[1] = (uint8_t)(0xb8 | (r & 7));
    memcpy(b + 2, &v, 8);
    return xput(c, b, 10);
}
/* cmp qword [base+d], imm32 */
static int x_cmpi(JC *c, int base, int32_t d, int32_t v) { return x_mem(c, 0, 1, 0x81, -1, 7, base, d) && x_imm32(c, v); }
/* jcc rel32 to the exit stub `xe` (cc: 0 jo, 3 jae, 5 jne, 6 jbe) */
static int x_jx(JC *c, int cc, int xe) {
    if (xe < 0) { c->why = "internal: guard without exit"; return 0; }
    uint8_t b[6] = {0x0f, (uint8_t)(0x80 | cc), 0, 0, 0, 0};
    uint32_t at = (uint32_t)c->cn + 2;
    if (!xput(c, b, 6)) return 0;
    if (!addfix(c, at, 1, xe, -4)) { c->why = "too many branches"; return 0; }
    return 1;
}
/* jcc rel32 to the branch target chosen by set_target (c->tk / c->tt) */
static int x_jt(JC *c, int cc) {
    uint8_t b[6] = {0x0f, (uint8_t)(0x80 | cc), 0, 0, 0, 0};
    uint32_t at = (uint32_t)c->cn + 2;
    if (!xput(c, b, 6)) return 0;
    if (!addfix(c, at, c->tk, c->tt, -4)) { c->why = "too many branches"; return 0; }
    return 1;
}
/* SSE scalar double: movsd xmm,[m] / movsd [m],xmm / op xmm,xmm / op xmm,[m] / cvtsi2sd xmm,r64 / cvtsi2sd xmm,[m] */
static int x_sd_ld(JC *c, int x, int base, int32_t d) { return x_mem(c, 0xf2, 0, 0x0f, 0x10, x, base, d); }
static int x_sd_st(JC *c, int base, int32_t d, int x) { return x_mem(c, 0xf2, 0, 0x0f, 0x11, x, base, d); }
static int x_sd_rr(JC *c, int op2, int x, int y) { return x_rr(c, 0xf2, 0, 0x0f, op2, x, y); }
static int x_sd_rm(JC *c, int op2, int x, int base, int32_t d) { return x_mem(c, 0xf2, 0, 0x0f, op2, x, base, d); }

/* payload of the (non-register) operand e at stack position pos into GPR rd; a pinned local comes from its rbp mirror */
static int x_ldop(JC *c, int rd, const Ent *e, int pos) {
    if (e->kind == EK_LOC && e->idx == c->pin) return x_mov(c, rd, R_RBP);
    return x_ld(c, rd, R_R12, roff(c, e, pos) + 8);
}
static int reg_get(JC *c, int xmm) {
    if (xmm) {
        for (int i = 1; i <= 7; i++) if (!((c->xb >> i) & 1)) { c->xb |= 1 << i; return i; }
        return -1;
    }
    for (int i = 0; i < 6; i++) if (!((c->rb >> gpool[i]) & 1)) { c->rb |= 1 << gpool[i]; return gpool[i]; }
    return -1;
}
static void reg_put(JC *c, int xmm, int r) {
    if (xmm) c->xb &= ~(1 << r); else c->rb &= ~(1 << r);
}
static int reg_is_x(const Ent *e) { return e->ty == TY_FLT; }

/* write one register entry back into its stack slot (tag and payload) */
static int reg_spill(JC *c, int pos) {
    Ent *e = &c->st[pos];
    int32_t so = soff(c, pos);
    int ok = x_sti(c, R_R12, so, (int32_t)tag_of(e->ty));
    if (ok) ok = reg_is_x(e) ? x_sd_st(c, R_R12, so + 8, e->idx) : x_st(c, R_R12, so + 8, e->idx);
    reg_put(c, reg_is_x(e), e->idx);
    e->kind = EK_MEM;
    return ok;
}
static int flush_regs(JC *c) {
    if (!c->rb && !c->xb) return 1;
    if (c->vm->jit_dbg > 2) (void)fprintf(stderr, "jit: flush regs at op 0x%02x\n", (unsigned)c->code[c->cur_pc]);
    for (int i = c->pos0; i < c->dep; i++) if (c->st[i].kind == EK_REG && !reg_spill(c, i)) return 0;
    c->rb = c->xb = 0; c->nlc = 0;
    return 1;
}
/* mirrors of an inlined body's locals live in the same table under keys of their own (one range per inlined call) */
static int lc_key(const JC *c, int k) { return c->cur_ic ? k + 1000 * c->cur_ic : k; }
static int lc_find(const JC *c, int k, int x) {
    k = lc_key(c, k);
    for (int i = 0; i < c->nlc; i++) if (!c->lc[i].up && c->lc[i].k == k && c->lc[i].x == x) return c->lc[i].reg;
    return -1;
}
static void lc_drop(JC *c, int k) {
    k = lc_key(c, k);
    for (int i = 0; i < c->nlc;) {
        if (!c->lc[i].up && c->lc[i].k == k) { reg_put(c, c->lc[i].x, c->lc[i].reg); c->lc[i] = c->lc[--c->nlc]; }
        else i++;
    }
}
static int lc_evict(JC *c, int x) {
    for (int i = 0; i < c->nlc; i++)
        if (c->lc[i].x == x) { reg_put(c, x, c->lc[i].reg); c->lc[i] = c->lc[--c->nlc]; return 1; }
    return 0;
}
/* the register (already marked busy) now also mirrors local k */
static void lc_add(JC *c, int k, int x, int reg) {
    k = lc_key(c, k);
    if (c->nlc == 8) { reg_put(c, c->lc[0].x, c->lc[0].reg); c->lc[0] = c->lc[--c->nlc]; }
    c->lc[c->nlc].k = k; c->lc[c->nlc].reg = reg; c->lc[c->nlc].x = x; c->lc[c->nlc].up = 0; c->lc[c->nlc].ty = 0;
    c->nlc++;
}
/* mirrors of closure variables (the payload of upvalue idx, whose type is known: guarded when loaded, or just stored). The
 * cell stays authoritative. They die at every store through any upvalue (two closures may share a cell) and when an
 * inlined body is entered or left (another closure). */
static int lc_find_up(const JC *c, int idx, int x, int ty) {
    for (int i = 0; i < c->nlc; i++)
        if (c->lc[i].up == 1 && c->lc[i].k == idx && c->lc[i].x == x && c->lc[i].ty == ty) return c->lc[i].reg;
    return -1;
}
static void lc_drop_up_kind(JC *c, int cells) {
    for (int i = 0; i < c->nlc;) {
        if (c->lc[i].up == 1 || (cells && c->lc[i].up == 2)) { reg_put(c, c->lc[i].x, c->lc[i].reg); c->lc[i] = c->lc[--c->nlc]; }
        else i++;
    }
}
static void lc_drop_up(JC *c) { lc_drop_up_kind(c, 0); }              /* the values (a store changed the cell) */
static void lc_add_up(JC *c, int idx, int x, int reg, int ty) {
    if (c->nlc == 8) { reg_put(c, c->lc[0].x, c->lc[0].reg); c->lc[0] = c->lc[--c->nlc]; }
    c->lc[c->nlc].k = idx; c->lc[c->nlc].reg = reg; c->lc[c->nlc].x = x; c->lc[c->nlc].up = 1; c->lc[c->nlc].ty = ty;
    c->nlc++;
}
/* the inlined body is over: its locals are dead, so their mirrors give their registers back */
static void lc_drop_scope(JC *c) {
    int lo = 1000 * c->cur_ic;
    for (int i = 0; i < c->nlc;) {
        if (!c->lc[i].up && c->lc[i].k >= lo) { reg_put(c, c->lc[i].x, c->lc[i].reg); c->lc[i] = c->lc[--c->nlc]; }
        else i++;
    }
}
static int lc_ok(const JC *c, int k) { return c->lrd &&  k >= 0 && k < c->nloc && k != c->pin; }
/* register holding the payload of local operand e (class x): its mirror, or a fresh one loaded now when the local is read
 * repeatedly; -1: use the memory operand, -2: emission failed */
static int lc_src(JC *c, const Ent *e, int x) {
    if (e->kind != EK_LOC || !lc_ok(c, e->idx)) return -1;
    int r = lc_find(c, e->idx, x);
    if (r >= 0) return r;
    if (c->lrd[e->idx] < 2) return -1;
    r = reg_get(c, x);
    if (r < 0) return -1;
    int ok = x ? x_sd_ld(c, r, R_R12, LOFF(c, e->idx) + 8) : x_ld(c, r, R_R12, LOFF(c, e->idx) + 8);
    if (!ok) return -2;
    lc_add(c, e->idx, x, r);
    return r;
}
/* a free register of the class, spilling the lowest register entry of that class when none is left (never positions
 * keep1 / keep2: operands of the instruction being translated) */
static int reg_alloc(JC *c, int xmm, int keep1, int keep2) {
    int r = reg_get(c, xmm);
    if (r >= 0) return r;
    if (lc_evict(c, xmm)) return reg_get(c, xmm);
    for (int i = c->pos0; i < c->dep; i++) {
        Ent *e = &c->st[i];
        if (e->kind != EK_REG || reg_is_x(e) != xmm || i == keep1 || i == keep2) continue;
        if (!reg_spill(c, i)) return -1;
        return reg_get(c, xmm);
    }
    return -1;
}

static int materialize(JC *c, int pos) {
    Ent *e = &c->st[pos];
    c->xe = -1;
    if (e->kind == EK_REG) return reg_spill(c, pos);
    if (e->kind == EK_LOC) EM(ST_mov, soff(c, pos), LOFF(c, e->idx), 0, 0, 0, 0);
    else if (e->kind == EK_K) EM(ST_movk, soff(c, pos), koff(e->idx), 0, 0, 0, 0);
    else if (e->kind == EK_MOD) EM(ST_ldmod, soff(c, pos), 0, c->mslot[e->idx] * 16, 0, 0, 0);
    e->kind = EK_MEM;
    return 1;
}
static int flush_from(JC *c, int lo, int hi) {
    for (int i = lo; i < hi; i++) if (c->st[i].kind != EK_MEM && !materialize(c, i)) return 0;
    return 1;
}

static int mvar(JC *c, int slot) {
    for (int i = 0; i < c->nmv; i++) if (c->mslot[i] == slot) return c->nloc + i;
    return -1;
}

/* make the entry at pos have type `want`, emitting a tag guard when it is not known */
static int need(JC *c, int pos, int want) {
    Ent *e = &c->st[pos];
    if (e->ty == want) return 1;
    if (e->ty != TY_UNK || e->kind == EK_K || e->kind == EK_MOD) return 0;
    int x = gexit(c);
    if (x < 0) FAIL("out of memory");
    c->xe = x;
    EM(ST_gtag, roff(c, e, pos), (int32_t)tag_of(want), 0, 0, 0, 0);
    e->ty = (uint8_t)want;
    if (e->kind == EK_LOC) c->vt[e->idx] = (uint8_t)((c->vt[e->idx] & 0x80) | want);
    return 1;
}

static int hint_ty(const SpValue *h) {
    if (!h) return TY_UNK;
    int t = ty_of(h, 0);
    return (t == TY_INT || t == TY_FLT) ? t : TY_UNK;
}

/* settle the operand types of a binary numeric op: returns 1 when both are INT or FLT */
static int num_types(JC *c, int pa, int pb) {
    Ent *a = &c->st[pa], *b = &c->st[pb];
    if (a->ty == TY_UNK) {
        int w = hint_ty(a->hint);
        if (w == TY_UNK && (b->ty == TY_INT || b->ty == TY_FLT)) w = b->ty;
        if (w == TY_UNK || !need(c, pa, w)) return 0;
    }
    if (b->ty == TY_UNK) {
        int w = hint_ty(b->hint);
        if (w == TY_UNK && (a->ty == TY_INT || a->ty == TY_FLT)) w = a->ty;
        if (w == TY_UNK || !need(c, pb, w)) return 0;
    }
    return (a->ty == TY_INT || a->ty == TY_FLT) && (b->ty == TY_INT || b->ty == TY_FLT);
}

/* ---- leader states ---- */
static uint8_t *lstate(JC *c, int li) { return c->lt + (size_t)li * (size_t)c->nvars; }

static int merge_to(JC *c, uint32_t tpc) {
    int li = c->lmap[tpc - c->hdr];
    if (li < 0) return 0;
    int depth = c->dep - c->d0;
    for (int i = c->d0; i < c->dep; i++)
        if (c->st[i].kind != EK_MEM) { c->why = "pending value at a join"; return 0; }
    if (c->ldep[li] == 0xff) c->ldep[li] = (uint8_t)depth;
    else if (c->ldep[li] != depth) { c->why = "stack depth differs at a join"; return 0; }
    uint8_t *d = lstate(c, li);
    if (!c->lvalid[li]) {
        memcpy(d, c->vt, (size_t)c->nvars);
        c->lvalid[li] = 1;
        return 1;
    }
    for (int v = 0; v < c->nvars; v++) {
        uint8_t a = d[v], b = c->vt[v];
        uint8_t ty = (a & 0x7f) == (b & 0x7f) ? (a & 0x7f) : TY_UNK;
        uint8_t m = (uint8_t)(ty | ((a & b) & 0x80));
        if (m != a) { d[v] = m; c->changed = 1; }
    }
    return 1;
}

/* ------------------------------------------------------------------ */
/* instruction translation                                             */
/* ------------------------------------------------------------------ */
#define F3(n, k) {ST_f##n##_##k##_rr, ST_f##n##_##k##_rk, ST_f##n##_##k##_kr}
#define F9(n) {F3(n, ff), F3(n, fi), F3(n, if)}
static const int ST_FA[4][3][3] = {F9(add), F9(sub), F9(mul), F9(div)};
#define F3N(n, k) {ST_f##n##_##k##_rr_n, ST_f##n##_##k##_rk_n, ST_f##n##_##k##_kr_n}
#define F9N(n) {F3N(n, ff), F3N(n, fi), F3N(n, if)}
static const int ST_FAN[4][3][3] = {F9N(add), F9N(sub), F9N(mul), F9N(div)};
static const int ST_IAN[3][3] = {{ST_iadd_rr_n, ST_iadd_rk_n, ST_iadd_kr_n}, {ST_isub_rr_n, ST_isub_rk_n, ST_isub_kr_n}, {ST_imul_rr_n, ST_imul_rk_n, ST_imul_kr_n}};
static const int ST_IA[3][3] = {{ST_iadd_rr, ST_iadd_rk, ST_iadd_kr}, {ST_isub_rr, ST_isub_rk, ST_isub_kr}, {ST_imul_rr, ST_imul_rk, ST_imul_kr}};
#define IB(k) {{ST_ibr_##k##_t_rr, ST_ibr_##k##_t_rk}, {ST_ibr_##k##_f_rr, ST_ibr_##k##_f_rk}}
static const int ST_IBR[6][2][2] = {IB(lt), IB(le), IB(gt), IB(ge), IB(eq), IB(ne)};
#define FB2(k, p, cb) {ST_fbr_##k##_##p##_##cb##_rr, ST_fbr_##k##_##p##_##cb##_rk}
#define FB(k) {{FB2(k, t, ff), FB2(k, t, fi), FB2(k, t, if)}, {FB2(k, f, ff), FB2(k, f, fi), FB2(k, f, if)}}
static const int ST_FBR[6][2][3][2] = {FB(lt), FB(le), FB(gt), FB(ge), FB(eq), FB(ne)};

/* reciprocal for unsigned division by a constant d (2 <= d < 2^31, not a power of two): see imod_m in stencils.S */
static int magic_of(int64_t d, uint64_t *m) {
    int l = 0;
    while (((int64_t)1 << l) < d) l++;
    uint64_t num = ((uint64_t)1 << l) - (uint64_t)d, q = 0, r = num;
    for (int i = 0; i < 64; i++) {            /* q = floor(num * 2^64 / d) by long division */
        r <<= 1;
        q <<= 1;
        if (r >= (uint64_t)d) { r -= (uint64_t)d; q |= 1; }
    }
    *m = q + 1;
    return l - 1;
}
static int is_pow2(int64_t v) { return v > 0 && (v & (v - 1)) == 0; }
static int log2i(int64_t v) { int k = 0; while (v > 1) { v >>= 1; k++; } return k; }

/* emit an operand-form stencil: forms 0 rr, 1 rk, 2 kr */
static int form_of(const Ent *a, const Ent *b) { return a->kind == EK_K ? 2 : b->kind == EK_K ? 1 : 0; }

/* the value an op leaves is stored to its stack position, or straight into a local when a STORE_LOCAL follows */
static int fuse_store(JC *c, uint32_t npc, int pa, int *dstlocal) {
    *dstlocal = -1;
    if (npc >= c->end || c->code[npc] != OP_STORE_LOCAL || c->lmap[npc - c->hdr] >= 0) return 1;
    int k = (int)rd16(c->code + npc + 1);
    if (k == c->pin && !c->pin_fuse) return 1;
    for (int i = 0; i < pa; i++) {
        const Ent *e = &c->st[i];
        if (e->kind == EK_LOC && e->idx == k) {
            if (!flush_from(c, 0, pa)) return 0;
            break;
        }
    }
    *dstlocal = k;
    return 1;
}


/* + - * (and float /) on operands that are all pending (locals, constants, register entries): the result stays in a
 * register. Returns 1 when done, 0 on failure (c->why set). */
static int arith_reg(JC *c, int op, int pa, int pb, int fl) {
    Ent a = c->st[pa], b = c->st[pb];
    uint32_t ppc = a.ppc;
    int rty = fl ? TY_FLT : TY_INT;
    if (!fl) {
        int xe = gexit(c);
        if (xe < 0) FAIL("out of memory");
        int commut = op != OP_SUB;
        int rd, swap = 0;
        if (a.kind == EK_REG) rd = a.idx;
        else if (b.kind == EK_REG && commut) { rd = b.idx; swap = 1; }
        else { rd = reg_alloc(c, 0, pa, pb); if (rd < 0) FAIL("no register"); }
        const Ent *dst_from = swap ? &b : &a, *src = swap ? &a : &b;
        if (dst_from->kind != EK_REG) {
            int cr = lc_src(c, dst_from, 0);
            if (cr == -2) return 0;
            if (dst_from->kind == EK_K) { if (!x_movi(c, rd, c->kt[dst_from->idx].as.i)) return 0; }
            else if (cr >= 0) { if (!x_mov(c, rd, cr)) return 0; }
            else if (!x_ldop(c, rd, dst_from, swap ? pb : pa)) return 0;
        }
        int oc = op == OP_ADD ? 0x03 : op == OP_SUB ? 0x2b : 0;
        int ok;
        if (src->kind == EK_REG) {
            ok = op == OP_MUL ? x_rr(c, 0, 1, 0x0f, 0xaf, rd, src->idx) : x_rr(c, 0, 1, oc, -1, rd, src->idx);
        } else if (src->kind == EK_K) {
            int64_t k = c->kt[src->idx].as.i;
            if (k >= INT32_MIN && k <= INT32_MAX) {
                if (op == OP_MUL) ok = x_rr(c, 0, 1, 0x69, -1, rd, rd) && x_imm32(c, (int32_t)k);
                else ok = x_rr(c, 0, 1, 0x81, -1, op == OP_ADD ? 0 : 5, rd) && x_imm32(c, (int32_t)k);
            } else {
                ok = x_movi(c, R_RCX, k) && (op == OP_MUL ? x_rr(c, 0, 1, 0x0f, 0xaf, rd, R_RCX) : x_rr(c, 0, 1, oc, -1, rd, R_RCX));
            }
        } else if (src->kind == EK_LOC && src->idx == c->pin) {
            ok = op == OP_MUL ? x_rr(c, 0, 1, 0x0f, 0xaf, rd, R_RBP) : x_rr(c, 0, 1, oc, -1, rd, R_RBP);
        } else if (src->kind == EK_LOC && lc_src(c, src, 0) >= 0) {
            int cr = lc_find(c, src->idx, 0);
            ok = op == OP_MUL ? x_rr(c, 0, 1, 0x0f, 0xaf, rd, cr) : x_rr(c, 0, 1, oc, -1, rd, cr);
        } else {
            int32_t o = roff(c, src, swap ? pa : pb) + 8;
            ok = op == OP_MUL ? x_mem(c, 0, 1, 0x0f, 0xaf, rd, R_R12, o) : x_mem(c, 0, 1, oc, -1, rd, R_R12, o);
        }
        if (!ok || !x_jx(c, 0, xe)) return 0;
        if (src->kind == EK_REG) reg_put(c, 0, src->idx);
        c->dep -= 2;
        Ent *r = push(c, EK_REG, TY_INT, rd);
        if (!r) return 0;
        r->ppc = ppc;
        return 1;
    }
    /* float: the left operand goes into the destination xmm register, the right one is combined into it */
    int op2 = op == OP_ADD ? 0x58 : op == OP_SUB ? 0x5c : op == OP_MUL ? 0x59 : 0x5e;
    int commut = op == OP_ADD || op == OP_MUL;
    int xd, swap = 0;
    if (a.kind == EK_REG && a.ty == TY_FLT) xd = a.idx;
    else if (commut && b.kind == EK_REG && b.ty == TY_FLT) { xd = b.idx; swap = 1; }
    else { xd = reg_alloc(c, 1, pa, pb); if (xd < 0) FAIL("no register"); }
    const Ent *lf = swap ? &b : &a, *rt = swap ? &a : &b;
    int lpos = swap ? pb : pa, rpos = swap ? pa : pb;
    if (!(lf->kind == EK_REG && lf->ty == TY_FLT)) {
        int ok, cr = lf->ty == TY_FLT ? lc_src(c, lf, 1) : -1;
        if (cr == -2) return 0;
        if (cr >= 0) ok = x_rr(c, 0, 0, 0x0f, 0x28, xd, cr);
        else if (lf->ty == TY_FLT) ok = lf->kind == EK_K ? x_sd_ld(c, xd, R_R13, koff(lf->idx) + 8) : x_sd_ld(c, xd, R_R12, roff(c, lf, lpos) + 8);
        else if (lf->kind == EK_REG) ok = x_rr(c, 0xf2, 1, 0x0f, 0x2a, xd, lf->idx);
        else ok = x_mem(c, 0xf2, 1, 0x0f, 0x2a, xd, lf->kind == EK_K ? R_R13 : R_R12, (lf->kind == EK_K ? koff(lf->idx) : roff(c, lf, lpos)) + 8);
        if (!ok) return 0;
    }
    if (op == OP_DIV) {          /* x / 0.0 (and x / NaN) is an error the interpreter raises: leave through the exit */
        int xe = gexit(c), xs = 0, ok = 1;
        if (xe < 0) FAIL("out of memory");
        int dcr = rt->ty == TY_FLT && rt->kind == EK_LOC ? lc_src(c, rt, 1) : -1;
        if (dcr == -2) return 0;
        if (rt->ty == TY_FLT && rt->kind == EK_REG) xs = rt->idx;
        else if (dcr >= 0) xs = dcr;
        else if (rt->ty == TY_FLT) ok = x_sd_ld(c, 0, rt->kind == EK_K ? R_R13 : R_R12, (rt->kind == EK_K ? koff(rt->idx) : roff(c, rt, rpos)) + 8);
        else if (rt->kind == EK_REG) ok = x_rr(c, 0xf2, 1, 0x0f, 0x2a, 0, rt->idx);
        else ok = x_mem(c, 0xf2, 1, 0x0f, 0x2a, 0, rt->kind == EK_K ? R_R13 : R_R12, (rt->kind == EK_K ? koff(rt->idx) : roff(c, rt, rpos)) + 8);
        ok = ok && x_rr(c, 0x66, 0, 0x0f, 0x57, 15, 15) && x_rr(c, 0x66, 0, 0x0f, 0x2e, xs, 15) && x_jx(c, 4, xe) && x_sd_rr(c, op2, xd, xs);
        if (!ok) return 0;
    } else {
        int ok;
        if (rt->ty == TY_FLT) {
            int cr = rt->kind == EK_LOC ? lc_src(c, rt, 1) : -1;
            if (cr == -2) return 0;
            if (rt->kind == EK_REG) ok = x_sd_rr(c, op2, xd, rt->idx);
            else if (cr >= 0) ok = x_sd_rr(c, op2, xd, cr);
            else ok = x_sd_rm(c, op2, xd, rt->kind == EK_K ? R_R13 : R_R12, (rt->kind == EK_K ? koff(rt->idx) : roff(c, rt, rpos)) + 8);
        } else {
            if (rt->kind == EK_REG) ok = x_rr(c, 0xf2, 1, 0x0f, 0x2a, 0, rt->idx);
            else ok = x_mem(c, 0xf2, 1, 0x0f, 0x2a, 0, rt->kind == EK_K ? R_R13 : R_R12, (rt->kind == EK_K ? koff(rt->idx) : roff(c, rt, rpos)) + 8);
            ok = ok && x_sd_rr(c, op2, xd, 0);
        }
        if (!ok) return 0;
    }
    if (a.kind == EK_REG && !(a.ty == TY_FLT && a.idx == xd)) reg_put(c, a.ty == TY_FLT, a.idx);
    if (b.kind == EK_REG && !(b.ty == TY_FLT && b.idx == xd)) reg_put(c, b.ty == TY_FLT, b.idx);
    c->dep -= 2;
    Ent *r = push(c, EK_REG, rty, xd);
    if (!r) return 0;
    r->ppc = ppc;
    return 1;
}

static int do_arith(JC *c, int op, uint32_t pc, int len, uint32_t *skip) {
    int pb = c->dep - 1, pa = c->dep - 2;
    if (pa < c->d0) FAIL("stack underflow");
    if (!num_types(c, pa, pb)) FAIL("non-numeric operands");
    Ent *a = &c->st[pa], *b = &c->st[pb];
    int ta = a->ty, tb = b->ty;
    int fl = (ta == TY_FLT || tb == TY_FLT);
    if ((op == OP_FLOOR_DIV || op == OP_MOD) && fl) FAIL("float floor division / modulo");
    if (a->kind != EK_MEM && !(a->kind == EK_K && b->kind == EK_K) && a->kind != EK_MOD && b->kind != EK_MOD &&
        (op == OP_ADD || op == OP_SUB || op == OP_MUL || op == OP_DIV) && c->reg_on)
        return arith_reg(c, op, pa, pb, fl || op == OP_DIV);
    if (!flush_regs(c)) return 0;
    a = &c->st[pa]; b = &c->st[pb];
    if (a->kind == EK_K && b->kind == EK_K) {
        if (!flush_from(c, pa, pa + 1)) return 0;
    }
    int dl;
    c->pin_fuse = 1;
    int fok = fuse_store(c, pc + (uint32_t)len, pa, &dl);
    c->pin_fuse = 0;
    if (!fok) return 0;
    int32_t dst = dl >= 0 ? LOFF(c, dl) : soff(c, pa);
    int rty = fl || op == OP_DIV ? TY_FLT : TY_INT;
    int form = form_of(a, b);
    int32_t oa = a->kind == EK_K ? koff(a->idx) : roff(c, a, pa);
    int32_t ob = b->kind == EK_K ? koff(b->idx) : roff(c, b, pb);
    c->xe = gexit(c);
    if (c->xe < 0) FAIL("out of memory");
    int rax_res = 0;
    if (!fl && op != OP_DIV && form != 2 && (a->kind == EK_LOC || a->kind == EK_MEM) && oa == c->rax_off) c->skip1 = 1;
    else if (!fl && op != OP_DIV && form != 2 && a->kind == EK_LOC && a->idx == c->pin) {
        EM(ST_ldrax_p, 0, 0, 0, 0, 0, 0);
        c->skip1 = 1;
    }
    if (!fl && op != OP_DIV) {
        if (op == OP_ADD || op == OP_SUB || op == OP_MUL) {
            int oi = op == OP_ADD ? 0 : op == OP_SUB ? 1 : 2;
            if (dl >= 0 && c->vt[dl] == (uint8_t)(0x80 | TY_INT)) EM(ST_IAN[oi][form], dst, oa, ob, 0, 0, 0);
            else EM(ST_IA[oi][form], dst, oa, ob, 0, 0, 0);
            rax_res = 1;
        } else if (b->kind == EK_K && form == 1 && c->kt[b->idx].as.i > 0 && c->kt[b->idx].as.i <= 0x7fffffff) {
            int64_t k = c->kt[b->idx].as.i;
            if (op == OP_MOD) {
                if (is_pow2(k)) { EM(ST_imod_p2, dst, oa, (int32_t)(k - 1), 0, 0, 0); rax_res = 1; }
                else { uint64_t mg; int sh = magic_of(k, &mg); EM(ST_imod_m, dst, oa, (int32_t)k, sh, 0, mg); }
            } else {
                if (is_pow2(k)) { EM(ST_ifdiv_p2, dst, oa, log2i(k), 0, 0, 0); rax_res = 1; }
                else { uint64_t mg; int sh = magic_of(k, &mg); EM(ST_ifdiv_m, dst, oa, (int32_t)k, sh, 0, mg); }
            }
        } else {
            static const int T[2][3] = {{ST_ifdiv_rr, ST_ifdiv_rk, ST_ifdiv_kr}, {ST_imod_rr, ST_imod_rk, ST_imod_kr}};
            EM(T[op == OP_MOD][form], dst, oa, ob, 0, 0, 0);
        }
    } else if (!fl) {                                   /* int / int -> float */
        if (form != 0 || a->kind == EK_K || b->kind == EK_K) FAIL("int division needs registers");
        EM(ST_idiv_rr, dst, oa, ob, 0, 0, 0);
    } else {
        int opi = op == OP_ADD ? 0 : op == OP_SUB ? 1 : op == OP_MUL ? 2 : 3;
        if ((opi == 0 || opi == 2) && (b->kind == EK_LOC || b->kind == EK_MEM) && ob == c->xmm_off && oa != c->xmm_off) {
            Ent *te = a; a = b; b = te;        /* + and * commute exactly: let the value still in xmm0 be the first operand */
            int tt = ta; ta = tb; tb = tt;
            int32_t to = oa; oa = ob; ob = to;
            form = form_of(a, b);
        }
        int combo = (ta == TY_FLT && tb == TY_FLT) ? 0 : (ta == TY_FLT ? 1 : 2);
        if (ta == TY_FLT && form != 2 && (a->kind == EK_LOC || a->kind == EK_MEM) && oa == c->xmm_off) c->skipx = 1;
        if (dl >= 0 && c->vt[dl] == (uint8_t)(0x80 | TY_FLT)) EM(ST_FAN[opi][combo][form], dst, oa, ob, 0, 0, 0);
        else EM(ST_FA[opi][combo][form], dst, oa, ob, 0, 0, 0);
        c->xmm_off = dst;
    }
    if (rax_res) c->rax_off = dst;
    if (dl >= 0 && dl == c->pin) {
        if (rax_res) { EM(ST_strax_p, 0, 0, 0, 0, 0, 0); c->rax_off = dst; }
        else EM(ST_ldp, dst, 0, 0, 0, 0, 0);
    }
    c->dep -= 2;
    if (dl >= 0) {
        c->vt[dl] = (uint8_t)(0x80 | rty);
        *skip = 3;
    } else {
        Ent *r = push(c, EK_MEM, rty, 0);
        if (!r) return 0;
        r->ppc = pc;
    }
    return 1;
}

static int cond_index(int op) {
    switch (op) {
    case OP_LT: return 0; case OP_LE: return 1; case OP_GT: return 2;
    case OP_GE: return 3; case OP_EQ: return 4; default: return 5;
    }
}

/* a branch target: inside the region a label (state merged), outside an exit to the interpreter */
static int set_target(JC *c, uint32_t tpc, uint32_t from_pc, int backward) {
    if (tpc >= c->hdr && tpc < c->end && c->lmap[tpc - c->hdr] >= 0) {
        if (!merge_to(c, tpc)) { if (!c->why) c->why = "bad branch target"; return 0; }
        c->tk = 0;
        c->tt = (int)tpc;
        return 1;
    }
    if (tpc >= c->hdr && tpc < c->end) FAIL("branch into the middle of a sequence");
    int x = exit_for(c, backward ? from_pc : tpc, c->dep);
    if (x < 0) FAIL("out of memory");
    c->tk = 1;
    c->tt = x;
    return 1;
}

/* Decode the conditional branch at pc as (jump when true / when false, target). The "or pop" forms keep the tested
 * value on the stack on the taken path; when the target tests it again (JUMP_IF_FALSE / JUMP_IF_TRUE, which is how
 * `a and b` / `a or b` are compiled in conditions) the pair is an ordinary conditional branch to wherever that second
 * test goes, or past it. Returns 0 for anything else (a value-producing and / or). */
static int branch_info(const uint8_t *code, uint32_t n, uint32_t pc, int *jop, uint32_t *tpc) {
    int op = code[pc];
    if (op != OP_JUMP_IF_FALSE && op != OP_JUMP_IF_TRUE && op != OP_JUMP_IF_FALSE_OR_POP && op != OP_JUMP_IF_TRUE_OR_POP) return 0;
    if (pc + 5 > n) return 0;
    int32_t off = rd32s(code + pc + 1);
    if (off < 0) return 0;
    uint32_t t = pc + 5 + (uint32_t)off;
    if (op == OP_JUMP_IF_FALSE || op == OP_JUMP_IF_TRUE) { *jop = op; *tpc = t; return 1; }
    if (t + 5 > n) return 0;
    int top = code[t];
    if (top != OP_JUMP_IF_FALSE && top != OP_JUMP_IF_TRUE) return 0;
    int32_t off2 = rd32s(code + t + 1);
    if (off2 < 0) return 0;
    int taken_falsy = op == OP_JUMP_IF_FALSE_OR_POP;
    int second_jumps = (top == OP_JUMP_IF_FALSE) == taken_falsy;
    *jop = taken_falsy ? OP_JUMP_IF_FALSE : OP_JUMP_IF_TRUE;
    *tpc = second_jumps ? t + 5 + (uint32_t)off2 : t + 5;
    return 1;
}

static int do_cmp_branch(JC *c, int cop, int jop, uint32_t tpc, uint32_t jpc, uint32_t extra, uint32_t *skip) {
    int pb = c->dep - 1, pa = c->dep - 2;
    if (pa < c->d0) FAIL("stack underflow");
    if (!num_types(c, pa, pb)) FAIL("non-numeric comparison");
    if (!flush_from(c, c->d0, pa)) return 0;
    Ent *a = &c->st[pa], *b = &c->st[pb];
    int ta = a->ty, tb = b->ty;
    int ci = cond_index(cop);
    int regcmp = c->reg_on && (a->kind == EK_REG || b->kind == EK_REG) && ((ta == TY_INT && tb == TY_INT) || (ta == TY_FLT && tb == TY_FLT && ci <= 3));
    if (!regcmp && !flush_regs(c)) return 0;
    a = &c->st[pa]; b = &c->st[pb];
    if (a->kind == EK_K && b->kind == EK_K) { if (!flush_from(c, pa, pa + 1)) return 0; }
    Ent ea = *a, eb = *b;
    int ia = pa, ib = pb;
    if (ea.kind == EK_K) {                              /* constant first: swap and mirror the condition */
        Ent t = ea; ea = eb; eb = t;
        int ti = ia; ia = ib; ib = ti;
        ci = ci == 0 ? 2 : ci == 1 ? 3 : ci == 2 ? 0 : ci == 3 ? 1 : ci;
        int tt = ta; ta = tb; tb = tt;
    }
    if (regcmp) {                                       /* operands in registers: compare and branch inline */
        int pol0 = jop == OP_JUMP_IF_TRUE ? 0 : 1, ok = 1;
        if (ta == TY_INT) {
            int ra = ea.kind == EK_REG ? ea.idx : R_RAX;
            if (ea.kind != EK_REG) ok = x_ldop(c, R_RAX, &ea, ia);
            if (ok) {
                if (eb.kind == EK_REG) ok = x_rr(c, 0, 1, 0x3b, -1, ra, eb.idx);
                else if (eb.kind == EK_K) {
                    int64_t k = c->kt[eb.idx].as.i;
                    if (k >= INT32_MIN && k <= INT32_MAX) ok = x_rr(c, 0, 1, 0x81, -1, 7, ra) && x_imm32(c, (int32_t)k);
                    else ok = x_movi(c, R_RCX, k) && x_rr(c, 0, 1, 0x3b, -1, ra, R_RCX);
                } else if (eb.kind == EK_LOC && eb.idx == c->pin) ok = x_rr(c, 0, 1, 0x3b, -1, ra, R_RBP);
                else ok = x_mem(c, 0, 1, 0x3b, -1, ra, R_R12, roff(c, &eb, ib) + 8);
            }
        } else {
            int lt = ci == 0 || ci == 1;               /* a < b is b > a: compare in the other order */
            const Ent *x = lt ? &eb : &ea, *y = lt ? &ea : &eb;
            int xp = lt ? ib : ia, yp = lt ? ia : ib;
            int xr = 0;
            if (x->kind == EK_REG) xr = x->idx;
            else ok = x->kind == EK_K ? x_sd_ld(c, 0, R_R13, koff(x->idx) + 8) : x_sd_ld(c, 0, R_R12, roff(c, x, xp) + 8);
            if (ok) {
                if (y->kind == EK_REG) ok = x_rr(c, 0x66, 0, 0x0f, 0x2e, xr, y->idx);
                else ok = x_mem(c, 0x66, 0, 0x0f, 0x2e, xr, y->kind == EK_K ? R_R13 : R_R12, (y->kind == EK_K ? koff(y->idx) : roff(c, y, yp)) + 8);
            }
        }
        if (!ok) return 0;
        if (ea.kind == EK_REG) reg_put(c, ea.ty == TY_FLT, ea.idx);
        if (eb.kind == EK_REG) reg_put(c, eb.ty == TY_FLT, eb.idx);
        c->dep -= 2;
        if (!set_target(c, tpc, jpc, 0)) return 0;
        int cc;
        if (ta == TY_INT) {
            static const int icc[6] = {0xc, 0xe, 0xf, 0xd, 0x4, 0x5};      /* l le g ge e ne */
            cc = icc[ci] ^ pol0;
        } else {
            static const int fcc[4] = {0x7, 0x3, 0x7, 0x3};                /* a (above) / ae; the inverse is be / b */
            cc = pol0 ? (fcc[ci] == 0x7 ? 0x6 : 0x2) : fcc[ci];
        }
        if (!x_jt(c, cc)) return 0;
        *skip = extra;
        return 1;
    }
    int form = eb.kind == EK_K ? 1 : 0;
    int32_t oa = roff(c, &ea, ia);
    int32_t ob = eb.kind == EK_K ? koff(eb.idx) : roff(c, &eb, ib);
    int pol = jop == OP_JUMP_IF_TRUE ? 0 : 1;          /* 0: jump when the condition holds, 1: when it does not */
    if (!(ta == TY_INT && tb == TY_INT)) {
        /* mixed int/float comparisons are exact in the interpreter; an int is exact as a double only within +-2^53 */
        for (int w = 0; w < 2; w++) {
            const Ent *e = w ? &eb : &ea;
            int t = w ? tb : ta, pos = w ? ib : ia;
            if (t != TY_INT) continue;
            if (e->kind == EK_K) {
                if (llabs(c->kt[e->idx].as.i) > (1LL << 53)) FAIL("mixed comparison");
            } else {
                c->xe = gexit(c);
                if (c->xe < 0) FAIL("out of memory");
                EM(ST_gi53, roff(c, e, pos), 0, 0, 0, 0, 0);
            }
        }
    }
    c->dep -= 2;
    if (!set_target(c, tpc, jpc, 0)) return 0;
    c->xe = -1;
    if (ta == TY_INT && tb == TY_INT) {
        if ((ea.kind == EK_LOC || ea.kind == EK_MEM) && oa == c->rax_off) c->skip1 = 1;
        else if (ea.kind == EK_LOC && ea.idx == c->pin) {
            EM(ST_ldrax_p, 0, 0, 0, 0, 0, 0);
            c->skip1 = 1;
        }
        EM(ST_IBR[ci][pol][form], 0, oa, ob, 0, 0, 0);
    } else {
        int combo = (ta == TY_FLT && tb == TY_FLT) ? 0 : (ta == TY_FLT ? 1 : 2);
        EM(ST_FBR[ci][pol][combo][form], 0, oa, ob, 0, 0, 0);
    }
    *skip = extra;
    return 1;
}

static int jump_if(JC *c, int op, uint32_t tpc, uint32_t pc) {
    int p = c->dep - 1;
    if (p < c->d0) FAIL("stack underflow");
    if (!flush_from(c, c->d0, p)) return 0;
    Ent *e = &c->st[p];
    int jt = op == OP_JUMP_IF_TRUE;
    c->dep--;
    if (e->ty == TY_INT || e->ty == TY_FLT || e->ty == TY_ARR || e->ty == TY_INST) {   /* always true */
        if (jt) { if (!set_target(c, tpc, pc, 0)) return 0; c->xe = -1; EM(ST_jmp, 0, 0, 0, 0, 0, 0); }
        return 1;
    }
    if (e->kind == EK_K) { if (!materialize(c, p)) return 0; e->ty = TY_UNK; }
    if (e->kind == EK_MOD) { if (!materialize(c, p)) return 0; }
    if (!set_target(c, tpc, pc, 0)) return 0;
    c->xe = -1;
    EM(e->ty == TY_BOOL ? (jt ? ST_bbr_t : ST_bbr_f) : (jt ? ST_tbr_t : ST_tbr_f), 0, roff(c, e, p), 0, 0, 0, 0);
    return 1;
}

/* `x == nil` / `x != nil` fused with the following conditional jump (the `??` pattern): a tag test on the slot, or a static
 * answer when the type is known and can never be nil */
static int do_nil_branch(JC *c, int cop, int jop, uint32_t tpc, uint32_t jpc) {
    int pa = c->dep - 2;
    if (pa < c->d0) FAIL("stack underflow");
    if (!flush_from(c, c->d0, pa)) return 0;
    Ent *e = &c->st[pa];
    int jn = (cop == OP_EQ) == (jop == OP_JUMP_IF_TRUE);       /* the jump is taken when the value is nil (else: when it is not) */
    if (e->ty == TY_INT || e->ty == TY_FLT || e->ty == TY_BOOL || e->ty == TY_ARR || e->ty == TY_INST) {
        if (e->kind == EK_REG) reg_put(c, reg_is_x(e), e->idx);
        c->dep -= 2;
        if (!jn) { if (!set_target(c, tpc, jpc, 0)) return 0; c->xe = -1; EM(ST_jmp, 0, 0, 0, 0, 0, 0); }
        return 1;
    }
    if (e->kind == EK_K || e->kind == EK_MOD) { if (!materialize(c, pa)) return 0; }
    e = &c->st[pa];
    int off = roff(c, e, pa);
    c->dep -= 2;
    if (!set_target(c, tpc, jpc, 0)) return 0;
    c->xe = -1;
    EM(jn ? ST_nilbr_t : ST_nilbr_f, 0, off, 0, 0, 0, 0);
    return 1;
}

static int after_call(JC *c, uint32_t next_pc);

/* ---- instances ---- */
static const SClass *inst_class(const Ent *e) {
    if (e->ty == TY_INST) return e->cls;
    if (e->ty == TY_UNK && e->hint && e->hint->type == T_INSTANCE) return AS_INSTANCE(*e->hint)->cls;
    return NULL;
}

/* make the entry an instance of class k (guard emitted unless already known) */
static int need_inst(JC *c, int pos, const SClass *k) {
    Ent *e = &c->st[pos];
    if (e->ty == TY_INST) return e->cls == k;
    if (e->ty != TY_UNK || e->kind == EK_K || e->kind == EK_MOD) return 0;
    int kx = kadd(c, v_obj(T_CLASS, (Obj *)(uintptr_t)k));     /* keeps the class alive as long as the code */
    if (kx < 0) return 0;
    int x = gexit(c);
    if (x < 0) return 0;
    c->xe = x;
    if (!em(c, ST_gcls, roff(c, e, pos), 0, 0, 0, 0, (uint64_t)(uintptr_t)k)) return 0;
    e->ty = TY_INST;
    e->cls = k;
    if (e->kind == EK_LOC && (!c->vk[e->idx] || c->vk[e->idx] == k)) {
        c->vk[e->idx] = k;
        c->vt[e->idx] = (uint8_t)((c->vt[e->idx] & 0x80) | TY_INST);
    }
    return 1;
}

static int field_slot(const SClass *k, const SString *name) {
    SpValue sv;
    if (!table_get_sstr(k->fields, name, &sv)) return -1;
    return sv.as.i >= 0 && sv.as.i < 4096 ? (int)sv.as.i : -1;
}

static int do_get_member(JC *c, uint32_t pc, int len, uint32_t *skip) {
    unsigned kix = rd16(c->code + pc + 1);
    int pa = c->dep - 1;
    if (pa < c->d0 || kix >= (unsigned)c->p->nconsts || c->p->consts[kix].type != T_STRING) FAIL("member");
    const SString *name = AS_STR(c->p->consts[kix]);
    Ent *a = &c->st[pa];
    const SClass *k = inst_class(a);
    if (!k) FAIL("member of a non-instance");
    int slot = field_slot(k, name);
    if (slot < 0) FAIL("not a field");
    if (!need_inst(c, pa, k)) FAIL("member receiver");
    const SpValue *hint = NULL;
    if (a->hint && a->hint->type == T_INSTANCE && AS_INSTANCE(*a->hint)->cls == k && slot < AS_INSTANCE(*a->hint)->nslots)
        hint = &AS_INSTANCE(*a->hint)->slots[slot];
    int hty = hint_ty(hint);
    if (hty == TY_UNK && hint && hint->type == T_ARRAY) hty = TY_ARR;
    int32_t fo = (int32_t)(offsetof(SInstance, slots) + (size_t)slot * 16);
    if (c->reg_on && hty != TY_UNK && (a->kind == EK_LOC || a->kind == EK_REG)) {   /* guard + payload straight into a register */
        c->xe = gexit(c);
        if (c->xe < 0) FAIL("out of memory");
        uint32_t ppc = a->ppc;
        Ent ae = *a;
        int mir = ae.kind == EK_LOC ? lc_src(c, &ae, 0) : -1;       /* the receiver pointer is often already in a register */
        if (mir == -2) return 0;
        int ra = ae.kind == EK_REG ? ae.idx : reg_alloc(c, 0, pa, -1);
        if (ra < 0) FAIL("no register");
        int base = ra;
        if (ae.kind != EK_REG) {
            if (mir >= 0 && lc_find(c, ae.idx, 0) == mir) base = mir;
            else if (!x_ldop(c, ra, &ae, pa)) return 0;
        }
        if (!x_cmpi(c, base, fo, (int32_t)tag_of(hty)) || !x_jx(c, 5, c->xe)) return 0;
        int rr = ra;
        if (hty == TY_FLT) {
            rr = reg_alloc(c, 1, pa, -1);
            if (rr < 0) FAIL("no register");
            if (!x_sd_ld(c, rr, base, fo + 8)) return 0;
            reg_put(c, 0, ra);
        } else if (!x_ld(c, ra, base, fo + 8)) return 0;
        c->dep--;
        Ent *r = push(c, EK_REG, hty, rr);
        if (!r) return 0;
        r->ppc = ppc;
        r->hint = hint;
        return 1;
    }
    if (!flush_regs(c)) return 0;
    a = &c->st[pa];
    if (hty == TY_ARR) hty = TY_UNK;
    int dl;
    if (!fuse_store(c, pc + (uint32_t)len, pa, &dl)) return 0;
    int32_t dst = dl >= 0 ? LOFF(c, dl) : soff(c, pa);
    if (hty != TY_UNK && !(dl >= 0 && dl == c->pin)) {   /* the field's type is predicted: guard it right here and keep the payload in rax / xmm0 */
        c->xe = gexit(c);
        if (c->xe < 0) FAIL("out of memory");
        EM(hty == TY_INT ? ST_ldfld_i : ST_ldfld_f, dst, roff(c, a, pa), fo, 0, 0, 0);
        if (hty == TY_INT) c->rax_off = dst; else c->xmm_off = dst;
        c->dep--;
        if (dl >= 0) {
            c->vt[dl] = (uint8_t)(0x80 | hty);
            *skip = 3;
        } else {
            Ent *r = push(c, EK_MEM, hty, 0);
            if (!r) return 0;
            r->ppc = pc;
            r->hint = hint;
        }
        return 1;
    }
    c->xe = -1;
    EM(ST_ldfld, dst, roff(c, a, pa), fo, 0, 0, 0);
    c->dep--;
    if (dl >= 0) {
        c->vt[dl] = 0x80 | TY_UNK;
        *skip = 3;
    } else {
        Ent *r = push(c, EK_MEM, TY_UNK, 0);
        if (!r) return 0;
        r->ppc = pc;
        r->hint = hint;
    }
    return 1;
}

static int do_set_member(JC *c, uint32_t pc) {
    unsigned kix = rd16(c->code + pc + 1);
    int pv = c->dep - 1, pr = c->dep - 2;
    if (pr < c->d0 || kix >= (unsigned)c->p->nconsts || c->p->consts[kix].type != T_STRING) FAIL("member");
    const SString *name = AS_STR(c->p->consts[kix]);
    Ent *r = &c->st[pr], *v = &c->st[pv];
    const SClass *k = inst_class(r);
    if (!k) FAIL("member of a non-instance");
    int slot = field_slot(k, name);
    if (slot < 0) FAIL("not a field");
    if (r->kind == EK_K || r->kind == EK_MOD) FAIL("member receiver");
    int32_t fo = (int32_t)(offsetof(SInstance, slots) + (size_t)slot * 16);
    if (c->reg_on && v->kind != EK_MOD && v->ty != TY_MOD) {      /* store straight from a register / slot / constant */
        if (!flush_from(c, c->d0, pr)) return 0;
        if (!need_inst(c, pr, k)) FAIL("member receiver");
        Ent re = *r, ve = *v;
        int rp = re.kind == EK_REG ? re.idx : R_RAX;
        int ok = re.kind == EK_REG ? 1 : x_ld(c, R_RAX, R_R12, roff(c, &re, pr) + 8);
        if (ok) {
            if (ve.kind == EK_REG) {
                ok = x_sti(c, rp, fo, (int32_t)tag_of(ve.ty)) && (reg_is_x(&ve) ? x_sd_st(c, rp, fo + 8, ve.idx) : x_st(c, rp, fo + 8, ve.idx));
            } else {
                int base = ve.kind == EK_K ? R_R13 : R_R12;
                int32_t o = ve.kind == EK_K ? koff(ve.idx) : roff(c, &ve, pv);
                ok = x_ld(c, R_RCX, base, o) && x_ld(c, R_RDX, base, o + 8) && x_st(c, rp, fo, R_RCX) && x_st(c, rp, fo + 8, R_RDX);
            }
        }
        if (!ok) return 0;
        if (re.kind == EK_REG) reg_put(c, 0, re.idx);
        if (ve.kind == EK_REG) reg_put(c, reg_is_x(&ve), ve.idx);
        c->dep -= 2;
        return 1;
    }
    if (!flush_regs(c)) return 0;
    r = &c->st[pr]; v = &c->st[pv];
    if (!flush_from(c, c->d0, pr)) return 0;
    if (v->kind == EK_MOD && !materialize(c, pv)) return 0;
    if (!need_inst(c, pr, k)) FAIL("member receiver");
    c->xe = -1;
    if (v->kind == EK_K) EM(ST_stfldk, roff(c, r, pr), koff(v->idx), fo, 0, 0, 0);
    else EM(ST_stfld, roff(c, r, pr), roff(c, v, pv), fo, 0, 0, 0);
    c->dep -= 2;
    return 1;
}

/* method call on an instance (receiver, arguments): a native call of the compiled method */
static int inl_enabled = -1;
/* the resource checks of an inlined call (frame room, stack room, budget): a loop region checks the first two once, at entry */
static int em_ginlr(JC *c, int32_t so, int64_t need) {
    if (c->unit) return em(c, ST_ginlr, so, (int32_t)need, 0, 0, 0, 0);
    if (so + 16 + need > c->inl_extent) c->inl_extent = so + 16 + need;
    return em(c, ST_ginlrn, 0, 0, 0, 0, 0, 0);
}
static int em_ginl(JC *c, int32_t so, int64_t need, const Proto *kp) {
    if (c->unit) return em(c, ST_ginl, so, (int32_t)need, 0, 0, 0, (uint64_t)(uintptr_t)kp);
    if (so + 16 + need > c->inl_extent) c->inl_extent = so + 16 + need;
    return em(c, ST_ginln, so, 0, 0, 0, 0, (uint64_t)(uintptr_t)kp);
}
static int inl_candidate(const Proto *kp, const uint8_t *code, int calls);
static int ictx_add(JC *c, Proto *kp, uint32_t retpc, int base_slots);
static int inl_body(JC *c, const Proto *kp, const uint8_t *kcode, int argc, int pf, uint32_t pc0, int ic, SFunc *cf, const SClass *ctor);
static int do_get_index(JC *c, uint32_t pc, int len, uint32_t *skip);
static int do_set_index(JC *c, uint32_t pc);
static int do_invoke_inst(JC *c, uint32_t pc, int len, const SClass *k, const SString *name, int argc) {
    if (!flush_regs(c)) return 0;
    int pm = c->dep - 1 - argc;
    if (pm < c->d0) FAIL("stack underflow");
    SpValue fv;
    if (table_get_sstr(k->fields, name, &fv)) FAIL("field call");
    if (!table_get_sstr(k->methods, name, &fv) || fv.type != T_FUNCTION || !AS_FUNC(fv)->proto) FAIL("method");
    if (!need_inst(c, pm, k)) FAIL("method receiver");
    int fk = kadd(c, fv);
    if (fk < 0) FAIL("too many constants");
    if (!flush_from(c, c->d0, c->dep)) return 0;
    int x = exit_for(c, pc, c->dep);
    if (x < 0) FAIL("out of memory");
    c->xe = x;
    const Proto *kp = AS_FUNC(fv)->proto;
    if (inl_enabled && c->cur_ic == 0 && kp != c->p && argc < 12 && kp->nparams == argc + 1 && kp->nrequired == argc + 1 &&
        !kp->has_rest && kp->ndefaults == 0) {
        const uint8_t *kcode = kp->ocode ? kp->ocode : kp->code;
        if (inl_candidate(kp, kcode, 1)) {
            Ent saved[12];
            memcpy(saved, &c->st[pm], (size_t)(argc + 1) * sizeof *saved);
            size_t scn = c->cn;
            int snfx = c->nfx, snex = c->nex, snic = c->nic, sdep = c->dep;
            int64_t need = ((int64_t)kp->nlocals + kp->max_stack + 8) * 16;
            int okk = c->dep + 1 < c->stcap;
            c->xe = x;
            if (okk) okk = em_ginlr(c, soff(c, pm), need);
            for (int i = argc; okk && i >= 0; i--) okk = em(c, ST_mov, soff(c, pm + 1 + i), soff(c, pm + i), 0, 0, 0, 0);
            if (okk) okk = em(c, ST_movk, soff(c, pm), koff(fk), 0, 0, 0, 0);
            int ic = okk ? ictx_add(c, (Proto *)(uintptr_t)kp, pc + (uint32_t)len, c->nloc + pm + 1) : -1;
            if (ic >= 0) {
                for (int i = argc; i >= 0; i--) c->st[pm + 1 + i] = saved[i];
                Ent *fe = &c->st[pm];
                fe->kind = EK_MEM; fe->ty = TY_UNK; fe->idx = 0; fe->ppc = pc; fe->hint = NULL; fe->cls = NULL;
                c->dep = sdep + 1;
                if (inl_body(c, kp, kcode, argc + 1, pm, pc, ic, AS_FUNC(fv), NULL) == 1) {
                    c->rax_off = -1;
                    c->xmm_off = -1;
                    return 1;
                }
            }
            memcpy(&c->st[pm], saved, (size_t)(argc + 1) * sizeof *saved);
            c->cn = scn; c->nfx = snfx; c->nex = snex; c->nic = snic; c->dep = sdep;
            c->why = NULL;
            c->rax_off = -1; c->xmm_off = -1; c->skip1 = 0; c->skipx = 0;
            c->xe = x;
        }
    }
    EM(ST_uinvoke, soff(c, pm), argc, koff(fk), 0, 0, (uint64_t)(uintptr_t)(c->p->code + pc + (uint32_t)len));
    c->dep -= argc + 1;
    Ent *r = push(c, EK_MEM, TY_UNK, 0);
    if (!r) return 0;
    r->ppc = pc;
    r->hint = &g_hint_int;
    return after_call(c, pc + (uint32_t)len);
}

/* the libm functions the interpreter's math fast path calls (same function => bit-identical results) */
static double (*libm_fn(const char *name))(double) {
    if (strcmp(name, "sin") == 0) return sin;
    if (strcmp(name, "cos") == 0) return cos;
    if (strcmp(name, "exp") == 0) return exp;
    if (strcmp(name, "tan") == 0) return tan;
    if (strcmp(name, "atan") == 0) return atan;
    return NULL;
}

static int jh_nat(VM *vm, SpValue *argv, unsigned argc, SpValue *dst, NativeFn fn, unsigned want);
static int emit_nat(JC *c, uint32_t pc, int pf, int argc, const NativeDesc *nd, int rty);
static int nat_result_ty(const NativeDesc *nd, JC *c, int pf, int argc);

/* INVOKE with one argument: math.sqrt / sin / cos / exp / tan / atan (LOAD_MODULE m; arg; INVOKE name) and
 * array.append (no growth) */
static int do_invoke(JC *c, uint32_t pc, int len, uint32_t *skip) {
    unsigned kix = rd16(c->code + pc + 1);
    int argc = c->code[pc + 3];
    if (kix >= (unsigned)c->p->nconsts || c->p->consts[kix].type != T_STRING) FAIL("call");
    if (c->dep - 1 - argc >= c->d0) {
        const Ent *re = &c->st[c->dep - 1 - argc];
        const SClass *rk = inst_class(re);
        if (rk) return do_invoke_inst(c, pc, len, rk, AS_STR(c->p->consts[kix]), argc);
    }
    int pb = c->dep - 1, pm = c->dep - 1 - argc;
    if (argc < 1 || pm < c->d0) FAIL("call");
    Ent *m = &c->st[pm];
    const SString *name = AS_STR(c->p->consts[kix]);
    if (m->ty != TY_MOD) {
        if (argc != 1) FAIL("call");
        if (!flush_regs(c)) return 0;
        m = &c->st[pm];
        if (name->len != 6 || memcmp(name->data, "append", 6) != 0) FAIL("call");
        Ent *a = &c->st[pb];
        if (m->kind == EK_K || m->kind == EK_MOD) FAIL("append receiver");
        if (!need(c, pm, TY_ARR)) FAIL("append receiver");
        if (a->kind == EK_MOD && !materialize(c, pb)) return 0;
        if (!flush_from(c, c->d0, pm)) return 0;
        c->xe = gexit(c);
        if (c->xe < 0) FAIL("out of memory");
        int32_t lo = (int32_t)offsetof(SArray, len), io = (int32_t)offsetof(SArray, items), co = (int32_t)offsetof(SArray, cap);
        c->h5 = co;
        if (a->kind == EK_K) EM(ST_aappend_k, soff(c, pm), roff(c, m, pm), koff(a->idx), lo, io, 0);
        else EM(ST_aappend_r, soff(c, pm), roff(c, m, pm), roff(c, a, pb), lo, io, 0);
        c->dep -= 2;
        Ent *r = push(c, EK_MEM, TY_UNK, 0);
        if (!r) return 0;
        r->ppc = pc;
        return 1;
    }
    const SpValue *mv = &c->vm->slots[c->mslot[m->idx]];
    if (mv->type != T_MODULE) FAIL("call");
    SpValue fv;
    if (!table_get_sstr(AS_MODULE(*mv)->exports, name, &fv) || fv.type != T_FUNCTION || !AS_FUNC(fv)->nat) FAIL("call");
    const NativeDesc *nd = AS_FUNC(fv)->nat;
    double o;
    int is_sqrt = strcmp(nd->name, "sqrt") == 0;
    double (*lf)(double) = is_sqrt ? NULL : libm_fn(nd->name);
    if (argc != 1 || !math_fast1(nd, 4.0, &o) || (!is_sqrt && !lf)) {
        if (!math_pure_native(nd) || argc < nd->min_args || (nd->max_args >= 0 && argc > nd->max_args)) FAIL("call");
        return emit_nat(c, pc, pm, argc, nd, nat_result_ty(nd, c, pm, argc));
    }
    if (is_sqrt && (o < 1.999 || o > 2.001)) FAIL("call");
    Ent *a = &c->st[pb];
    if (a->ty == TY_UNK && !need(c, pb, hint_ty(a->hint) == TY_INT ? TY_INT : TY_FLT)) FAIL("math argument");
    if (a->ty != TY_FLT && a->ty != TY_INT) FAIL("math argument");
    if (c->reg_on && is_sqrt && a->kind != EK_MOD) {         /* sqrt of a float / int operand into an xmm register */
        Ent ae = *a;
        uint32_t ppc = c->st[pm].ppc;
        c->xe = gexit(c);
        if (c->xe < 0) FAIL("out of memory");
        EM(ST_tick1, (int32_t)offsetof(VM, ileft), 0, 0, 0, 0, 0);
        int xd = (ae.kind == EK_REG && ae.ty == TY_FLT) ? ae.idx : reg_alloc(c, 1, pb, -1);
        if (xd < 0) FAIL("no register");
        int ok = 1;
        if (!(ae.kind == EK_REG && ae.ty == TY_FLT)) {
            int base = ae.kind == EK_K ? R_R13 : R_R12;
            int32_t ao = (ae.kind == EK_K ? koff(ae.idx) : roff(c, &ae, pb)) + 8;
            if (ae.ty == TY_FLT) ok = x_sd_ld(c, xd, base, ao);
            else if (ae.kind == EK_REG) ok = x_rr(c, 0xf2, 1, 0x0f, 0x2a, xd, ae.idx);
            else ok = x_mem(c, 0xf2, 1, 0x0f, 0x2a, xd, base, ao);
        }
        ok = ok && x_rr(c, 0x66, 0, 0x0f, 0x57, 15, 15) && x_rr(c, 0x66, 0, 0x0f, 0x2e, xd, 15) && x_jx(c, 2, c->xe) &&
             x_rr(c, 0xf2, 0, 0x0f, 0x51, xd, xd);
        if (!ok) return 0;
        if (ae.kind == EK_REG && ae.ty != TY_FLT) reg_put(c, 0, ae.idx);
        c->dep -= 2;
        Ent *r = push(c, EK_REG, TY_FLT, xd);
        if (!r) return 0;
        r->ppc = ppc;
        return 1;
    }
    if (!flush_regs(c)) return 0;
    a = &c->st[pb];
    if (a->kind == EK_K) { if (!materialize(c, pb)) return 0; }
    int dl;
    if (!fuse_store(c, pc + (uint32_t)len, pm, &dl)) return 0;
    int32_t dst = dl >= 0 ? LOFF(c, dl) : soff(c, pm);
    int32_t src = roff(c, a, pb);
    c->xe = gexit(c);
    if (c->xe < 0) FAIL("out of memory");
    {   /* the budget tick touches no register: what rax / xmm0 hold stays valid */
        int32_t ro = c->rax_off, xo = c->xmm_off;
        EM(ST_tick1, (int32_t)offsetof(VM, ileft), 0, 0, 0, 0, 0);
        c->rax_off = ro;
        c->xmm_off = xo;
    }
    if (a->ty == TY_INT) {
        /* the temporary lives in the (dead) receiver slot */
        EM(ST_i2f, soff(c, pm), src, 0, 0, 0, 0);
        src = soff(c, pm);
    }
    if (is_sqrt) {
        if (src == c->xmm_off) c->skipx = 1;
        EM(ST_fsqrt, dst, src, 0, 0, 0, 0);
        c->xmm_off = dst;
    } else EM(ST_fcall1, dst, src, 0, 0, 0, (uint64_t)(uintptr_t)lf);
    c->dep -= 2;
    if (dl >= 0) {
        c->vt[dl] = 0x80 | TY_FLT;
        *skip = 3;
    } else {
        Ent *r = push(c, EK_MEM, TY_FLT, 0);
        if (!r) return 0;
        r->ppc = pc;
    }
    return 1;
}

/* LOAD_LINK n: a resolved builtin function becomes a constant entry (only CALL looks at it) */
static int do_load_link(JC *c, uint32_t pc) {
    unsigned n = rd16(c->code + pc + 1);
    if (n >= (unsigned)c->vm->prog->nlinks) FAIL("unresolved link");
    SpValue v = c->vm->links[n];
    if (v.type != T_FUNCTION || !AS_FUNC(v)->nat) FAIL("link is not a builtin");
    int k = kadd(c, v);
    if (k < 0) FAIL("too many constants");
    Ent *e = push(c, EK_K, TY_UNK, k);
    if (!e) return 0;
    e->hint = &c->kt[k];
    return 1;
}

/* CALL of the builtin len on an array */
/* result type of a pure native, predicted from its name and the operand types (the helper checks the prediction) */
static int nat_result_ty(const NativeDesc *nd, JC *c, int pf, int argc) {
    const char *n = nd->name;
    if (!strcmp(n, "len") || !strcmp(n, "floor") || !strcmp(n, "ceil") || !strcmp(n, "trunc") || !strcmp(n, "round")) return TY_INT;
    if (!strcmp(n, "log") || !strcmp(n, "atan2") || !strcmp(n, "asin") || !strcmp(n, "acos")) return TY_FLT;
    if (!strncmp(n, "is_", 3)) return TY_BOOL;
    if (!strcmp(n, "abs") || !strcmp(n, "min") || !strcmp(n, "max") || !strcmp(n, "clamp")) {
        int t = TY_UNK;
        for (int i = 1; i <= argc; i++) {
            const Ent *e = &c->st[pf + i];
            int ti = e->ty == TY_INT || e->ty == TY_FLT ? e->ty : hint_ty(e->hint);
            if (ti == TY_UNK || (t != TY_UNK && ti != t)) return TY_UNK;
            t = ti;
        }
        return t;
    }
    return TY_UNK;
}

/* call a pure native through the helper: the callee entry is at pf, the argc arguments follow it */
static int emit_nat(JC *c, uint32_t pc, int pf, int argc, const NativeDesc *nd, int rty) {
    if (!flush_regs(c) || !flush_from(c, pf, c->dep)) return 0;
    c->xe = gexit(c);
    if (c->xe < 0) FAIL("out of memory");
    c->hq2 = (uint64_t)(uintptr_t)nd->fn;
    EM(ST_hnat, soff(c, pf), soff(c, pf + 1), argc, soff(c, c->dep), rty == TY_UNK ? 0xff : (int32_t)tag_of(rty), (uint64_t)(uintptr_t)jh_nat);
    c->dep -= argc + 1;
    Ent *r = push(c, EK_MEM, rty, 0);
    if (!r) return 0;
    r->ppc = pc;
    c->rax_off = -1; c->xmm_off = -1; c->skip1 = 0; c->skipx = 0;
    return 1;
}

static int do_call_len(JC *c, uint32_t pc, int len, uint32_t *skip) {
    int pb = c->dep - 1, pf = c->dep - 2;
    Ent *a = &c->st[pb];
    if (a->kind == EK_K || a->kind == EK_MOD || !need(c, pb, TY_ARR)) FAIL("len argument");
    int dl;
    if (!fuse_store(c, pc + (uint32_t)len, pf, &dl)) return 0;
    int32_t dst = dl >= 0 ? LOFF(c, dl) : soff(c, pf);
    int32_t src = roff(c, a, pb);
    c->xe = gexit(c);
    if (c->xe < 0) FAIL("out of memory");
    EM(ST_tick1, (int32_t)offsetof(VM, ileft), 0, 0, 0, 0, 0);
    EM(ST_alen, dst, src, 0, (int32_t)offsetof(SArray, len), 0, 0);
    c->dep -= 2;
    if (dl >= 0) {
        c->vt[dl] = 0x80 | TY_INT;
        *skip = 3;
    } else {
        Ent *r = push(c, EK_MEM, TY_INT, 0);
        if (!r) return 0;
        r->ppc = pc;
    }
    return 1;
}

/* After a call anything global may have changed: module variables lose their type (module objects are re-checked,
 * because the inlined math functions depend on which module a variable holds). */
static int after_call(JC *c, uint32_t next_pc) {
    for (int i = 0; i < c->nmv; i++) {
        int v = c->nloc + i;
        if ((c->vt[v] & 0x7f) == TY_MOD) {
            int x = exit_for(c, next_pc, c->dep);
            if (x < 0) FAIL("out of memory");
            c->xe = x;
            EM(ST_gtag_mod, c->mslot[i] * 16, (int32_t)T_MODULE, 0, 0, 0, 0);
            EM(ST_gobj_mod, c->mslot[i] * 16, 0, 0, 0, 0, (uint64_t)(uintptr_t)c->vm->slots[c->mslot[i]].as.o);
        } else {
            c->vt[v] = 0x80 | TY_UNK;
        }
    }
    return 1;
}

/* construction `Class(args)` through the interpreter's fast path (class_analyze): see stencil uctor */
static int do_construct(JC *c, uint32_t pc, int len, int argc, SClass *k) {
    int pf = c->dep - 1 - argc;
    if (k->fast != 1) FAIL("class not analysed");
    const SFunc *init = k->init;
    if (init && (!init->proto || init->proto->nparams != argc + 1 || init->proto->has_rest || init->proto->ndefaults != 0 ||
                 init->proto->nrequired != argc + 1))
        FAIL("constructor arity");
    if (!init && argc != 0) FAIL("constructor arity");
    int ck = kadd(c, v_obj(T_CLASS, (Obj *)k));            /* keeps the class (and init) alive with the code */
    int fk = init ? kadd(c, v_obj(T_FUNCTION, (Obj *)(uintptr_t)init)) : 0;
    if (ck < 0 || fk < 0) FAIL("too many constants");
    if (init && inl_enabled && c->nest <= 1 && (c->nest == 0 || pf == c->pos0) && init->proto != c->p && argc < 11 && c->dep + 2 < c->stcap && k->nfields <= 14 &&
        c->st[pf].kind != EK_REG) {
        const Proto *kp = init->proto;
        const uint8_t *kcode = kp->ocode ? kp->ocode : kp->code;
        if (inl_candidate(kp, kcode, 0)) {
            /* what the caller still has pending below the class goes to memory first: a guard that fails inside the body leaves
             * the interpreter in the constructor's frame, on top of the caller's stack as it is in memory (a miscompilation fixed
             * in 2.28.1: `a + P(x).v` read a stale slot for `a`). Nothing is below the class when pf is the frame's bottom. */
            if (pf > c->pos0 && !flush_from(c, c->pos0, pf)) return 0;
            /* the arguments go straight to the slots above the instance (no flush and shift): until the first write the entries
             * stay pending, so a guard that fails replays them from their pushes */
            if (c->st[pf].kind != EK_MEM && !materialize(c, pf)) return 0;
            Ent saved[12];
            memcpy(saved, &c->st[pf], (size_t)(argc + 1) * sizeof *saved);
            int64_t need = ((int64_t)kp->nlocals + kp->max_stack + 8) * 16;
            int gx = gexit(c);
            if (gx < 0) FAIL("out of memory");
            c->xe = gx;
            EM(ST_ucls, soff(c, pf), 0, 0, 0, 0, (uint64_t)(uintptr_t)k);
            if (!em_ginlr(c, soff(c, pf), need)) return 0;
            c->xe = -1;
            for (int i = argc - 1; i >= 0; i--) {
                Ent *a = &saved[1 + i];
                int32_t dst = soff(c, pf + 2 + i);
                if (a->kind == EK_LOC) EM(ST_mov, dst, LOFF(c, a->idx), 0, 0, 0, 0);
                else if (a->kind == EK_K) EM(ST_movk, dst, koff(a->idx), 0, 0, 0, 0);
                else if (a->kind == EK_MOD) EM(ST_ldmod, dst, 0, c->mslot[a->idx] * 16, 0, 0, 0);
                else if (a->kind == EK_REG) {
                    if (!x_sti(c, R_R12, dst, (int32_t)tag_of(a->ty)) ||
                        !(reg_is_x(a) ? x_sd_st(c, R_R12, dst + 8, a->idx) : x_st(c, R_R12, dst + 8, a->idx))) return 0;
                    reg_put(c, reg_is_x(a), a->idx);
                } else EM(ST_mov, dst, soff(c, pf + 1 + i), 0, 0, 0, 0);
            }
            int32_t selfo = soff(c, pf + 1);
            if (!x_sti(c, R_R12, selfo, 0)) return 0;          /* valid for the collector until the instance is stored */
            EM(ST_unewc, soff(c, pf + 2 + argc), k->nfields, 32 + 16 * k->nfields, 0, 0, (uint64_t)(uintptr_t)k);
            for (int i = 0; i < k->nfields; i++) {
                uint64_t w = k->dflt ? k->dflt[i].w : 0;
                int64_t pay = k->dflt ? k->dflt[i].as.i : 0;
                int32_t fo = 32 + 16 * i;
                if (!x_sti(c, R_RAX, fo, (int32_t)w)) return 0;
                if (pay >= INT32_MIN && pay <= INT32_MAX) { if (!x_sti(c, R_RAX, fo + 8, (int32_t)pay)) return 0; }
                else if (!x_movi(c, R_RCX, pay) || !x_st(c, R_RAX, fo + 8, R_RCX)) return 0;
            }
            if (!x_sti(c, R_R12, selfo, 9) || !x_st(c, R_R12, selfo + 8, R_RAX)) return 0;
            EM(ST_movk, soff(c, pf), koff(fk), 0, 0, 0, 0);
            int ic = ictx_add(c, (Proto *)(uintptr_t)kp, pc + (uint32_t)len, soff(c, pf + 1) / 16);
            if (ic < 0) FAIL("out of memory");
            c->ic[ic].ctor = 1;
            size_t scn = c->cn;
            int snfx = c->nfx, snex = c->nex, sdep = c->dep;
            for (int i = argc - 1; i >= 0; i--) {
                c->st[pf + 2 + i] = saved[1 + i];
                c->st[pf + 2 + i].kind = EK_MEM;
            }
            Ent *fe = &c->st[pf];
            fe->kind = EK_MEM; fe->ty = TY_UNK; fe->idx = 0; fe->ppc = pc; fe->hint = NULL; fe->cls = NULL;
            Ent *se = &c->st[pf + 1];
            se->kind = EK_MEM; se->ty = TY_INST; se->idx = 0; se->ppc = pc; se->hint = NULL; se->cls = k;
            c->dep = sdep + 1;
            if (inl_body(c, kp, kcode, argc + 1, pf, pc, ic, (SFunc *)(uintptr_t)init, k) == 1) {
                c->rax_off = -1;
                c->xmm_off = -1;
                return after_call(c, pc + (uint32_t)len);
            }
            /* the body could not be translated: undo it, put the arguments and the class back where the call expects them and
             * take the ordinary path (the instance made above is simply garbage) */
            c->cn = scn; c->nfx = snfx; c->nex = snex; c->dep = sdep - 1;
            c->why = NULL;
            c->rax_off = -1; c->xmm_off = -1; c->skip1 = 0; c->skipx = 0;
            c->xe = -1;
            for (int i = 0; i < argc; i++) EM(ST_mov, soff(c, pf + 1 + i), soff(c, pf + 2 + i), 0, 0, 0, 0);
            EM(ST_movk, soff(c, pf), koff(ck), 0, 0, 0, 0);
            for (int i = 0; i <= argc; i++) {
                c->st[pf + i] = saved[i];
                c->st[pf + i].kind = EK_MEM;
            }
            c->dep = pf + 1 + argc;
        }
    }
    if (c->cur_ic) FAIL("nested construction not inlined");
    if (!flush_from(c, c->d0, c->dep)) return 0;
    int x = exit_for(c, pc, c->dep);
    if (x < 0) FAIL("out of memory");
    c->xe = x;
    c->hq2 = (uint64_t)(uintptr_t)(c->p->code + pc + (uint32_t)len);
    if (init) EM(ST_uctor, soff(c, pf), argc, koff(fk), soff(c, c->dep), 0, (uint64_t)(uintptr_t)k);
    else EM(ST_unew0, soff(c, pf), 0, 0, soff(c, c->dep), 0, (uint64_t)(uintptr_t)k);
    c->dep -= argc + 1;
    Ent *r = push(c, EK_MEM, TY_INST, 0);
    if (!r) return 0;
    r->ppc = pc;
    r->cls = k;
    return after_call(c, pc + (uint32_t)len);
}

/* CALL: a builtin `len` on an array is inlined; any other call is a native call into a compiled Sprint function
 * (stencil ucall), which leaves for the interpreter when the callee is not such a function. */
/* ---- inlining of small straight-line callees ---------------------------------------------------------------- */
#define INL_MAXCODE 160
#define INL_MAXLOC 16
static int reg_aware(int op);
static int do_dup(JC *c, int n, uint32_t pc);
static int do_store_local(JC *c, uint32_t pc);
static int do_neg(JC *c, uint32_t pc, int len, uint32_t *skip);
static int do_load_upval(JC *c, uint32_t pc);
static int do_store_upval(JC *c, uint32_t pc);

/* a callee worth inlining: no branches, calls, allocation or module access, a single RETURN at the very end */
static int inl_candidate(const Proto *kp, const uint8_t *code, int calls) {
    if (!code || kp->code_len > INL_MAXCODE || kp->nlocals > INL_MAXLOC || kp->max_stack > 12 || kp->nupvals > 8) return 0;
    uint32_t pc = 0, n = kp->code_len;
    int ret = 0;
    while (pc < n) {
        int op = code[pc], len = op_len(op);
        if (len <= 0) return 0;
        switch (op) {
        case OP_NOP: case OP_CONST: case OP_SMALLINT: case OP_NIL: case OP_TRUE: case OP_FALSE: case OP_POP: case OP_DUP:
        case OP_LOAD_LOCAL: case OP_STORE_LOCAL: case OP_ADD: case OP_SUB: case OP_MUL: case OP_DIV: case OP_FLOOR_DIV:
        case OP_MOD: case OP_NEG: case OP_GET_MEMBER: case OP_SET_MEMBER: case OP_LOAD_UPVAL: case OP_STORE_UPVAL:
        case OP_GET_INDEX: case OP_SET_INDEX:
            break;
        case OP_LOAD_MODULE: case OP_CALL:      /* a construction `Class(args)` (checked when the body is translated) */
            if (!calls) return 0;
            break;
        case OP_RETURN: case OP_RETURN_NIL:      /* whatever follows is unreachable (no branches) */
            return 1;
        default: return 0;
        }
        pc += (uint32_t)len;
    }
    return ret;
}

static int ictx_add(JC *c, Proto *kp, uint32_t retpc, int base_slots) {
    if (c->nic == c->capic) {
        int nc = c->capic ? c->capic * 2 : 8;
        JIctx *t = realloc(c->ic, (size_t)nc * sizeof *t);
        if (!t) return -1;
        c->ic = t;
        c->capic = nc;
    }
    c->ic[c->nic] = (JIctx){kp, retpc, base_slots, 0, c->cur_ic - 1};
    return c->nic++;
}

/* translate the callee's body in place; the frame state (locals, stack, exits) is the callee's for the duration */
static int inl_body(JC *c, const Proto *kp, const uint8_t *kcode, int argc, int pf, uint32_t pc0, int ic, SFunc *cf, const SClass *ctor) {
    int nl = kp->nlocals;
    uint8_t vt[INL_MAXLOC], vlive[INL_MAXLOC];
    const SClass *vk[INL_MAXLOC];
    const SpValue *hints[INL_MAXLOC];
    int lmap[INL_MAXCODE + 1];
    memset(vlive, 0, sizeof vlive);
    for (int i = 0; i < nl; i++) { vt[i] = 0x80 | TY_UNK; vk[i] = NULL; hints[i] = NULL; }
    for (int i = 0; i < argc; i++) {
        const Ent *a = &c->st[pf + 1 + i];
        if (a->ty == TY_MOD) return 0;
        vt[i] = (uint8_t)(0x80 | a->ty);
        hints[i] = a->hint;
        if (a->ty == TY_INST) vk[i] = a->cls;
    }
    for (uint32_t i = 0; i <= kp->code_len; i++) lmap[i] = -1;
    /* swap in the callee's frame */
    struct { Proto *p; SFunc *fn; const uint8_t *code; uint32_t hdr, end, cur_pc; int nloc, d0, dep, nvars, nmv, pin, cur_ic, pos0; int32_t bias;
             SpValue *base; uint8_t *vt, *vlive; const SClass **vk; int *lmap; uint8_t *lrd; } sv =
        {c->p, c->fn, c->code, c->hdr, c->end, c->cur_pc, c->nloc, c->d0, c->dep, c->nvars, c->nmv, c->pin, c->cur_ic, c->pos0, c->bias,
         c->base, c->vt, c->vlive, c->vk, c->lmap, c->lrd};
    uint8_t lrd_in[INL_MAXLOC];
    memset(lrd_in, 0, sizeof lrd_in);
    if (c->reg_on) {                           /* reads of each callee local: the ones read twice or more get a register mirror */
        for (uint32_t q = 0; q < kp->code_len;) {
            int o = kcode[q], l = op_len(o);
            if (l <= 0) break;
            if (o == OP_LOAD_LOCAL && q + 3 <= kp->code_len) {
                unsigned li = rd16(kcode + q + 1);
                if (li < (unsigned)nl && lrd_in[li] < 255) lrd_in[li]++;
            }
            q += (uint32_t)l;
        }
    }
    int32_t nilk = -1;
    int ok = 0;
    uint32_t pc = 0;
    int bias = soff(c, pf + 1);
    int pos0 = pf + 1 + nl;
    if (pos0 + kp->max_stack + 2 > c->stcap) return 0;
    c->p = (Proto *)(uintptr_t)kp;
    c->fn = cf;
    c->code = kcode;
    c->hdr = 0;
    c->end = kp->code_len;
    c->nloc = nl;
    c->nvars = nl;
    c->nmv = 0;
    c->pin = -1;
    c->cur_ic = ic + 1;
    c->nest++;
    c->bias = bias;
    c->pos0 = pos0;
    c->d0 = pos0;
    c->dep = pos0;
    c->base = NULL;
    c->vt = vt; c->vlive = vlive; c->vk = vk; c->lmap = lmap;
    c->lrd = c->reg_on ? lrd_in : NULL;
    lc_drop_up_kind(c, 1);                           /* another closure's variables from here on */
    /* locals beyond the arguments start out nil, as the interpreter's call leaves them */
    nilk = kadd(c, v_nil());
    if (nilk < 0) { c->why = "too many constants"; goto out; }
    for (int i = argc; i < nl; i++) { c->xe = -1; if (!em(c, ST_movk, LOFF(c, i), koff(nilk), 0, 0, 0, 0)) goto out; }
    while (pc < kp->code_len) {
        int op = kcode[pc], len = op_len(op);
        c->cur_pc = pc;
        uint32_t skip = 0;
        int r = 1;
        if ((c->rb || c->xb) && !reg_aware(op) && op != OP_RETURN && !flush_regs(c)) goto out;
        switch (op) {
        case OP_NOP: break;
        case OP_CONST: {
            unsigned k = rd16(kcode + pc + 1);
            if (k >= (unsigned)kp->nconsts) { c->why = "bad constant"; goto out; }
            int ki = kadd(c, kp->consts[k]);
            if (ki < 0) { c->why = "too many constants"; goto out; }
            Ent *e = push(c, EK_K, ty_of(&kp->consts[k], 0), ki);
            r = e != NULL;
            if (r) e->hint = &kp->consts[k];
            break;
        }
        case OP_SMALLINT: case OP_NIL: case OP_TRUE: case OP_FALSE: {
            SpValue v = op == OP_SMALLINT ? v_int((int16_t)rd16(kcode + pc + 1)) : op == OP_NIL ? v_nil() : v_bool(op == OP_TRUE);
            int k = kadd(c, v);
            if (k < 0) { c->why = "too many constants"; goto out; }
            Ent *e = push(c, EK_K, ty_of(&v, 0), k);
            r = e != NULL;
            break;
        }
        case OP_POP:
            if (c->dep <= c->d0) { c->why = "stack underflow"; goto out; }
            if (c->st[c->dep - 1].kind == EK_REG) reg_put(c, reg_is_x(&c->st[c->dep - 1]), c->st[c->dep - 1].idx);
            c->dep--;
            break;
        case OP_DUP: r = do_dup(c, 1, pc); break;
        case OP_LOAD_LOCAL: {
            unsigned i = rd16(kcode + pc + 1);
            if (i >= (unsigned)nl) { c->why = "bad local"; goto out; }
            Ent *e = push(c, EK_LOC, vt[i] & 0x7f, (int)i);
            r = e != NULL;
            if (r) { e->hint = hints[i]; if (e->ty == TY_INST) e->cls = vk[i]; }
            break;
        }
        case OP_STORE_LOCAL:
            if (ctor && rd16(kcode + pc + 1) == 0) { c->why = "constructor assigns self"; goto out; }
            r = do_store_local(c, pc);
            break;
        case OP_ADD: case OP_SUB: case OP_MUL: case OP_DIV: case OP_FLOOR_DIV: case OP_MOD:
            r = do_arith(c, op, pc, len, &skip);
            break;
        case OP_NEG: r = do_neg(c, pc, len, &skip); break;
        case OP_GET_MEMBER: r = do_get_member(c, pc, len, &skip); break;
        case OP_SET_MEMBER: r = do_set_member(c, pc); break;
        case OP_GET_INDEX: r = do_get_index(c, pc, len, &skip); break;
        case OP_SET_INDEX: r = do_set_index(c, pc); break;
        case OP_LOAD_UPVAL: r = do_load_upval(c, pc); break;
        case OP_STORE_UPVAL: r = do_store_upval(c, pc); break;
        case OP_LOAD_MODULE: {                 /* only a class that a construction below calls (guarded there) */
            int slot = (int)rd16(kcode + pc + 1);
            const SpValue *mv = &c->vm->slots[slot];
            if (ctor || mv->type != T_CLASS) { c->why = "inline: module variable"; goto out; }
            Ent *e = push(c, EK_MEM, TY_UNK, 0);
            if (!e) goto out;
            e->ppc = pc;
            e->hint = mv;
            c->xe = -1;
            r = em(c, ST_ldmod, soff(c, c->dep - 1), 0, slot * 16, 0, 0, 0);
            break;
        }
        case OP_CALL: {
            int cargc = kcode[pc + 1], pfc = c->dep - 1 - cargc;
            if (ctor || cargc > 10 || pfc != c->pos0) { c->why = "inline: call"; goto out; }
            const Ent *fe = &c->st[pfc];
            if (fe->kind != EK_MEM || !fe->hint || fe->hint->type != T_CLASS) { c->why = "inline: call"; goto out; }
            r = do_construct(c, pc, len, cargc, AS_CLASS(*fe->hint));
            break;
        }
        case OP_RETURN: case OP_RETURN_NIL: {
            int32_t dst = c->bias - 16;
            int rty = TY_UNK;
            const SpValue *rh = NULL;
            const SClass *rcls = NULL;
            c->xe = -1;
            if (op == OP_RETURN_NIL) {
                if (!ctor) r = em(c, ST_movk, dst, koff(nilk), 0, 0, 0, 0);       /* a constructor yields the instance instead (below) */
            } else {
                int p = c->dep - 1;
                if (p < c->d0) { c->why = "stack underflow"; goto out; }
                Ent *e = &c->st[p];
                rty = e->ty; rh = e->hint; rcls = e->cls;
                if (rty == TY_MOD) { c->why = "module result"; goto out; }
                if (ctor) {                      /* init's own result is dropped */
                    if (e->kind == EK_REG) reg_put(c, reg_is_x(e), e->idx);
                } else if (e->kind == EK_REG) {
                    Ent re = *e;
                    r = x_sti(c, R_R12, dst, (int32_t)tag_of(re.ty)) && (reg_is_x(&re) ? x_sd_st(c, R_R12, dst + 8, re.idx) : x_st(c, R_R12, dst + 8, re.idx));
                    reg_put(c, reg_is_x(&re), re.idx);
                } else if (e->kind == EK_K) r = em(c, ST_movk, dst, koff(e->idx), 0, 0, 0, 0);
                else r = em(c, ST_mov, dst, roff(c, e, p), 0, 0, 0, 0);
                c->dep--;
            }
            if (r && ctor) {                     /* a constructor call yields the new instance, whatever init returns */
                r = em(c, ST_mov, dst, LOFF(c, 0), 0, 0, 0, 0);
                rty = TY_INST; rh = NULL; rcls = ctor;
            }
            if (!r) goto out;
            lc_drop_scope(c);
            lc_drop_up_kind(c, 1);
            c->nloc = sv.nloc; c->bias = sv.bias; c->pos0 = sv.pos0; c->cur_ic = sv.cur_ic;
            c->dep = pf;
            Ent *re = push(c, EK_MEM, rty, 0);
            if (!re) goto out;
            re->hint = rh;
            re->cls = rcls;
            re->ppc = pc0;
            ok = 1;
            goto out;
        }
        default: c->why = "inline: unsupported instruction"; goto out;
        }
        if (!r) goto out;
        pc += (uint32_t)len + skip;
    }
out:
    c->p = sv.p; c->fn = sv.fn; c->code = sv.code; c->hdr = sv.hdr; c->end = sv.end; c->cur_pc = sv.cur_pc; c->nloc = sv.nloc;
    c->d0 = sv.d0; c->nvars = sv.nvars; c->nmv = sv.nmv; c->pin = sv.pin; c->cur_ic = sv.cur_ic; c->pos0 = sv.pos0; c->bias = sv.bias; c->nest--;
    c->base = sv.base; c->vt = sv.vt; c->vlive = sv.vlive; c->vk = sv.vk; c->lmap = sv.lmap; c->lrd = sv.lrd;
    if (!ok) { c->dep = sv.dep; c->rb = c->xb = 0; c->nlc = 0; }
    return ok ? 1 : -1;
}

static int do_call(JC *c, uint32_t pc, int len, uint32_t *skip) {
    int argc = c->code[pc + 1];
    int pf = c->dep - 1 - argc;
    if (pf < c->d0) FAIL("stack underflow");
    Ent *f = &c->st[pf];
    if (f->kind == EK_K && c->kt[f->idx].type == T_FUNCTION) {
        const NativeDesc *nd = AS_FUNC(c->kt[f->idx])->nat;
        if (!nd) FAIL("call");
        if (argc == 1 && strcmp(nd->name, "len") == 0) {
            const Ent *ae = &c->st[c->dep - 1];
            if (ae->kind != EK_K && ae->kind != EK_MOD && (ae->ty == TY_ARR || (ae->ty == TY_UNK && ae->hint && ae->hint->type == T_ARRAY)))
                return do_call_len(c, pc, len, skip);
            return emit_nat(c, pc, pf, 1, nd, TY_INT);
        }
        FAIL("call of a builtin");
    }
    if (f->kind != EK_K && f->hint && f->hint->type == T_CLASS) return do_construct(c, pc, len, argc, AS_CLASS(*f->hint));
    if (!flush_from(c, c->d0, c->dep)) return 0;
    int x = exit_for(c, pc, c->dep);
    if (x < 0) FAIL("out of memory");
    c->xe = x;
    uint64_t retpc = (uint64_t)(uintptr_t)(c->p->code + pc + (uint32_t)len);
    const Proto *kp = (f->hint && f->hint->type == T_FUNCTION) ? AS_FUNC(*f->hint)->proto : NULL;
    if (kp && kp->nparams == argc && kp->nrequired == argc && !kp->has_rest && kp->ndefaults == 0) {
        int64_t need = ((int64_t)kp->nlocals + kp->max_stack + 8) * 16;
        if (kp == c->p && c->unit) {                   /* the function calls itself */
            c->hq2 = (uint64_t)(uintptr_t)kp;
            c->tk = 3;
            c->tt = 0;
            EM(ST_ucall_s, soff(c, pf), argc, kp->nlocals, (int32_t)need, 0, retpc);
            goto called;
        }
        if (inl_enabled && c->cur_ic == 0 && kp != c->p && f->hint && f->hint->type == T_FUNCTION) {
            const uint8_t *kcode = kp->ocode ? kp->ocode : kp->code;
            if (c->vm->jit_dbg) (void)fprintf(stderr, "jit: inline? %s cand=%d\n", kp->name ? kp->name : "?", inl_candidate(kp, kcode, 1));
            if (inl_candidate(kp, kcode, 1)) {
                size_t scn = c->cn;
                int snfx = c->nfx, snex = c->nex, snic = c->nic;
                c->xe = x;
                int okk = em_ginl(c, soff(c, pf), need, kp);
                int ic = okk ? ictx_add(c, (Proto *)(uintptr_t)kp, pc + (uint32_t)len, c->nloc + pf + 1) : -1;
                if (ic >= 0 && inl_body(c, kp, kcode, argc, pf, pc, ic, AS_FUNC(*f->hint), NULL) == 1) {
                    c->rax_off = -1;
                    c->xmm_off = -1;
                    return 1;
                }
                if (c->vm->jit_dbg) (void)fprintf(stderr, "jit: inline failed: %s\n", c->why ? c->why : "?");
                c->cn = scn; c->nfx = snfx; c->nex = snex; c->nic = snic;     /* not inlinable after all: the call stays */
                c->why = NULL;
                c->rax_off = -1;
                c->xmm_off = -1;
                c->skip1 = 0;
                c->skipx = 0;
                c->dep = pf + 1 + argc;
                c->xe = x;
            }
        }
        if (kp->junit) {
            c->hq2 = (uint64_t)(uintptr_t)kp->junit;
            EM(ST_ucall_k, soff(c, pf), argc, kp->nlocals, (int32_t)need, 0, retpc);
            goto called;
        }
    }
    EM(ST_ucall, soff(c, pf), argc, 0, 0, 0, retpc);
called:
    c->dep -= argc + 1;
    Ent *r = push(c, EK_MEM, TY_UNK, 0);
    if (!r) return 0;
    r->ppc = pc;
    r->hint = &g_hint_int;
    return after_call(c, pc + (uint32_t)len);
}

static int do_return(JC *c, int op) {
    if (!c->unit) FAIL("return inside a loop region");
    c->xe = -1;
    if (op == OP_RETURN_NIL) {
        EM(c->pin >= 0 ? ST_ret_nil_p : ST_ret_nil, 0, 0, 0, 0, 0, 0);
        return 1;
    }
    int p = c->dep - 1;
    if (p < c->d0) FAIL("stack underflow");
    Ent *e = &c->st[p];
    if (e->kind == EK_MOD && !materialize(c, p)) return 0;
    c->xe = -1;
    if (e->kind == EK_K) EM(c->pin >= 0 ? ST_ret_k_p : ST_ret_k, koff(e->idx), 0, 0, 0, 0, 0);
    else EM(c->pin >= 0 ? ST_ret_r_p : ST_ret_r, roff(c, e, p), 0, 0, 0, 0, 0);
    return 1;
}

/* register holding the address of upvalue idx's cell: the mirror when there is one, else rax after the pointer chain
 * (the chain is then also kept in a register for the next access). -1: emission failed */
static int up_cell(JC *c, int idx) {
    for (int i = 0; i < c->nlc; i++)
        if (c->lc[i].up == 2 && c->lc[i].k == idx) return c->lc[i].reg;
    int ok = c->cur_ic ? x_ld(c, R_RAX, R_R12, c->bias - 16 + 8) : x_ld(c, R_RAX, R_R15, L_FR_FN);
    ok = ok && x_ld(c, R_RAX, R_RAX, L_SFUNC_UP) && x_ld(c, R_RAX, R_RAX, (int32_t)(idx * 8));
    if (!ok) return -1;
    if (c->reg_on) {
        int rc = reg_get(c, 0);
        if (rc >= 0) {
            if (!x_mov(c, rc, R_RAX)) return -1;
            lc_add_up(c, idx, 0, rc, 0);
            c->lc[c->nlc - 1].up = 2;
            return rc;
        }
    }
    return R_RAX;
}

static int do_load_upval(JC *c, uint32_t pc) {
    unsigned i = rd16(c->code + pc + 1);
    if (c->fn && i >= (unsigned)c->fn->nup) FAIL("bad upvalue");
    const SpValue *uh = c->fn ? &c->fn->up[i]->v : NULL;
    int hty = c->reg_on ? hint_ty(uh) : TY_UNK;
    if (hty != TY_UNK) {                             /* a closure variable of a predicted type: guard it and keep the payload in a register */
        int isx = hty == TY_FLT;
        int mr = lc_find_up(c, (int)i, isx, hty);
        if (mr >= 0) {                               /* read or written just now: the register still holds the value (no guard, no cell chain) */
            int rm = reg_alloc(c, isx, -1, -1);
            if (rm < 0) FAIL("no register");
            mr = lc_find_up(c, (int)i, isx, hty);    /* reg_alloc may have evicted it */
            if (mr >= 0) {
                if (!(isx ? x_sd_rr(c, 0x10, rm, mr) : x_mov(c, rm, mr))) return 0;
                Ent *re = push(c, EK_REG, hty, rm);
                if (!re) return 0;
                re->ppc = pc;
                re->hint = uh;
                return 1;
            }
            reg_put(c, isx, rm);
        }
        c->xe = gexit(c);
        if (c->xe < 0) FAIL("out of memory");
        int rd = reg_alloc(c, isx, -1, -1);
        if (rd < 0) FAIL("no register");
        int cb = up_cell(c, (int)i);
        if (cb < 0) return 0;
        int ok = x_cmpi(c, cb, L_CELL_V, (int32_t)tag_of(hty)) && x_jx(c, 5, c->xe) &&
                 (isx ? x_sd_ld(c, rd, cb, L_CELL_V + 8) : x_ld(c, rd, cb, L_CELL_V + 8));
        if (!ok) return 0;
        int rm2 = reg_get(c, isx);                   /* a second register keeps the loaded value for the next read */
        if (rm2 >= 0) {
            if (!(isx ? x_sd_rr(c, 0x10, rm2, rd) : x_mov(c, rm2, rd))) return 0;
            lc_add_up(c, (int)i, isx, rm2, hty);
        }
        Ent *re = push(c, EK_REG, hty, rd);
        if (!re) return 0;
        re->ppc = pc;
        re->hint = uh;
        return 1;
    }
    Ent *e = push(c, EK_MEM, TY_UNK, 0);
    if (!e) return 0;
    e->ppc = pc;
    e->hint = uh;
    c->xe = -1;
    if (c->cur_ic) EM(ST_ldupi, soff(c, c->dep - 1), (int32_t)(i * 8), c->bias - 16, 0, 0, 0);
    else EM(ST_ldup, soff(c, c->dep - 1), (int32_t)(i * 8), 0, 0, 0, 0);
    return 1;
}

static int do_store_upval(JC *c, uint32_t pc) {
    unsigned i = rd16(c->code + pc + 1);
    int p = c->dep - 1;
    if (p < c->d0) FAIL("stack underflow");
    Ent *e = &c->st[p];
    if (!flush_from(c, c->d0, p)) return 0;          /* a pending read of this variable must see the old value */
    e = &c->st[p];
    if (e->kind == EK_MOD && !materialize(c, p)) return 0;
    lc_drop_up(c);                                   /* whatever the mirrors held, the cell changes now */
    c->xe = -1;
    if (e->kind == EK_REG) {
        Ent re = *e;
        int cb = up_cell(c, (int)i);
        if (cb < 0) return 0;
        int ok = x_sti(c, cb, L_CELL_V, (int32_t)tag_of(re.ty)) &&
                 (reg_is_x(&re) ? x_sd_st(c, cb, L_CELL_V + 8, re.idx) : x_st(c, cb, L_CELL_V + 8, re.idx));
        if (ok && c->reg_on && (re.ty == TY_INT || re.ty == TY_FLT)) lc_add_up(c, (int)i, reg_is_x(&re), re.idx, re.ty);   /* the stored value stays in its register */
        else reg_put(c, reg_is_x(&re), re.idx);
        c->dep--;
        return ok;
    }
    if (c->cur_ic) {
        if (e->kind == EK_K) EM(ST_stupki, koff(e->idx), (int32_t)(i * 8), c->bias - 16, 0, 0, 0);
        else EM(ST_stupi, roff(c, e, p), (int32_t)(i * 8), c->bias - 16, 0, 0, 0);
    } else if (e->kind == EK_K) EM(ST_stupk, koff(e->idx), (int32_t)(i * 8), 0, 0, 0, 0);
    else EM(ST_stup, roff(c, e, p), (int32_t)(i * 8), 0, 0, 0, 0);
    c->dep--;
    return 1;
}

typedef int (*LoopHelper)(VM *vm, SpValue *st, SpValue *dst, unsigned n);
static int do_for_next_tab(JC *c, uint32_t pc, uint32_t *skip, int s, int n, int32_t off, LoopHelper helper);
/* for i, x in typed array / for x in typed array: the same state layout as an array loop (array, cursor) */
static int jh_anext(VM *vm, SpValue *st, SpValue *dst, unsigned n) {
    (void)vm;
    if (st[1].type != T_INT || st[1].as.i < 0 || !typed_is(st[0])) return 0;
    int64_t cur = st[1].as.i;
    if (cur >= typed_len(st[0])) return 2;
    SpValue ev;
    if (!typed_peek(st[0], v_int(cur), &ev)) return 0;
    st[1] = v_int(cur + 1);
    if (n == 2) { dst[0] = v_int(cur); dst[1] = ev; }
    else dst[0] = ev;
    return 1;
}
/* for k, v in table / for k in table: the helper steps the interpreter's own loop state (table, cursor, version) */
static int jh_tnext(VM *vm, SpValue *st, SpValue *dst, unsigned n) {
    (void)vm;
    if (st[0].type != T_TABLE || st[1].type != T_INT || st[1].as.i < 0 || st[2].type != T_INT) return 0;
    STable *t = AS_TABLE(st[0]);
    if ((int64_t)t->version != st[2].as.i) return 0;                 /* "modified during iteration": the interpreter reports it */
    SpValue k, v;
    int64_t nx = table_next(t, st[1].as.i, &k, &v);
    if (nx < 0) return 2;
    st[1] = v_int(nx);
    dst[0] = k;
    if (n == 2) dst[1] = v;
    return 1;
}

static int do_for_next_tab(JC *c, uint32_t pc, uint32_t *skip, int s, int n, int32_t off, LoopHelper helper) {
    if (!flush_regs(c) || !flush_from(c, c->d0, c->dep)) return 0;
    int dl = -1;
    if (n == 1 && !fuse_store(c, pc + 8, c->dep, &dl)) return 0;
    int32_t dst = dl >= 0 ? LOFF(c, dl) : soff(c, c->dep);
    if (!set_target(c, pc + 8 + (uint32_t)off, pc, 0)) return 0;
    c->xe = gexit(c);
    if (c->xe < 0) FAIL("out of memory");
    EM(ST_tnext, dst, s * 16, n, 0, 0, (uint64_t)(uintptr_t)helper);
    c->rax_off = -1; c->xmm_off = -1; c->skip1 = 0; c->skipx = 0;
    if (dl >= 0) {
        c->vt[dl] = 0x80 | TY_UNK;
        *skip = 3;
        return 1;
    }
    Ent *k = push(c, EK_MEM, TY_UNK, 0);
    if (!k) return 0;
    k->ppc = pc;
    if (n == 2) {
        Ent *v = push(c, EK_MEM, TY_UNK, 0);
        if (!v) return 0;
        v->ppc = pc;
    }
    return 1;
}

/* for x in array / for i, x in array */
static int do_for_next(JC *c, uint32_t pc, uint32_t *skip) {
    int s = (int)rd16(c->code + pc + 1), n = c->code[pc + 3];
    int32_t off = rd32s(c->code + pc + 4);
    if (s + 2 >= c->nloc || (n != 1 && n != 2)) FAIL("for-in");
    for (int i = 0; i < 2; i++)
        if (!(c->vt[s + i] & 0x80)) c->vlive[s + i] = 1;
    if ((c->vt[s] & 0x7f) == TY_UNK && c->base[s].type == T_TABLE && (c->vt[s + 1] & 0x7f) == TY_INT && (c->vt[s + 2] & 0x7f) == TY_INT)
        return do_for_next_tab(c, pc, skip, s, n, off, jh_tnext);
    if ((c->vt[s] & 0x7f) == TY_UNK && c->base[s].type == T_NATIVE && typed_is(c->base[s]) && (c->vt[s + 1] & 0x7f) == TY_INT && (c->vt[s + 2] & 0x7f) == TY_INT)
        return do_for_next_tab(c, pc, skip, s, n, off, jh_anext);
    if ((c->vt[s] & 0x7f) != TY_ARR || (c->vt[s + 1] & 0x7f) != TY_INT) FAIL("for-in over a non-array");
    if (!flush_from(c, c->d0, c->dep)) return 0;
    const SpValue *hint = NULL;
    if (c->base[s].type == T_ARRAY && AS_ARRAY(c->base[s])->len > 0) hint = &AS_ARRAY(c->base[s])->items[0];
    int32_t lo = (int32_t)offsetof(SArray, len), io = (int32_t)offsetof(SArray, items);
    int dl = -1;
    if (n == 1 && !fuse_store(c, pc + 8, c->dep, &dl)) return 0;
    int32_t dst = dl >= 0 ? LOFF(c, dl) : soff(c, c->dep);
    if (!set_target(c, pc + 8 + (uint32_t)off, pc, 0)) return 0;
    c->xe = -1;
    if (n == 1) EM(ST_arr_next, dst, s * 16, 0, lo, io, 0);
    else EM(ST_arr_next2, dst, s * 16, 0, lo, io, 0);
    if (dl >= 0) {
        c->vt[dl] = 0x80 | TY_UNK;
        *skip = 3;
        return 1;
    }
    if (n == 2) {
        Ent *i = push(c, EK_MEM, TY_INT, 0);
        if (!i) return 0;
        i->ppc = pc;
    }
    Ent *v = push(c, EK_MEM, TY_UNK, 0);
    if (!v) return 0;
    v->ppc = pc;
    v->hint = hint;
    return 1;
}

/* ---- containers other than typed arrays, and string concatenation: C helpers ---------------------------------------- */
/* They return 0 for anything they do not handle without having changed anything, and the compiled code then leaves for the
 * interpreter, which runs the instruction (and raises its errors) as always. The collector may run inside them: the stencil
 * publishes the stack top first. */
static int jh_getidx(VM *vm, const SpValue *o, const SpValue *k, SpValue *dst) {
    SpValue r;
    switch (o->type) {
    case T_TABLE:
        if (k->type != T_STRING && k->type != T_INT) return 0;
        if (table_get(vm, AS_TABLE(*o), *k, &r, NULL)) return 0;
        break;
    case T_ARRAY: {
        const SArray *a = AS_ARRAY(*o);
        if (k->type != T_INT || k->as.i < 0 || k->as.i >= a->len) return 0;
        r = a->items[k->as.i];
        break;
    }
    case T_STRING: {
        const SString *st = AS_STR(*o);
        if (k->type != T_INT || k->as.i < 0 || k->as.i >= (int64_t)st->len) return 0;
        r = v_int((unsigned char)st->data[k->as.i]);
        break;
    }
    case T_NATIVE:
        if (!typed_is(*o) || !typed_peek(*o, *k, &r)) return 0;
        break;
    default: return 0;
    }
    *dst = r;
    return 1;
}
/* a pure native (see math_pure_native / len): on an error, or a result whose type is not the one the compiled code
 * expects, nothing is changed and the interpreter runs the call again */
static int jh_nat(VM *vm, SpValue *argv, unsigned argc, SpValue *dst, NativeFn fn, unsigned want) {
    int code = vm->pend_code;
    SpValue po = vm->pend_obj;
    SpValue r = v_nil();
    if (fn(vm, (int)argc, argv, &r)) {
        vm->pend_code = code;
        vm->pend_obj = po;
        return 0;
    }
    if (want != 0xffu && (unsigned)r.type != want) return 0;
    *dst = r;
    return 1;
}
static int jh_setidx(VM *vm, const SpValue *o, const SpValue *k, const SpValue *v) {
    if (vm->bytes >= vm->gc_next) vm_gc(vm);
    if (o->type == T_TABLE) {
        if (k->type != T_STRING && k->type != T_INT) return 0;
        return table_set(vm, AS_TABLE(*o), *k, *v) == 0;
    }
    if (o->type == T_ARRAY) {
        SArray *a = AS_ARRAY(*o);
        if (k->type != T_INT || k->as.i < 0 || k->as.i >= a->len) return 0;
        a->items[k->as.i] = *v;
        return 1;
    }
    if (o->type == T_NATIVE) return typed_is(*o) && typed_poke(*o, *k, *v);
    return 0;
}
static int jh_concat(VM *vm, const SpValue *ops, unsigned n, SpValue *dst) {
    if (vm->bytes >= vm->gc_next) vm_gc(vm);
    SString *s = vm_concat_fast(vm, ops, n);
    if (!s) return 0;
    *dst = v_obj(T_STRING, s);
    return 1;
}

/* the container is known (from the value seen at compile time) to be a table or a string, not a typed array */
static int hint_is_container(const Ent *a) {
    return a->ty != TY_ARR && a->hint && (a->hint->type == T_TABLE || a->hint->type == T_STRING || (a->hint->type == T_NATIVE && typed_is(*a->hint)));
}

static int do_get_index_h(JC *c, uint32_t pc) {
    int pb = c->dep - 1, pa = c->dep - 2;
    if (!flush_regs(c)) return 0;
    for (int q = pa; q <= pb; q++) if (c->st[q].kind != EK_MEM && c->st[q].kind != EK_LOC && !materialize(c, q)) return 0;
    Ent *a = &c->st[pa], *b = &c->st[pb];
    c->xe = gexit(c);
    if (c->xe < 0) FAIL("out of memory");
    EM(ST_hget, soff(c, pa), roff(c, a, pa), roff(c, b, pb), 0, 0, (uint64_t)(uintptr_t)jh_getidx);
    c->dep -= 2;
    Ent *r = push(c, EK_MEM, TY_UNK, 0);
    if (!r) return 0;
    r->ppc = pc;
    c->rax_off = -1; c->xmm_off = -1; c->skip1 = 0; c->skipx = 0;
    return 1;
}

static int do_set_index_h(JC *c) {
    int pv = c->dep - 1, pi = c->dep - 2, pa = c->dep - 3;
    if (!flush_regs(c)) return 0;
    for (int q = pa; q <= pv; q++) if (c->st[q].kind != EK_MEM && c->st[q].kind != EK_LOC && !materialize(c, q)) return 0;
    Ent *a = &c->st[pa], *i = &c->st[pi], *v = &c->st[pv];
    c->xe = gexit(c);
    if (c->xe < 0) FAIL("out of memory");
    EM(ST_hset, soff(c, c->dep), roff(c, a, pa), roff(c, i, pi), roff(c, v, pv), 0, (uint64_t)(uintptr_t)jh_setidx);
    c->dep -= 3;
    c->rax_off = -1; c->xmm_off = -1; c->skip1 = 0; c->skipx = 0;
    return 1;
}

static int do_concat(JC *c, uint32_t pc) {
    int n = c->code[pc + 1];
    int p0 = c->dep - n;
    if (n < 2 || n > 16 || p0 < c->d0) FAIL("concatenation");
    if (!flush_regs(c)) return 0;
    if (!flush_from(c, p0, c->dep)) return 0;      /* the operands go to consecutive stack slots */
    c->xe = gexit(c);
    if (c->xe < 0) FAIL("out of memory");
    EM(ST_hconcat, soff(c, p0), soff(c, p0), n, soff(c, c->dep), 0, (uint64_t)(uintptr_t)jh_concat);
    c->dep -= n;
    Ent *r = push(c, EK_MEM, TY_UNK, 0);
    if (!r) return 0;
    r->ppc = pc;
    c->rax_off = -1; c->xmm_off = -1; c->skip1 = 0; c->skipx = 0;
    return 1;
}

/* ---- typed arrays: guard (tag, class), bounds check, then the element straight from the payload ------------------------ */
/* kind of the typed array this entry was seen to hold, or -1. Only a local or a materialised stack slot qualifies: the
 * guard reads its tag and pointer from memory. */
static int ta_kind(const Ent *a) {
    if (a->ty != TY_UNK || (a->kind != EK_LOC && a->kind != EK_MEM) || !a->hint || a->hint->type != T_NATIVE || !typed_is(*a->hint)) return -1;
    return typed_kind(*a->hint);
}
static const uint8_t ta_shift[TK_COUNT] = {0, 0, 1, 1, 2, 2, 3, 2, 3};

/* mov rax, &elem[index]: leaves rax at the element after the checks; the guards leave through c->xe */
static int ta_addr(JC *c, int kind, const Ent *ae, int pa, const Ent *ie, int pi, int64_t kk) {
    if (!x_cmpi(c, R_R12, roff(c, ae, pa), (int32_t)T_NATIVE) || !x_jx(c, 5, c->xe)) return 0;
    const NativeClass *tcls = typed_class(kind);
    if (!x_ld(c, R_RAX, R_R12, roff(c, ae, pa) + 8) || !x_movi(c, R_RDX, (int64_t)(intptr_t)tcls) ||
        !x_mem(c, 0, 1, 0x3b, -1, R_RDX, R_RAX, (int32_t)offsetof(SNativeObj, cls)) || !x_jx(c, 5, c->xe) ||
        !x_ld(c, R_RAX, R_RAX, (int32_t)offsetof(SNativeObj, data))) return 0;
    if (ie->kind == EK_K) { if (!x_movi(c, R_RCX, kk)) return 0; }
    else if (ie->kind == EK_REG) { if (!x_mov(c, R_RCX, ie->idx)) return 0; }
    else if (!x_ldop(c, R_RCX, ie, pi)) return 0;
    if (!x_mem(c, 0, 1, 0x3b, -1, R_RCX, R_RAX, 0) || !x_jx(c, 3, c->xe)) return 0;
    if (ta_shift[kind]) {
        uint8_t sh = ta_shift[kind];
        if (!x_rr(c, 0, 1, 0xc1, -1, 4, R_RCX) || !xput(c, &sh, 1)) return 0;
    }
    return x_rr(c, 0, 1, 0x03, -1, R_RAX, R_RCX);
}

static int do_get_index_ta(JC *c, int kind, int pa, int pb) {
    Ent *a = &c->st[pa], *b = &c->st[pb];
    if (!c->reg_on || !need(c, pb, TY_INT)) FAIL("typed index");
    int64_t kk = b->kind == EK_K ? c->kt[b->idx].as.i : 0;
    if (b->kind == EK_MOD || (b->kind == EK_K && (kk < 0 || kk >= (1 << 24)))) FAIL("typed index operand");
    c->xe = gexit(c);
    if (c->xe < 0) FAIL("out of memory");
    Ent ae = *a, be = *b;
    uint32_t ppc = a->ppc;
    int isf = kind == TK_F32 || kind == TK_F64;
    int rr = reg_alloc(c, isf, pa, pb);
    if (rr < 0) FAIL("no register");
    if (!ta_addr(c, kind, &ae, pa, &be, pb, kk)) return 0;
    int32_t d = TYPED_DATA_OFF;
    int ok;
    switch ((TKind)kind) {
    case TK_I8: ok = x_mem(c, 0, 1, 0x0f, 0xbe, rr, R_RAX, d); break;
    case TK_U8: ok = x_mem(c, 0, 0, 0x0f, 0xb6, rr, R_RAX, d); break;
    case TK_I16: ok = x_mem(c, 0, 1, 0x0f, 0xbf, rr, R_RAX, d); break;
    case TK_U16: ok = x_mem(c, 0, 0, 0x0f, 0xb7, rr, R_RAX, d); break;
    case TK_I32: ok = x_mem(c, 0, 1, 0x63, -1, rr, R_RAX, d); break;
    case TK_U32: ok = x_mem(c, 0, 0, 0x8b, -1, rr, R_RAX, d); break;
    case TK_F32: ok = x_mem(c, 0xf3, 0, 0x0f, 0x5a, rr, R_RAX, d); break;
    case TK_F64: ok = x_sd_ld(c, rr, R_RAX, d); break;
    case TK_I64: case TK_COUNT: default: ok = x_ld(c, rr, R_RAX, d); break;
    }
    if (!ok) return 0;
    if (be.kind == EK_REG) reg_put(c, 0, be.idx);
    c->dep -= 2;
    Ent *r = push(c, EK_REG, isf ? TY_FLT : TY_INT, rr);
    if (!r) return 0;
    r->ppc = ppc;
    return 1;
}

static int do_set_index_ta(JC *c, int kind, int pa, int pi, int pv) {
    Ent *i = &c->st[pi], *v = &c->st[pv];
    int isf = kind == TK_F32 || kind == TK_F64;
    if (!c->reg_on || !need(c, pi, TY_INT)) FAIL("typed index");
    if (v->kind == EK_MOD || v->ty == TY_MOD) return do_set_index_h(c);
    if (v->ty == TY_UNK) {
        int w = isf ? (hint_ty(v->hint) == TY_INT ? TY_INT : TY_FLT) : TY_INT;
        if (!need(c, pv, w)) return do_set_index_h(c);
    }
    /* a value that can never be stored (a float into an integer array, a bool, ...) leaves for the interpreter, which raises */
    if (isf ? (v->ty != TY_INT && v->ty != TY_FLT) : v->ty != TY_INT) return do_set_index_h(c);
    int64_t kk = i->kind == EK_K ? c->kt[i->idx].as.i : 0;
    if (i->kind == EK_MOD || (i->kind == EK_K && (kk < 0 || kk >= (1 << 24)))) FAIL("typed index operand");
    if (!flush_from(c, c->d0, pa)) return 0;
    c->xe = gexit(c);
    if (c->xe < 0) FAIL("out of memory");
    Ent ae = c->st[pa], ie = c->st[pi], ve = c->st[pv];
    if (!ta_addr(c, kind, &ae, pa, &ie, pi, kk)) return 0;
    int32_t d = TYPED_DATA_OFF;
    int xs = 0;
    if (ve.ty == TY_FLT) {                                     /* the value in an xmm register (xmm0 when it comes from memory) */
        if (ve.kind == EK_REG) xs = ve.idx;
        else if (!x_sd_ld(c, 0, ve.kind == EK_K ? R_R13 : R_R12, (ve.kind == EK_K ? koff(ve.idx) : roff(c, &ve, pv)) + 8)) return 0;
    } else {                                                   /* the integer payload in rdx */
        int ok = ve.kind == EK_REG ? x_mov(c, R_RDX, ve.idx)
               : ve.kind == EK_K ? x_ld(c, R_RDX, R_R13, koff(ve.idx) + 8) : x_ldop(c, R_RDX, &ve, pv);
        if (!ok) return 0;
        if (isf && !x_rr(c, 0xf2, 1, 0x0f, 0x2a, 0, R_RDX)) return 0;   /* cvtsi2sd xmm0, rdx */
    }
    int ok;
    switch ((TKind)kind) {
    case TK_I8: case TK_U8: ok = x_mem(c, 0, 0, 0x88, -1, R_RDX, R_RAX, d); break;
    case TK_I16: case TK_U16: ok = x_mem(c, 0x66, 0, 0x89, -1, R_RDX, R_RAX, d); break;
    case TK_I32: case TK_U32: ok = x_mem(c, 0, 0, 0x89, -1, R_RDX, R_RAX, d); break;
    case TK_F32: ok = x_sd_rr(c, 0x5a, 0, xs) && x_mem(c, 0xf3, 0, 0x0f, 0x11, 0, R_RAX, d); break;
    case TK_F64: ok = x_sd_st(c, R_RAX, d, xs); break;
    case TK_I64: case TK_COUNT: default: ok = x_st(c, R_RAX, d, R_RDX); break;
    }
    if (!ok) return 0;
    if (ie.kind == EK_REG) reg_put(c, 0, ie.idx);
    if (ve.kind == EK_REG) reg_put(c, reg_is_x(&ve), ve.idx);
    c->dep -= 3;
    return 1;
}

static int do_get_index(JC *c, uint32_t pc, int len, uint32_t *skip) {
    int pb = c->dep - 1, pa = c->dep - 2;
    if (pa < c->d0) FAIL("stack underflow");
    Ent *a = &c->st[pa], *b = &c->st[pb];
    {
        int tk = ta_kind(a);
        if (tk >= 0 && c->reg_on && (b->kind == EK_LOC || b->kind == EK_REG || b->kind == EK_MEM || b->kind == EK_K)) return do_get_index_ta(c, tk, pa, pb);
    }
    if (a->kind != EK_K && a->kind != EK_MOD && hint_is_container(a)) { (void)len; (void)skip; return do_get_index_h(c, pc); }
    if (a->kind == EK_K || a->kind == EK_MOD) FAIL("index of a constant");
    if (!need(c, pa, TY_ARR) || !need(c, pb, TY_INT)) FAIL("index types");
    int32_t so = (int32_t)offsetof(SArray, len), io = (int32_t)offsetof(SArray, items);
    const SpValue *hint = NULL;
    if (a->hint && a->hint->type == T_ARRAY && AS_ARRAY(*a->hint)->len > 0) hint = &AS_ARRAY(*a->hint)->items[0];
    int ety = hint ? ty_of(hint, 0) : TY_UNK;
    int64_t kk = b->kind == EK_K ? c->kt[b->idx].as.i : 0;
    if (c->reg_on && (ety == TY_INT || ety == TY_FLT || ety == TY_ARR) && (a->kind == EK_LOC || a->kind == EK_REG) &&
        (b->kind == EK_LOC || b->kind == EK_REG || b->kind == EK_MEM || (b->kind == EK_K && kk >= 0 && kk < (1 << 24)))) {
        c->xe = gexit(c);
        if (c->xe < 0) FAIL("out of memory");
        Ent ae = *a, be = *b;
        uint32_t ppc = a->ppc;
        int ra = ae.kind == EK_REG ? ae.idx : reg_alloc(c, 0, pa, pb);
        if (ra < 0) FAIL("no register");
        if (ae.kind != EK_REG && !x_ldop(c, ra, &ae, pa)) return 0;
        int32_t ed = 0;
        if (be.kind == EK_K) {
            if (!x_cmpi(c, ra, so, (int32_t)kk) || !x_jx(c, 6, c->xe) || !x_ld(c, R_RAX, ra, io)) return 0;
            ed = (int32_t)(kk * 16);
        } else {
            if (be.kind == EK_REG ? !x_mov(c, R_RCX, be.idx) : !x_ldop(c, R_RCX, &be, pb)) return 0;
            if (!x_mem(c, 0, 1, 0x3b, -1, R_RCX, ra, so) || !x_jx(c, 3, c->xe) || !x_ld(c, R_RAX, ra, io)) return 0;
            uint8_t sh = 4;
            if (!x_rr(c, 0, 1, 0xc1, -1, 4, R_RCX) || !xput(c, &sh, 1) || !x_rr(c, 0, 1, 0x03, -1, R_RAX, R_RCX)) return 0;
        }
        if (!x_cmpi(c, R_RAX, ed, (int32_t)tag_of(ety)) || !x_jx(c, 5, c->xe)) return 0;
        int rr = ra;
        if (ety == TY_FLT) {
            rr = reg_alloc(c, 1, pa, pb);
            if (rr < 0) FAIL("no register");
            if (!x_sd_ld(c, rr, R_RAX, ed + 8)) return 0;
            reg_put(c, 0, ra);
        } else if (!x_ld(c, ra, R_RAX, ed + 8)) return 0;
        if (be.kind == EK_REG) reg_put(c, 0, be.idx);
        c->dep -= 2;
        Ent *r = push(c, EK_REG, ety, rr);
        if (!r) return 0;
        r->ppc = ppc;
        r->hint = hint;
        return 1;
    }
    if (!flush_regs(c)) return 0;
    a = &c->st[pa]; b = &c->st[pb];
    int dl;
    if (!fuse_store(c, pc + (uint32_t)len, pa, &dl)) return 0;
    int32_t dst = dl >= 0 ? LOFF(c, dl) : soff(c, pa);
    c->xe = gexit(c);
    if (c->xe < 0) FAIL("out of memory");
    if (b->kind == EK_K) EM(ST_getidx_rk, dst, roff(c, a, pa), koff(b->idx), so, io, 0);
    else EM(ST_getidx_rr, dst, roff(c, a, pa), roff(c, b, pb), so, io, 0);
    c->dep -= 2;
    if (dl >= 0) {
        c->vt[dl] = 0x80 | TY_UNK;
        *skip = 3;
    } else {
        Ent *r = push(c, EK_MEM, TY_UNK, 0);
        if (!r) return 0;
        r->ppc = pc;
        r->hint = hint;
    }
    return 1;
}

static int do_set_index(JC *c, uint32_t pc) {
    (void)pc;
    int pv = c->dep - 1, pi = c->dep - 2, pa = c->dep - 3;
    if (pa < c->d0) FAIL("stack underflow");
    Ent *a = &c->st[pa], *i = &c->st[pi], *v = &c->st[pv];
    {
        int tk = ta_kind(a);
        if (tk >= 0 && c->reg_on && v->kind != EK_MOD && (i->kind == EK_LOC || i->kind == EK_REG || i->kind == EK_MEM || i->kind == EK_K)) return do_set_index_ta(c, tk, pa, pi, pv);
    }
    if (a->kind != EK_K && a->kind != EK_MOD && hint_is_container(a) && a->hint->type != T_STRING) return do_set_index_h(c);
    if (a->kind == EK_K || a->kind == EK_MOD) FAIL("index of a constant");
    if (!need(c, pa, TY_ARR) || !need(c, pi, TY_INT)) FAIL("index types");
    int32_t so = (int32_t)offsetof(SArray, len), io = (int32_t)offsetof(SArray, items);
    int64_t kk = i->kind == EK_K ? c->kt[i->idx].as.i : 0;
    if (c->reg_on && v->kind != EK_MOD && v->ty != TY_MOD && a->kind != EK_MOD && (i->kind != EK_K || (kk >= 0 && kk < (1 << 24)))) {
        if (!flush_from(c, c->d0, pa)) return 0;
        c->xe = gexit(c);
        if (c->xe < 0) FAIL("out of memory");
        Ent ae = *a, ie = *i, ve = *v;
        int rp = ae.kind == EK_REG ? ae.idx : R_RDX;
        if (ae.kind != EK_REG && !x_ld(c, R_RDX, R_R12, roff(c, &ae, pa) + 8)) return 0;
        int32_t ed = 0;
        if (ie.kind == EK_K) {
            if (!x_cmpi(c, rp, so, (int32_t)kk) || !x_jx(c, 6, c->xe) || !x_ld(c, R_RAX, rp, io)) return 0;
            ed = (int32_t)(kk * 16);
        } else {
            if (ie.kind == EK_REG ? !x_mov(c, R_RCX, ie.idx) : !x_ld(c, R_RCX, R_R12, roff(c, &ie, pi) + 8)) return 0;
            uint8_t sh = 4;
            if (!x_mem(c, 0, 1, 0x3b, -1, R_RCX, rp, so) || !x_jx(c, 3, c->xe) || !x_ld(c, R_RAX, rp, io) ||
                !x_rr(c, 0, 1, 0xc1, -1, 4, R_RCX) || !xput(c, &sh, 1) || !x_rr(c, 0, 1, 0x03, -1, R_RAX, R_RCX)) return 0;
        }
        int ok;
        if (ve.kind == EK_REG) {
            ok = x_sti(c, R_RAX, ed, (int32_t)tag_of(ve.ty)) && (reg_is_x(&ve) ? x_sd_st(c, R_RAX, ed + 8, ve.idx) : x_st(c, R_RAX, ed + 8, ve.idx));
        } else {
            int base = ve.kind == EK_K ? R_R13 : R_R12;
            int32_t o = ve.kind == EK_K ? koff(ve.idx) : roff(c, &ve, pv);
            ok = x_ld(c, R_RCX, base, o) && x_ld(c, R_RDX, base, o + 8) && x_st(c, R_RAX, ed, R_RCX) && x_st(c, R_RAX, ed + 8, R_RDX);
        }
        if (!ok) return 0;
        if (ae.kind == EK_REG) reg_put(c, 0, ae.idx);
        if (ie.kind == EK_REG) reg_put(c, 0, ie.idx);
        if (ve.kind == EK_REG) reg_put(c, reg_is_x(&ve), ve.idx);
        c->dep -= 3;
        return 1;
    }
    if (!flush_regs(c)) return 0;
    a = &c->st[pa]; i = &c->st[pi]; v = &c->st[pv];
    if (i->kind == EK_K && !materialize(c, pi)) return 0;
    if (v->kind == EK_MOD && !materialize(c, pv)) return 0;
    if (!flush_from(c, c->d0, pa)) return 0;
    c->xe = gexit(c);
    if (c->xe < 0) FAIL("out of memory");
    if (v->kind == EK_K) EM(ST_setidx_rk, roff(c, a, pa), roff(c, i, pi), koff(v->idx), so, io, 0);
    else EM(ST_setidx_rr, roff(c, a, pa), roff(c, i, pi), roff(c, v, pv), so, io, 0);
    c->dep -= 3;
    return 1;
}

static int do_store_local(JC *c, uint32_t pc) {
    (void)pc;
    int k = (int)rd16(c->code + pc + 1), p = c->dep - 1;
    if (p < c->d0) FAIL("stack underflow");
    if (k >= c->nloc) FAIL("bad local");
    Ent e = c->st[p];
    c->dep--;
    lc_drop(c, k);
    for (int i = c->pos0; i < c->dep; i++)   /* pending reads of this local must see the old value (a register chain may replay a read of it) */
        if (((c->st[i].kind == EK_LOC && c->st[i].idx == k) || c->st[i].kind == EK_REG) && !materialize(c, i)) return 0;
    c->xe = -1;
    if (e.kind == EK_REG) {
        int32_t lo = LOFF(c, k);
        int tagok = (c->vt[k] & 0x7f) == e.ty && ((c->vt[k] & 0x80) || c->vlive[k]);   /* the tag in memory is already right (written here, or guarded at entry) */
        int ok = tagok ? 1 : x_sti(c, R_R12, lo, (int32_t)tag_of(e.ty));
        ok = ok && (reg_is_x(&e) ? x_sd_st(c, R_R12, lo + 8, e.idx) : x_st(c, R_R12, lo + 8, e.idx));
        if (lc_ok(c, k) && c->lrd[k] > 0 && (e.ty == TY_INT || e.ty == TY_FLT)) lc_add(c, k, reg_is_x(&e), e.idx);   /* the value stays in its register as the local's mirror */
        else reg_put(c, reg_is_x(&e), e.idx);
        if (!ok) return 0;
        if (k == c->pin && !(reg_is_x(&e) ? x_ld(c, R_RBP, R_R12, lo + 8) : x_mov(c, R_RBP, e.idx))) return 0;
    }
    else if (e.kind == EK_MEM) EM(ST_mov, LOFF(c, k), soff(c, p), 0, 0, 0, 0);
    else if (e.kind == EK_LOC) { if (e.idx != k) EM(ST_mov, LOFF(c, k), LOFF(c, e.idx), 0, 0, 0, 0); }
    else if (e.kind == EK_K) EM(ST_movk, LOFF(c, k), koff(e.idx), 0, 0, 0, 0);
    else EM(ST_ldmod, k * 16, 0, c->mslot[e.idx] * 16, 0, 0, 0);
    if (k == c->pin && e.kind != EK_REG) EM(ST_ldp, k * 16, 0, 0, 0, 0, 0);
    int sty = e.ty == TY_MOD ? TY_UNK : e.ty;
    if (sty == TY_INST) {                       /* a variable keeps one class for the whole compilation */
        if (!c->vk[k]) c->vk[k] = e.cls;
        if (c->vk[k] != e.cls) sty = TY_UNK;
    }
    c->vt[k] = (uint8_t)(0x80 | sty);
    return 1;
}

static int do_store_module(JC *c, uint32_t pc) {
    int slot = (int)rd16(c->code + pc + 1), p = c->dep - 1;
    if (p < c->d0) FAIL("stack underflow");
    int v = mvar(c, slot);
    if (v < 0) FAIL("module variable");
    Ent *e = &c->st[p];
    if ((c->vt[v] & 0x7f) == TY_MOD || e->ty == TY_MOD) FAIL("module object assignment");
    if (e->kind == EK_K || e->kind == EK_MOD) { if (!materialize(c, p)) return 0; }
    c->xe = -1;
    if (e->kind == EK_REG) {                     /* register -> variable, without the detour through a stack slot */
        for (int i = c->pos0; i < p; i++)        /* pending register chains must not replay a read of the old value */
            if (c->st[i].kind == EK_REG && !materialize(c, i)) return 0;
        e = &c->st[p];
        int isx = reg_is_x(e);
        int tagok = (c->vt[v] & 0x7f) == e->ty && ((c->vt[v] & 0x80) || c->vlive[v]);
        int ok = tagok ? 1 : x_sti(c, R_R14, slot * 16, (int32_t)tag_of(e->ty));
        ok = ok && (isx ? x_sd_st(c, R_R14, slot * 16 + 8, e->idx) : x_st(c, R_R14, slot * 16 + 8, e->idx));
        reg_put(c, isx, e->idx);
        if (!ok) return 0;
    } else
    EM(ST_stmod, slot * 16, 0, roff(c, e, p), 0, 0, 0);
    int sty = e->ty;
    if (sty == TY_INST) {                        /* a variable keeps one class for the whole compilation */
        if (!c->reg_on) sty = TY_UNK;
        else {
            if (!c->vk[v]) c->vk[v] = e->cls;
            if (c->vk[v] != e->cls) sty = TY_UNK;
        }
    }
    c->vt[v] = (uint8_t)(0x80 | sty);
    c->dep--;
    return 1;
}

static int do_load_module(JC *c, uint32_t pc) {
    int slot = (int)rd16(c->code + pc + 1);
    int v = mvar(c, slot);
    if (v < 0) FAIL("module variable");
    int ty = c->vt[v] & 0x7f;
    if (!(c->vt[v] & 0x80)) c->vlive[v] = 1;
    if (ty == TY_MOD) {
        Ent *e = push(c, EK_MOD, TY_MOD, v - c->nloc);
        if (!e) return 0;
        e->hint = &c->vm->slots[slot];
        return 1;
    }
    if (c->reg_on && (ty == TY_INT || ty == TY_FLT || ty == TY_INST)) {      /* a typed variable: its payload straight into a register */
        int isx = ty == TY_FLT;
        int r = reg_alloc(c, isx, c->dep, -1);
        if (r < 0) FAIL("no register");
        c->xe = -1;
        if (!(isx ? x_sd_ld(c, r, R_R14, slot * 16 + 8) : x_ld(c, r, R_R14, slot * 16 + 8))) return 0;
        Ent *e = push(c, EK_REG, ty, r);
        if (!e) return 0;
        e->hint = &c->vm->slots[slot];
        if (ty == TY_INST) e->cls = c->vk[v];
        return 1;
    }
    int x = ty == TY_UNK ? gexit(c) : 0;
    if (x < 0) FAIL("out of memory");
    Ent *e = push(c, EK_MEM, ty, 0);
    if (!e) return 0;
    e->hint = &c->vm->slots[slot];
    if (ty == TY_INST) e->cls = c->vk[v];
    c->xe = -1;
    EM(ST_ldmod, soff(c, c->dep - 1), 0, slot * 16, 0, 0, 0);
    if (ty == TY_UNK) {                       /* an uninitialised module variable is an error the interpreter raises */
        c->xe = x;
        EM(ST_gntag, soff(c, c->dep - 1), T_UNINIT, 0, 0, 0, 0);
    }
    return 1;
}

static int do_neg(JC *c, uint32_t pc, int len, uint32_t *skip) {
    int p = c->dep - 1;
    if (p < c->d0) FAIL("stack underflow");
    Ent *a = &c->st[p];
    if (a->ty == TY_UNK) {
        int w = hint_ty(a->hint);
        if (w == TY_UNK || !need(c, p, w)) FAIL("negation operand");
    }
    if (a->ty != TY_INT && a->ty != TY_FLT) FAIL("negation operand");
    if (a->kind == EK_K && !materialize(c, p)) return 0;
    int dl;
    if (!fuse_store(c, pc + (uint32_t)len, p, &dl)) return 0;
    int32_t dst = dl >= 0 ? LOFF(c, dl) : soff(c, p);
    c->xe = gexit(c);
    if (c->xe < 0) FAIL("out of memory");
    EM(a->ty == TY_INT ? ST_ineg : ST_fneg, dst, roff(c, a, p), 0, 0, 0, 0);
    int rty = a->ty;
    c->dep--;
    if (dl >= 0) {
        c->vt[dl] = (uint8_t)(0x80 | rty);
        *skip = 3;
    } else {
        Ent *r = push(c, EK_MEM, rty, 0);
        if (!r) return 0;
        r->ppc = pc;
    }
    return 1;
}

static int do_range_prep(JC *c, uint32_t pc) {
    int s = (int)rd16(c->code + pc + 1);
    int pa = c->dep - 3;
    if (pa < c->d0 || s + 2 >= c->nloc) FAIL("range prep");
    if (!flush_from(c, c->d0, pa)) return 0;
    for (int i = 0; i < 3; i++)
        if (!need(c, pa + i, TY_INT)) FAIL("range arguments");
    Ent *st = &c->st[pa + 2];
    if (s < 256) c->rstep[s] = 3;
    if (st->kind == EK_K) {
        int64_t sv = c->kt[st->idx].as.i;
        if (sv == 0) FAIL("zero step");
        if (s < 256 && c->cur_ic == 0 && sv >= INT32_MIN && sv <= INT32_MAX) {
            c->rstep[s] = sv > 0 ? 1 : 2;
            c->rstep_imm[s] = (int32_t)sv;
        }
    } else {
        c->xe = gexit(c);
        if (c->xe < 0) FAIL("out of memory");
        EM(ST_gnz, roff(c, st, pa + 2), 0, 0, 0, 0, 0);
    }
    if (!flush_from(c, pa, pa + 3)) return 0;
    c->xe = -1;
    for (int i = 0; i < 3; i++) EM(ST_mov, LOFF(c, s + i), soff(c, pa + i), 0, 0, 0, 0);
    for (int i = 0; i < 3; i++) c->vt[s + i] = 0x80 | TY_INT;
    c->dep -= 3;
    return 1;
}

static int do_range_next(JC *c, uint32_t pc, uint32_t *skip) {
    int s = (int)rd16(c->code + pc + 1);
    int32_t off = rd32s(c->code + pc + 3);
    if (s + 2 >= c->nloc) FAIL("range next");
    for (int i = 0; i < 3; i++) {
        if (!(c->vt[s + i] & 0x80)) c->vlive[s + i] = 1;
        if ((c->vt[s + i] & 0x7f) != TY_INT) FAIL("range state type");
    }
    if (!flush_from(c, c->d0, c->dep)) return 0;
    int dl;
    c->pin_fuse = 1;
    int fok = fuse_store(c, pc + 7, c->dep, &dl);
    c->pin_fuse = 0;
    if (!fok) return 0;
    int32_t dst = dl >= 0 ? LOFF(c, dl) : soff(c, c->dep);
    if (!set_target(c, pc + 7 + (uint32_t)off, pc, 0)) return 0;
    c->xe = -1;
    int mode = s < 256 && c->cur_ic == 0 ? c->rstep[s] : 3, imm = mode == 1 || mode == 2 ? c->rstep_imm[s] : 0;
    if (mode == 0 && !c->unit && c->base && c->base[s + 2].type == T_INT) {      /* the loop was entered before the region: its step is checked on entry */
        int64_t sv = c->base[s + 2].as.i;
        if (sv != 0 && sv >= INT32_MIN && sv <= INT32_MAX && (!c->eg[s] || c->egv[s] == (int32_t)sv)) {
            c->eg[s] = 1; c->egv[s] = (int32_t)sv;
            mode = sv > 0 ? 1 : 2; imm = (int32_t)sv;
        }
    }
    if (mode == 1 || mode == 2) EM(mode == 1 ? ST_range_up : ST_range_dn, dst, s * 16, imm, 0, 0, 0);
    else EM(ST_range_next, dst, s * 16, 0, 0, 0, 0);
    if (dl >= 0 && dl == c->pin) EM(ST_ldp, dst, 0, 0, 0, 0, 0);
    if (dl >= 0) {
        c->vt[dl] = 0x80 | TY_INT;
        *skip = 3;
    } else {
        Ent *r = push(c, EK_MEM, TY_INT, 0);
        if (!r) return 0;
        r->ppc = pc;
    }
    return 1;
}

static int do_dup(JC *c, int n, uint32_t pc) {
    if (c->dep - n < c->d0) FAIL("stack underflow");
    int base = c->dep - n;
    for (int i = 0; i < n; i++) {
        Ent src = c->st[base + i];
        Ent *e = push(c, src.kind, src.ty, src.idx);
        if (!e) return 0;
        e->hint = src.hint;
        e->ppc = src.kind == EK_MEM ? pc : src.ppc;
        if (src.kind == EK_MEM) {
            c->xe = -1;
            EM(ST_mov, soff(c, c->dep - 1), soff(c, base + i), 0, 0, 0, 0);
        }
    }
    return 1;
}

/* `a and b` / `a or b` used as a value: the tested value stays on the stack on the taken edge (so it is in memory there) and is
 * dropped on the fall-through edge, where the other operand is evaluated into the same slot; the join keeps one value. */
static int do_orpop(JC *c, int op, uint32_t pc) {
    int p = c->dep - 1;
    if (p < c->d0) FAIL("stack underflow");
    int32_t off = rd32s(c->code + pc + 1);
    if (off < 0) FAIL("backward and / or");
    uint32_t tpc = pc + 5 + (uint32_t)off;
    if (!flush_regs(c) || !flush_from(c, c->d0, c->dep)) return 0;
    Ent *e = &c->st[p];
    int jt = op == OP_JUMP_IF_TRUE_OR_POP;
    if (e->ty == TY_INT || e->ty == TY_FLT || e->ty == TY_ARR || e->ty == TY_INST) {      /* always true */
        if (jt) { if (!set_target(c, tpc, pc, 0)) return 0; c->xe = -1; EM(ST_jmp, 0, 0, 0, 0, 0, 0); }
        c->dep--;
        return 1;
    }
    if (!set_target(c, tpc, pc, 0)) return 0;                   /* the model still holds the value: that is the state at the join */
    c->xe = -1;
    EM(e->ty == TY_BOOL ? (jt ? ST_bbr_t : ST_bbr_f) : (jt ? ST_tbr_t : ST_tbr_f), 0, roff(c, e, p), 0, 0, 0, 0);
    c->dep--;
    return 1;
}

/* a comparison whose result is used as a value: ints (all six) and floats (< <= > >=) compare in registers and leave the bool in a register */
static int do_cmp_value(JC *c, int cop, uint32_t pc, int inv) {
    (void)pc;
    int pb = c->dep - 1, pa = c->dep - 2;
    if (pa < c->d0) FAIL("stack underflow");
    if (!c->reg_on || !num_types(c, pa, pb)) FAIL("comparison used as a value");
    int ci = cond_index(cop);
    {
        const Ent *a0 = &c->st[pa], *b0 = &c->st[pb];
        if (!((a0->ty == TY_INT && b0->ty == TY_INT) || (a0->ty == TY_FLT && b0->ty == TY_FLT && ci <= 3))) FAIL("comparison used as a value");
    }
    if (!flush_from(c, c->d0, pa)) return 0;
    Ent *a = &c->st[pa], *b = &c->st[pb];
    if (a->kind == EK_K && b->kind == EK_K) { if (!flush_from(c, pa, pa + 1)) return 0; }
    a = &c->st[pa]; b = &c->st[pb];
    uint32_t ppc = a->ppc;
    Ent ea = *a, eb = *b;
    int ia = pa, ib = pb, ta = a->ty;
    if (ea.kind == EK_K) {
        Ent t = ea; ea = eb; eb = t;
        int ti = ia; ia = ib; ib = ti;
        ci = ci == 0 ? 2 : ci == 1 ? 3 : ci == 2 ? 0 : ci == 3 ? 1 : ci;
    }
    int rr = reg_alloc(c, 0, pa, pb);
    if (rr < 0) FAIL("no register");
    int ok = 1;
    int cc;
    if (ta == TY_INT) {
        int ra = ea.kind == EK_REG ? ea.idx : R_RAX;
        if (ea.kind != EK_REG) ok = x_ldop(c, R_RAX, &ea, ia);
        if (ok) {
            if (eb.kind == EK_REG) ok = x_rr(c, 0, 1, 0x3b, -1, ra, eb.idx);
            else if (eb.kind == EK_K) {
                int64_t k = c->kt[eb.idx].as.i;
                if (k >= INT32_MIN && k <= INT32_MAX) ok = x_rr(c, 0, 1, 0x81, -1, 7, ra) && x_imm32(c, (int32_t)k);
                else ok = x_movi(c, R_RCX, k) && x_rr(c, 0, 1, 0x3b, -1, ra, R_RCX);
            } else if (eb.kind == EK_LOC && eb.idx == c->pin) ok = x_rr(c, 0, 1, 0x3b, -1, ra, R_RBP);
            else ok = x_mem(c, 0, 1, 0x3b, -1, ra, R_R12, roff(c, &eb, ib) + 8);
        }
        static const int icc[6] = {0xc, 0xe, 0xf, 0xd, 0x4, 0x5};      /* l le g ge e ne */
        cc = icc[ci];
    } else {
        int lt = ci == 0 || ci == 1;               /* a < b is b > a: compare in the other order */
        const Ent *x = lt ? &eb : &ea, *y = lt ? &ea : &eb;
        int xp = lt ? ib : ia, yp = lt ? ia : ib;
        int xr = 0;
        if (x->kind == EK_REG) xr = x->idx;
        else ok = x->kind == EK_K ? x_sd_ld(c, 0, R_R13, koff(x->idx) + 8) : x_sd_ld(c, 0, R_R12, roff(c, x, xp) + 8);
        if (ok) {
            if (y->kind == EK_REG) ok = x_rr(c, 0x66, 0, 0x0f, 0x2e, xr, y->idx);
            else ok = x_mem(c, 0x66, 0, 0x0f, 0x2e, xr, y->kind == EK_K ? R_R13 : R_R12, (y->kind == EK_K ? koff(y->idx) : roff(c, y, yp)) + 8);
        }
        static const int fcc[4] = {0x7, 0x3, 0x7, 0x3};                /* above / above-or-equal (false when unordered) */
        cc = fcc[ci];
    }
    if (!ok) return 0;
    if (inv) cc ^= 1;                                                  /* not (a < b): the opposite condition (also right for NaN) */
    uint8_t sb[3] = {0x0f, (uint8_t)(0x90 | cc), 0xc0};                /* setcc al */
    if (!xput(c, sb, 3) || !x_rr(c, 0, 0, 0x0f, 0xb6, rr, R_RAX)) return 0;   /* movzx rr32, al */
    if (ea.kind == EK_REG) reg_put(c, ea.ty == TY_FLT, ea.idx);
    if (eb.kind == EK_REG) reg_put(c, eb.ty == TY_FLT, eb.idx);
    c->dep -= 2;
    Ent *r = push(c, EK_REG, TY_BOOL, rr);
    if (!r) return 0;
    r->ppc = ppc;
    return 1;
}

static int do_jump(JC *c, uint32_t pc) {
    int32_t off = rd32s(c->code + pc + 1);
    uint32_t tpc = pc + 5 + (uint32_t)off;
    if (!flush_from(c, c->d0, c->dep)) return 0;
    int inside = tpc >= c->hdr && tpc < c->end && c->lmap[tpc - c->hdr] >= 0;
    if (off < 0 && inside) {
        int x = exit_for(c, pc, c->dep);
        if (x < 0) FAIL("out of memory");
        if (!set_target(c, tpc, pc, 0)) return 0;
        c->xe = x;
        EM(ST_tick, (int32_t)offsetof(VM, ileft), 0, 0, 0, 0, 0);
        return 1;
    }
    if (!set_target(c, tpc, pc, off < 0)) return 0;
    c->xe = -1;
    EM(ST_jmp, 0, 0, 0, 0, 0, 0);
    return 1;
}

/* the local worth mirroring in rbp: the most used one that is written in the region and is not a loop-state slot */
static int pick_pin(const JC *c) {
    int n = c->nloc;
    if (n <= 0) return -1;
    int *sc = calloc((size_t)n * 3, sizeof *sc);        /* loads, stores, excluded */
    if (!sc) return -1;
    uint32_t pc = c->hdr;
    while (pc < c->end) {
        int op = c->code[pc], len = op_len(op);
        if (len <= 0) { free(sc); return -1; }
        int lo = op == OP_LOAD_LOCAL || op == OP_STORE_LOCAL;
        int st = op == OP_FOR_NEXT || op == OP_RANGE_PREP || op == OP_RANGE_NEXT || op == OP_FOR_PREP;
        if ((lo || st) && len >= 3) {
            unsigned i = rd16(c->code + pc + 1);
            if (lo && i < (unsigned)n) sc[i * 3 + (op == OP_STORE_LOCAL)]++;
            else if (st)
                for (unsigned j = i; j < i + 3 && j < (unsigned)n; j++) sc[j * 3 + 2] = 1;
        }
        pc += (uint32_t)len;
    }
    int best = -1, bs = 0;
    for (int i = 0; i < n; i++) {
        if (sc[i * 3 + 2] || !sc[i * 3 + 1] || !sc[i * 3]) continue;
        int s = sc[i * 3] + 2 * sc[i * 3 + 1];
        if (s > bs) { bs = s; best = i; }
    }
    free(sc);
    return best;
}

/* the instructions whose handlers understand register entries (every other one is preceded by flush_regs) */
static int reg_aware(int op) {
    switch (op) {
    case OP_NOP: case OP_CONST: case OP_SMALLINT: case OP_NIL: case OP_TRUE: case OP_FALSE: case OP_POP: case OP_LOAD_LOCAL:
    case OP_STORE_LOCAL: case OP_ADD: case OP_SUB: case OP_MUL: case OP_DIV: case OP_FLOOR_DIV: case OP_MOD:
    case OP_GET_MEMBER: case OP_GET_INDEX: case OP_SET_MEMBER: case OP_SET_INDEX:
    case OP_EQ: case OP_NE: case OP_LT: case OP_LE: case OP_GT: case OP_GE: case OP_INVOKE:
    case OP_LOAD_UPVAL: case OP_STORE_UPVAL: case OP_LOAD_MODULE: case OP_STORE_MODULE:
        return 1;
    default:
        return 0;
    }
}

static int walk(JC *c) {
    c->rb = c->xb = 0; c->nlc = 0;
    memset(c->rstep, 0, sizeof c->rstep);
    c->cn = 0;
    c->nfx = 0;
    c->nex = 0;
    c->nk = c->nk0;
    c->why = NULL;
    memset(c->pcaddr, 0xff, ((size_t)(c->end - c->hdr) + 1) * sizeof(uint32_t));
    memset(c->vlive, 0, (size_t)c->nvars);
    if (exit_for(c, c->hdr, c->d0) != 0) FAIL("out of memory");
    memcpy(c->vt, lstate(c, 0), (size_t)c->nvars);
    c->rax_off = -1;
    c->xmm_off = -1;
    c->skip1 = 0;
    c->skipx = 0;
    c->dep = 0;
    c->nic = 0;
    c->cur_ic = 0;
    c->bias = 0;
    c->pos0 = 0;
    for (int i = 0; i < c->d0; i++) { Ent *e = push(c, EK_MEM, TY_UNK, 0); if (!e) return 0; }
    int reach = 1;
    uint32_t pc = c->hdr;
    while (pc < c->end) {
        int op = c->code[pc];
        int len = op_len(op);
        if (len <= 0) FAIL("bad instruction");
        int li = c->lmap[pc - c->hdr];
        if (li >= 0) {
            if (reach && (!flush_regs(c) || !flush_from(c, c->d0, c->dep) || !merge_to(c, pc))) return 0;
            if (!c->lvalid[li]) { pc += (uint32_t)len; reach = 0; continue; }
            memcpy(c->vt, lstate(c, li), (size_t)c->nvars);
            c->rax_off = -1;
            c->xmm_off = -1;
            c->dep = c->d0;
            for (int k = 0; k < c->ldep[li]; k++) { Ent *je = push(c, EK_MEM, TY_UNK, 0); if (!je) return 0; je->ppc = pc; }
            c->rb = c->xb = 0; c->nlc = 0;
            reach = 1;
            c->pcaddr[pc - c->hdr] = (uint32_t)c->cn;
        } else if (!reach) {
            pc += (uint32_t)len;
            continue;
        }
        c->cur_pc = pc;
        uint32_t skip = 0;
        int ok = 1;
        if ((c->rb || c->xb) && !reg_aware(op) && !flush_regs(c)) return 0;
        switch (op) {
        case OP_NOP: break;
        case OP_CONST: {
            unsigned k = rd16(c->code + pc + 1);
            if (k >= (unsigned)c->p->nconsts) FAIL("bad constant");
            Ent *e = push(c, EK_K, ty_of(&c->p->consts[k], 0), (int)k);
            ok = e != NULL;
            if (ok) e->hint = &c->p->consts[k];
            break;
        }
        case OP_SMALLINT: case OP_NIL: case OP_TRUE: case OP_FALSE: {
            SpValue v = op == OP_SMALLINT ? v_int((int16_t)rd16(c->code + pc + 1)) : op == OP_NIL ? v_nil() : v_bool(op == OP_TRUE);
            int k = kadd(c, v);
            if (k < 0) FAIL("too many constants");
            Ent *e = push(c, EK_K, ty_of(&v, 0), k);
            ok = e != NULL;
            break;
        }
        case OP_POP:
            if (c->dep <= c->d0) FAIL("stack underflow");
            if (c->st[c->dep - 1].kind == EK_REG) reg_put(c, reg_is_x(&c->st[c->dep - 1]), c->st[c->dep - 1].idx);
            c->dep--;
            break;
        case OP_DUP: ok = do_dup(c, 1, pc); break;
        case OP_DUP2: ok = do_dup(c, 2, pc); break;
        case OP_LOAD_LOCAL: {
            unsigned i = rd16(c->code + pc + 1);
            if (i >= (unsigned)c->nloc) FAIL("bad local");
            if (!(c->vt[i] & 0x80)) c->vlive[i] = 1;
            Ent *e = push(c, EK_LOC, c->vt[i] & 0x7f, (int)i);
            ok = e != NULL;
            if (ok) { e->hint = &c->base[i]; if (e->ty == TY_INST) e->cls = c->vk[i]; }
            break;
        }
        case OP_STORE_LOCAL: ok = do_store_local(c, pc); break;
        case OP_LOAD_MODULE: ok = do_load_module(c, pc); break;
        case OP_STORE_MODULE: ok = do_store_module(c, pc); break;
        case OP_ADD: case OP_SUB: case OP_MUL: case OP_DIV: case OP_FLOOR_DIV: case OP_MOD:
            ok = do_arith(c, op, pc, len, &skip);
            break;
        case OP_NEG: ok = do_neg(c, pc, len, &skip); break;
        case OP_EQ: case OP_NE: case OP_LT: case OP_LE: case OP_GT: case OP_GE: {
            uint32_t npc = pc + 1;
            int inv = 0, jop;
            uint32_t tpc;
            if (npc < c->end && c->code[npc] == OP_NOT && c->lmap[npc - c->hdr] < 0) { inv = 1; npc++; }
            if (npc >= c->end || c->lmap[npc - c->hdr] >= 0 || !branch_info(c->code, c->p->code_len, npc, &jop, &tpc)) {
                ok = do_cmp_value(c, op, pc, inv);
                if (inv) skip = 1;
                break;
            }
            if (inv) jop = jop == OP_JUMP_IF_FALSE ? OP_JUMP_IF_TRUE : OP_JUMP_IF_FALSE;
            if ((op == OP_EQ || op == OP_NE) && c->dep - 2 >= c->d0 && c->st[c->dep - 1].kind == EK_K && c->kt[c->st[c->dep - 1].idx].type == T_NIL
                && c->st[c->dep - 2].kind != EK_K) {
                ok = do_nil_branch(c, op, jop, tpc, npc);
                skip = npc + 5 - (pc + 1);
                break;
            }
            ok = do_cmp_branch(c, op, jop, tpc, npc, npc + 5 - (pc + 1), &skip);
            break;
        }
        case OP_NOT: {
            uint32_t npc = pc + 1;
            int jop;
            uint32_t tpc;
            if (npc >= c->end || c->lmap[npc - c->hdr] >= 0 || !branch_info(c->code, c->p->code_len, npc, &jop, &tpc))
                FAIL("not used as a value");
            jop = jop == OP_JUMP_IF_FALSE ? OP_JUMP_IF_TRUE : OP_JUMP_IF_FALSE;
            ok = jump_if(c, jop, tpc, npc);
            skip = 5;
            break;
        }
        case OP_JUMP: ok = do_jump(c, pc); reach = 0; break;
        case OP_JUMP_IF_FALSE: case OP_JUMP_IF_TRUE: case OP_JUMP_IF_FALSE_OR_POP: case OP_JUMP_IF_TRUE_OR_POP: {
            int jop;
            uint32_t tpc;
            if (branch_info(c->code, c->p->code_len, pc, &jop, &tpc)) ok = jump_if(c, jop, tpc, pc);
            else if (op == OP_JUMP_IF_FALSE_OR_POP || op == OP_JUMP_IF_TRUE_OR_POP) ok = do_orpop(c, op, pc);
            else FAIL("and / or used as a value");
            break;
        }
        case OP_GET_INDEX: ok = do_get_index(c, pc, len, &skip); break;
        case OP_CONCAT: ok = do_concat(c, pc); break;
        case OP_SET_INDEX: ok = do_set_index(c, pc); break;
        case OP_INVOKE: ok = do_invoke(c, pc, len, &skip); break;
        case OP_GET_MEMBER: ok = do_get_member(c, pc, len, &skip); break;
        case OP_SET_MEMBER: ok = do_set_member(c, pc); break;
        case OP_RANGE_PREP: ok = do_range_prep(c, pc); break;
        case OP_RANGE_NEXT: ok = do_range_next(c, pc, &skip); break;
        case OP_FOR_NEXT: ok = do_for_next(c, pc, &skip); break;
        case OP_LOAD_LINK: ok = do_load_link(c, pc); break;
        case OP_CALL: ok = do_call(c, pc, len, &skip); break;
        case OP_RETURN: case OP_RETURN_NIL: ok = do_return(c, op); reach = 0; break;
        case OP_LOAD_UPVAL: ok = do_load_upval(c, pc); break;
        case OP_STORE_UPVAL: ok = do_store_upval(c, pc); break;
        default: FAIL("unsupported instruction");
        }
        if (!ok) { if (!c->why) c->why = "translation failed"; return 0; }
        pc += (uint32_t)len + skip;
    }
    if (reach) {
        if (!flush_from(c, c->d0, c->dep)) return 0;
        int x = exit_for(c, c->end, c->dep);
        if (x < 0) FAIL("out of memory");
        c->tk = 1;
        c->tt = x;
        c->xe = -1;
        EM(ST_jmp, 0, 0, 0, 0, 0, 0);
    }
    return 1;
}

/* ------------------------------------------------------------------ */
/* region compilation                                                  */
/* ------------------------------------------------------------------ */
static int op_allowed(int op, int unit) {
    switch (op) {
    case OP_NOP: case OP_CONST: case OP_NIL: case OP_TRUE: case OP_FALSE: case OP_SMALLINT: case OP_POP: case OP_DUP:
    case OP_DUP2: case OP_LOAD_LOCAL: case OP_STORE_LOCAL: case OP_LOAD_MODULE: case OP_STORE_MODULE: case OP_ADD:
    case OP_SUB: case OP_MUL: case OP_DIV: case OP_FLOOR_DIV: case OP_MOD: case OP_NEG: case OP_EQ: case OP_NE:
    case OP_LT: case OP_LE: case OP_GT: case OP_GE: case OP_JUMP: case OP_JUMP_IF_FALSE: case OP_JUMP_IF_TRUE:
    case OP_JUMP_IF_FALSE_OR_POP: case OP_JUMP_IF_TRUE_OR_POP: case OP_NOT:
    case OP_GET_INDEX: case OP_SET_INDEX: case OP_INVOKE: case OP_RANGE_PREP: case OP_RANGE_NEXT: case OP_FOR_NEXT: case OP_CONCAT:
    case OP_LOAD_LINK: case OP_CALL: case OP_LOAD_UPVAL: case OP_STORE_UPVAL: case OP_GET_MEMBER: case OP_SET_MEMBER:
        return 1;
    case OP_RETURN: case OP_RETURN_NIL:
        return unit;
    default:
        return 0;
    }
}

static void jc_free(JC *c) {
    free(c->vt); free(c->vk); free(c->vlive); free(c->lt); free(c->lvalid); free(c->ldep); free(c->lmap); free(c->isins); free(c->st);
    free(c->lrd); free(c->cb); free(c->fx); free(c->pcaddr); free(c->ex); free(c->kt); free(c->ic);
}

static int jc_setup(JC *c, uint32_t len) {
    size_t n = (size_t)len + 1;
    c->lmap = malloc(n * sizeof(int));
    c->isins = calloc(n, 1);
    c->pcaddr = malloc(n * sizeof(uint32_t));
    c->stcap = c->p->max_stack + 4 + INL_MAXLOC + 16;
    c->st = malloc((size_t)c->stcap * sizeof *c->st);
    c->kt = malloc(((size_t)c->p->nconsts + MAXEXTRA) * sizeof *c->kt);
    if (!c->lmap || !c->isins || !c->pcaddr || !c->st || !c->kt) return 0;
    for (size_t i = 0; i < n; i++) c->lmap[i] = -1;
    if (c->p->nconsts > 0) memcpy(c->kt, c->p->consts, (size_t)c->p->nconsts * sizeof *c->kt);
    c->nk = c->nk0 = c->p->nconsts;
    c->capk = c->p->nconsts + MAXEXTRA;
    return 1;
}

static int compile_region(VM *vm, Proto *p, JRegion *r, SFunc *fn, SpValue *base, int depth) {
    JC cs;
    memset(&cs, 0, sizeof cs);
    JC *c = &cs;
    c->vm = vm;
    c->p = p;
    c->fn = fn;
    c->unit = r->unit;
    c->region = r;
    c->code = p->ocode ? p->ocode : p->code;
    c->hdr = r->hdr;
    if (inl_enabled < 0) { const char *ei = getenv("SPRINT_JIT_INLINE"); inl_enabled = !(ei && ei[0] == '0'); }
    c->nloc = p->nlocals;
    c->pin = -1;
    c->pin_fuse = 0;
    { const char *er = getenv("SPRINT_JIT_REGS"); c->reg_on = !(er && er[0] == '0'); }
    c->d0 = depth;
    c->base = base;
    int ok = 0, nstub = 0, eok = 1;
    uint8_t *mem = NULL;
    size_t msize = 0;
    uint32_t n = p->code_len, end = 0, entry_off = 0, tramp_off = 0;
    uint32_t *stub = NULL;
    long pg = 0;
    void *fp = NULL;

    if (c->unit) {
        end = n;                                   /* a function: the whole body */
        if (n == 0) { c->why = "empty function"; goto done; }
    } else {
        /* extent of the loop: the last backward jump that targets the header */
        for (uint32_t pc = c->hdr; pc < n;) {
            int op = c->code[pc], len = op_len(op);
            if (len <= 0) break;
            if (op == OP_JUMP) {
                int32_t off = rd32s(c->code + pc + 1);
                if (off < 0 && pc + 5 + (uint32_t)off == c->hdr) end = pc + 5;
            }
            pc += (uint32_t)len;
        }
        if (end == 0) { c->why = "no back edge"; goto done; }
    }
    c->end = end;
    if (end - c->hdr > 6000) { c->why = "region too large"; goto done; }
    if (!jc_setup(c, end - c->hdr)) { c->why = "out of memory"; goto done; }

    /* prescan: instruction starts, supported opcodes, leaders, module variables */
    for (uint32_t pc = c->hdr; pc < end;) {
        int op = c->code[pc], len = op_len(op);
        if (len <= 0 || pc + (uint32_t)len > end) { c->why = "bad instruction"; goto done; }
        c->isins[pc - c->hdr] = 1;
        if (!op_allowed(op, c->unit)) { (void)snprintf(c->whybuf, sizeof c->whybuf, "unsupported op 0x%02x", (unsigned)op); c->why = c->whybuf; goto done; }
        if (op == OP_LOAD_MODULE || op == OP_STORE_MODULE) {
            int slot = (int)rd16(c->code + pc + 1), f = 0;
            for (int i = 0; i < c->nmv; i++) if (c->mslot[i] == slot) f = 1;
            if (!f) {
                if (c->nmv >= MAXMV) { c->why = "too many module variables"; goto done; }
                c->mslot[c->nmv++] = slot;
            }
        }
        pc += (uint32_t)len;
    }
    c->lmap[0] = c->nl++;
    for (uint32_t pc = c->hdr; pc < end;) {
        int op = c->code[pc], len = op_len(op);
        int64_t t = -1;
        if (op == OP_JUMP) t = (int64_t)pc + 5 + rd32s(c->code + pc + 1);
        else if (op == OP_JUMP_IF_FALSE || op == OP_JUMP_IF_TRUE || op == OP_JUMP_IF_FALSE_OR_POP || op == OP_JUMP_IF_TRUE_OR_POP) {
            int jop;
            uint32_t tp;
            if (branch_info(c->code, c->p->code_len, pc, &jop, &tp)) t = tp;
            else if ((op == OP_JUMP_IF_FALSE_OR_POP || op == OP_JUMP_IF_TRUE_OR_POP) && pc + 5 <= c->p->code_len && rd32s(c->code + pc + 1) >= 0)
                t = (int64_t)pc + 5 + rd32s(c->code + pc + 1);     /* a value-producing and / or: the join keeps the value */
            else { c->why = "and / or used as a value"; goto done; }
        }
        else if (op == OP_RANGE_NEXT) t = (int64_t)pc + 7 + rd32s(c->code + pc + 3);
        else if (op == OP_FOR_NEXT) t = (int64_t)pc + 8 + rd32s(c->code + pc + 4);
        if (t >= (int64_t)c->hdr && t < (int64_t)end) {
            if (!c->isins[(uint32_t)t - c->hdr]) { c->why = "branch into an instruction"; goto done; }
            if (c->lmap[(uint32_t)t - c->hdr] < 0) c->lmap[(uint32_t)t - c->hdr] = c->nl++;
        }
        pc += (uint32_t)len;
    }
    c->nvars = c->nloc + c->nmv;
    c->vt = calloc((size_t)c->nvars, 1);
    c->vlive = calloc((size_t)c->nvars, 1);
    c->vk = calloc((size_t)c->nvars, sizeof *c->vk);
    c->lt = calloc((size_t)c->nl * (size_t)c->nvars, 1);
    c->lvalid = calloc((size_t)c->nl, 1);
    c->ldep = malloc((size_t)c->nl);
    if (c->ldep) memset(c->ldep, 0xff, (size_t)c->nl);
    if (!c->vt || !c->vlive || !c->vk || !c->lt || !c->lvalid || !c->ldep) { c->why = "out of memory"; goto done; }
    for (int i = 0; i < c->nloc; i++) {
        if (c->unit && i >= p->nparams) { lstate(c, 0)[i] = TY_UNK; continue; }
        if (base[i].type == T_INSTANCE) { lstate(c, 0)[i] = TY_INST; c->vk[i] = AS_INSTANCE(base[i])->cls; continue; }
        lstate(c, 0)[i] = (uint8_t)ty_of(&base[i], 0);
    }
    for (int i = 0; i < c->nmv; i++) {
        const SpValue *mv = &vm->slots[c->mslot[i]];
        if (mv->type == T_INSTANCE && c->reg_on) { lstate(c, 0)[c->nloc + i] = TY_INST; c->vk[c->nloc + i] = AS_INSTANCE(*mv)->cls; continue; }   /* an instance variable keeps its class (checked on entry) */
        lstate(c, 0)[c->nloc + i] = (uint8_t)ty_of(mv, 1);
    }
    c->lvalid[0] = 1;

    c->lrd = calloc((size_t)(p->nlocals > 0 ? p->nlocals : 1), 1);
    if (c->lrd && c->reg_on) {
        for (uint32_t q = c->hdr; q < c->end;) {
            int o = c->code[q], l = op_len(o);
            if (l <= 0) break;
            if (o == OP_LOAD_LOCAL && q + 3 <= c->end) {
                unsigned li = rd16(c->code + q + 1);
                if (li < (unsigned)p->nlocals && c->lrd[li] < 255) c->lrd[li]++;
            }
            q += (uint32_t)l;
        }
    }
    { const char *np = getenv("SPRINT_JIT_PIN"); c->pin = np && np[0] == '0' ? -1 : pick_pin(c); }
    for (int round = 0;; round++) {
        if (round > 16) { c->why = "no fixpoint"; goto done; }
        c->changed = 0;
        if (!walk(c)) goto done;
        if (!c->changed) break;
    }

    if (c->pin >= 0) {                      /* rbp only pays off for an integer that is an integer everywhere */
        int allint = 1;
        for (int li = 0; li < c->nl; li++)
            if (c->lvalid[li] && (lstate(c, li)[c->pin] & 0x7f) != TY_INT) allint = 0;
        if (!allint) {
            c->pin = -1;
            if (!walk(c)) goto done;
        }
    }

    /* stubs, entry guards, fixups */
    nstub = c->nex;
    stub = malloc((size_t)(nstub + 1) * sizeof *stub);
    if (!stub) { c->why = "out of memory"; goto done; }
    c->xe = -1;
    for (int i = 0; i < nstub; i++) {
        stub[i] = (uint32_t)c->cn;
        if (!em(c, ST_exit, i, 0, 0, 0, 0, (uint64_t)(uintptr_t)r)) { free(stub); goto done; }
    }
    entry_off = (uint32_t)c->cn;
    eok = em(c, c->unit ? (c->pin >= 0 ? ST_ufn_p : ST_ufn) : ST_entry, 0, 0, 0, 0, 0, 0);
    c->xe = 0;
    for (int v = 0; eok && v < c->nvars; v++) {
        int ty = lstate(c, 0)[v] & 0x7f;
        if (!c->vlive[v] || ty == TY_UNK) continue;
        if (v < c->nloc && ty == TY_INST) {
            eok = em(c, ST_gcls, v * 16, 0, 0, 0, 0, (uint64_t)(uintptr_t)c->vk[v]);
        } else if (v < c->nloc) {
            eok = em(c, ST_gtag, v * 16, (int32_t)tag_of(ty), 0, 0, 0, 0);
        } else {
            int slot = c->mslot[v - c->nloc];
            if (ty == TY_INST) {
                int kx = kadd(c, v_obj(T_CLASS, (Obj *)(uintptr_t)c->vk[v]));      /* the class lives as long as the code that compares with it */
                if (kx < 0) { c->why = "too many constants"; free(stub); goto done; }
                eok = em(c, ST_gcls_mod, slot * 16, 0, 0, 0, 0, (uint64_t)(uintptr_t)c->vk[v]);
                continue;
            }
            eok = em(c, ST_gtag_mod, slot * 16, (int32_t)tag_of(ty), 0, 0, 0, 0);
            if (eok && ty == TY_MOD) {
                uint64_t ptr = (uint64_t)(uintptr_t)vm->slots[slot].as.o;
                eok = em(c, ST_gobj_mod, slot * 16, 0, 0, 0, 0, ptr);
            }
        }
    }
    for (int si = 0; eok && si < 256; si++)
        if (c->eg[si]) eok = em(c, ST_gimm, (si + 2) * 16, c->egv[si], 0, 0, 0, 0);
    if (eok && c->pin >= 0) { c->xe = -1; eok = em(c, ST_ldp, c->pin * 16, 0, 0, 0, 0, 0); }
    if (eok) {
        c->tk = 0;
        c->tt = (int)c->hdr;
        c->xe = -1;
        eok = em(c, ST_jmp, 0, 0, 0, 0, 0, 0);
    }
    if (eok && c->unit) {                         /* the entry used by the interpreter: calls ufn */
        tramp_off = (uint32_t)c->cn;
        c->tk = 2;
        c->tt = (int)entry_off;
        c->xe = -1;
        eok = em(c, ST_utramp, 0, 0, 0, 0, 0, 0);
    }
    if (!eok) { free(stub); goto done; }
    for (int i = 0; i < c->nfx; i++) {
        const Fix *f = &c->fx[i];
        uint32_t tgt;
        if (f->kind == 0) {
            tgt = c->pcaddr[(uint32_t)f->target - c->hdr];
            if (tgt == 0xffffffffu) { c->why = "branch to unreachable code"; free(stub); goto done; }
        } else if (f->kind == 2) {
            tgt = (uint32_t)f->target;
        } else if (f->kind == 3) {
            tgt = entry_off;                   /* the function's own entry */
        } else {
            tgt = stub[f->target];
        }
        int32_t rel = (int32_t)((int64_t)tgt + f->addend - (int64_t)f->pos);
        memcpy(c->cb + f->pos, &rel, 4);
    }
    free(stub);
    pg = sysconf(_SC_PAGESIZE);
    if (pg <= 0) pg = 4096;
    msize = (c->cn + (size_t)pg - 1) / (size_t)pg * (size_t)pg;
    mem = mmap(NULL, msize, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (mem == MAP_FAILED) { mem = NULL; c->why = "mmap failed"; goto done; }
    memcpy(mem, c->cb, c->cn);
    if (mprotect(mem, msize, PROT_READ | PROT_EXEC) != 0) { munmap(mem, msize); mem = NULL; c->why = "mprotect failed"; goto done; }
    {   /* developer aid: SPRINT_JIT_DUMP=file appends every compiled region's bytes (objdump -D -b binary -mi386:x86-64) */
        const char *dump = getenv("SPRINT_JIT_DUMP");
        FILE *df = dump ? fopen(dump, "ab") : NULL;
        if (df) { (void)fwrite(c->cb, 1, c->cn, df); (void)fclose(df); }
    }
    r->mem = mem;
    r->msize = msize;
    fp = mem + (c->unit ? tramp_off : entry_off);
    memcpy(&r->fn, &fp, sizeof fp);
    if (c->unit) {
        r->u.entry = mem + entry_off;
        r->u.tramp = r->fn;
        r->u.code = p->code;
        r->u.nparams = p->nparams;
        r->u.nlocals = p->nlocals;
        r->u.need = ((int64_t)p->nlocals + p->max_stack + 8) * 16;
        r->u.owner = r;
        r->u.proto = p;
        r->u.kt = c->kt;
    }
    r->proto = p;
    r->nk0 = c->nk0;
    r->nk = c->nk;
    r->kt = c->kt;
    c->kt = NULL;
    r->exits = c->ex;
    c->ex = NULL;
    r->nexits = c->nex;
    r->ictx = c->ic;
    c->ic = NULL;
    r->nictx = c->nic;
    r->inl_extent = c->inl_extent;
    r->d0 = depth;
    ok = 1;
done:
    if (vm->jit_dbg) {
        if (ok) (void)fprintf(stderr, "jit: %s %s @%u..%u ok (%zu bytes)\n", c->unit ? "function" : "loop", p->name ? p->name : "?", c->hdr, c->end, c->cn);
        else (void)fprintf(stderr, "jit: %s %s @%u failed: %s\n", c->unit ? "function" : "loop", p->name ? p->name : "?", c->hdr, c->why ? c->why : "?");
    }
    jc_free(c);
    return ok;
}

/* ------------------------------------------------------------------ */
/* entry from the interpreter                                          */
/* ------------------------------------------------------------------ */

/* Compiled code has left (exit `id`, possibly deep inside native calls): point the interpreter at the instruction the
 * exit names, in the innermost frame. */
static void jit_finish(VM *vm, int id) {
    const JRegion *x = vm->jit_cur;
    const JExit *e = &x->exits[id];
    Frame *f = &vm->frames[vm->nframes - 1];
    Proto *fp = f->fn->proto;
    if (vm->jit_dbg > 1) {
        int nd = 0;
        for (int i = e->ictx - 1; i >= 0 && nd < 4; i = x->ictx[i].parent) nd++;
        (void)fprintf(stderr, "jit: exit %d -> %s pc %u depth %d%s%s\n", id, fp->name ? fp->name : "?", e->pc, e->depth,
                      e->ictx ? " (inlined callee)" : "", nd > 1 ? " (nested)" : "");
    }
    if (e->ictx) {                       /* the exit lies in inlined callees (outermost first): build the frames the calls would have pushed */
        int chain[4], n = 0;
        for (int i = e->ictx - 1; i >= 0 && n < 4; i = x->ictx[i].parent) chain[n++] = i;
        Frame *cur = f;
        const Proto *cp = fp;
        for (int k = n - 1; k >= 0; k--) {
            const JIctx *ic = &x->ictx[chain[k]];
            SpValue *nb = f->base + ic->base_slots;
            cur->pc = cp->code + ic->retpc;
            Frame *nf = cur + 1;
            vm->nframes++;
            nf->fn = AS_FUNC(nb[-1]);
            nf->base = nb;
            nf->kind = ic->ctor ? FK_CTOR : FK_NORMAL;
            nf->uev = ic->ctor ? nb[0] : v_nil();
            nf->dbase = vm->ndr;
            nf->pc = ic->proto->code + e->pc;
            vm->sp = nb + ic->proto->nlocals + e->depth;
            cur = nf;
            cp = ic->proto;
        }
        return;
    }
    f->pc = fp->code + e->pc;
    vm->sp = f->base + fp->nlocals + e->depth;
}

static struct JitProto *jit_proto(Proto *p) {
    struct JitProto *jp = p->jit;
    if (!jp) {
        jp = calloc(1, sizeof *jp);
        if (!jp) return NULL;
        p->jit = jp;
    }
    return jp;
}

int jit_site(VM *vm, Proto *p, const uint8_t *hdr, SpValue *base, SpValue *sp) {
    if (!p->jhot) p->jhot = vm->jit_on ? vm->jit_thresh : 0x3fffffff;   /* first visit: arm the countdown */
    if (!vm->jit_on || p->jhot > 1) return 0;
    struct JitProto *jp = jit_proto(p);
    if (!jp) return 0;
    uint32_t h = (uint32_t)(hdr - p->code);
    JRegion *r = NULL;
    for (int i = 0; i < jp->n; i++) if (jp->r[i]->hdr == h) { r = jp->r[i]; break; }
    if (!r) {
        if (jp->n == jp->cap) {
            int nc = jp->cap ? jp->cap * 2 : 4;
            JRegion **t = realloc(jp->r, (size_t)nc * sizeof *t);
            if (!t) return 0;
            jp->r = t;
            jp->cap = nc;
        }
        r = calloc(1, sizeof *r);
        if (!r) return 0;
        jp->r[jp->n++] = r;
        r->hdr = h;
        r->state = JS_NEW;
    }
    SpValue *stk = base + p->nlocals;
    if (r->state == JS_NEW) {
        if (++r->cnt < vm->jit_thresh) return 0;
        r->state = compile_region(vm, p, r, vm->frames[vm->nframes - 1].fn, base, (int)(sp - stk)) ? JS_OK : JS_FAIL;
        if (r->state == JS_OK) jp->nok++;
    }
    if (r->state != JS_OK) {
        /* a loop the JIT cannot take: consult it only now and then (the interpreter keeps its full speed) */
        if (!jp->nok) p->jhot = 1500;
        return 0;
    }
    if ((int)(sp - stk) != r->d0) return 0;
    Frame *fr = &vm->frames[vm->nframes - 1];
    int fm = vm->nframes + 3000;
    vm->jit_fmax = fm < vm->max_frames - 1 ? fm : vm->max_frames - 1;
    /* inlined calls build their frames only when they are left: the room they would need is checked here, once */
    if (r->inl_extent && (vm->nframes >= vm->jit_fmax || (char *)base + r->inl_extent > (char *)vm->stack_end)) return 0;
    uint64_t before = vm->ileft;
    int id = r->fn(vm, base, r->kt, fr);
    r->nent++;
    r->work += before - vm->ileft;
    /* a region that keeps being left at once (a call it cannot make, a guard that fails) costs more than it gains */
    if (r->nent == 64 && r->work < 2u * 64u) r->state = JS_FAIL;
    jit_finish(vm, id);
    return 1;
}

JitUnit *jit_call_hot(VM *vm, SFunc *fn, SpValue *base) {
    Proto *p = fn->proto;
    if (!p->jcall) p->jcall = vm->jit_on ? vm->jit_thresh : 0x3fffffff;   /* first visit: arm the countdown */
    if (p->junit) return p->junit;
    if (!vm->jit_on || p->jcall > 1) return NULL;
    p->jcall = 0x3fffffff;                                                /* one attempt only */
    if (p->nparams != p->nrequired || p->has_rest || p->ndefaults != 0) return NULL;
    struct JitProto *jp = jit_proto(p);
    if (!jp || jp->unit) return NULL;
    JRegion *r = calloc(1, sizeof *r);
    if (!r) return NULL;
    r->unit = 1;
    r->hdr = 0;
    if (!compile_region(vm, p, r, fn, base, 0)) {
        free(r);
        return NULL;
    }
    jp->unit = r;
    r->state = JS_OK;
    p->junit = &r->u;
    return p->junit;
}

void jit_run(VM *vm, JitUnit *u, SpValue *base) {
    JRegion *r = u->owner;
    Frame *fr = &vm->frames[vm->nframes - 1];
    int fm = vm->nframes + 3000;
    vm->jit_fmax = fm < vm->max_frames - 1 ? fm : vm->max_frames - 1;
    int id = u->tramp(vm, base, u->kt, fr);
    if (id < 0) {                       /* returned: the result sits below the base, the frame is gone */
        vm->sp = base;
        r->oks++;
        return;
    }
    if (id == 0 && ++r->fails > 64 && r->fails > r->oks) {   /* it keeps refusing its callers' arguments */
        r->proto->junit = NULL;
        r->proto->jcall = 0x3fffffff;
    }
    jit_finish(vm, id);
}

#endif
